def make_live21_rollback_authorization(
    *,
    mission_id: str,
    conflict_id: str,
    capability: Live21CapabilityInventoryItem,
    surviving_capability_ids: tuple[str, ...],
    issued_sequence: int = 1300,
    expiration_sequence: int = 1320,
    consumed: bool = False,
    revoked: bool = False,
) -> Live21RollbackAuthorization:
    return Live21RollbackAuthorization(
        authorization_id=stable_id("live21-rollback-authorization", mission_id, conflict_id, capability.capability_id, issued_sequence),
        mission_id=mission_id,
        conflict_id=conflict_id,
        exact_capability_id=capability.capability_id,
        exact_affected_paths=capability.affected_paths,
        pre_rollback_digests=(capability.evidence_digest,),
        rollback_target=capability.rollback_identity,
        surviving_capability_ids=surviving_capability_ids,
        validation_commands=("py_compile", "LIVE-21 focused rollback validation"),
        issued_sequence=issued_sequence,
        expiration_sequence=expiration_sequence,
        operator_identity="operator",
        one_use_token=stable_id("live21-rollback-token", mission_id, conflict_id, capability.capability_id, issued_sequence),
        consumed=consumed,
        revoked=revoked,
    )


def run_live21_conflict_rollback_recovery(
    state: OARRuntimeState,
    *,
    mission_id: str = "live21-capability-conflict-rollback",
    reproduce_conflict: bool = True,
    rollback_authorized: bool = True,
    rollback_scope_expanded: bool = False,
    rollback_failure: bool = False,
    restart_recovery: bool = False,
    replay_rollback: bool = False,
    actual_duration_minutes: float = 16.0,
) -> Live21ConflictRecoveryResult:
    if state.development_runtime_mode not in ("stopped", "paused", "idle"):
        return Live21ConflictRecoveryResult(False, "runtime_not_at_clean_boundary", state, mission_id, (), "", "", "", "", (), (), (), None, (), "", (), False, False, False, actual_duration_minutes=actual_duration_minutes)
    inventory = make_live21_capability_inventory()
    earlier = tuple(item.capability_id for item in inventory[:2])
    suspect = inventory[-1]
    if not reproduce_conflict:
        return Live21ConflictRecoveryResult(True, "no_reproducible_capability_conflict", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), mission_id, inventory, "", "none", "no incorrect transition reproduced", "", (), ("contextual-analysis", "source-normalization"), ("operator-facing summary prepared",), None, tuple(item.capability_id for item in inventory if item.active), "", ("baseline composition remained stable",), restart_recovery, True, True, actual_duration_minutes=actual_duration_minutes)

    conflict_id = stable_id("live21-conflict", mission_id, suspect.capability_id, "unsupported-confidence-increase")
    first_transition = "source-assisted uncertainty -> experimental confidence amplifier -> unsupported confidence increase"
    auth = make_live21_rollback_authorization(mission_id=mission_id, conflict_id=conflict_id, capability=suspect, surviving_capability_ids=earlier)
    if not rollback_authorized:
        auth = replace(auth, revoked=True)
    if rollback_scope_expanded:
        auth = replace(auth, exact_affected_paths=auth.exact_affected_paths + ("DELTA.py",))
    if replay_rollback:
        auth = replace(auth, consumed=True)

    if auth.revoked:
        return Live21ConflictRecoveryResult(False, "rollback_authorization_revoked", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), mission_id, inventory, conflict_id, "unsupported_confidence_increase", first_transition, suspect.capability_id, ("confidence-reporting",), ("source-normalization",), ("source-normalization completed while suspect branch paused",), auth, earlier, "", ("suspect capability frozen",), False, False, True, actual_duration_minutes=actual_duration_minutes)
    if auth.consumed:
        return Live21ConflictRecoveryResult(False, "duplicate_rollback_denied", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), mission_id, inventory, conflict_id, "unsupported_confidence_increase", first_transition, suspect.capability_id, ("confidence-reporting",), ("source-normalization",), ("source-normalization completed while suspect branch paused",), auth, earlier, "", ("rollback replay rejected",), False, True, True, actual_duration_minutes=actual_duration_minutes)
    if tuple(auth.exact_affected_paths) != suspect.affected_paths:
        return Live21ConflictRecoveryResult(False, "rollback_scope_expansion_denied", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), mission_id, inventory, conflict_id, "rollback_scope_leak", first_transition, suspect.capability_id, ("confidence-reporting",), ("source-normalization",), ("source-normalization completed while suspect branch paused",), auth, earlier, "", ("scope expansion blocked",), False, False, True, actual_duration_minutes=actual_duration_minutes)
    if rollback_failure:
        return Live21ConflictRecoveryResult(False, "rollback_integrity_failure", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), mission_id, inventory, conflict_id, "unsupported_confidence_increase", first_transition, suspect.capability_id, ("confidence-reporting",), ("source-normalization",), ("source-normalization completed while suspect branch paused",), auth, earlier, "", ("rollback could not prove trustworthy state",), False, False, True, unresolved_integrity=True, actual_duration_minutes=actual_duration_minutes)

    consumed_auth = replace(auth, consumed=True)
    updated = replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False if restart_recovery else state.automatic_resume_performed)
    return Live21ConflictRecoveryResult(
        True,
        "capability_conflict_rollback_recovered",
        updated,
        mission_id,
        inventory,
        conflict_id,
        "unsupported_confidence_increase",
        first_transition,
        suspect.capability_id,
        ("confidence-reporting",),
        ("source-normalization", "operator-summary"),
        ("source-normalization completed while confidence-reporting was paused", "operator-summary retained mission wording"),
        consumed_auth,
        earlier,
        suspect.capability_id,
        ("later capability inactive", "earlier capabilities active", "mission resumed from clean checkpoint"),
        restart_recovery,
        True,
        True,
        actual_duration_minutes=actual_duration_minutes,
    )


def _live22_checkpoint_chain(mission_id: str, exact_mission: str) -> tuple[Live20CheckpointRecord, ...]:
    checkpoints: list[Live20CheckpointRecord] = []
    previous_digest = stable_id("live22-root", mission_id, exact_mission)
    for sequence, checkpoint_type, states, pending in (
        (1, "mission_checkpoint", {"analysis": "ready", "tool-call": "ready"}, ()),
        (2, "completed_tool_call", {"analysis": "completed", "tool-call": "completed", "source-call": "ready"}, ()),
        (3, "pending_operator_question", {"analysis": "completed", "operator-question": "blocked_operator_decision", "independent-summary": "completed"}, ("live22-question-1",)),
        (4, "restart_recovery", {"analysis": "completed", "operator-question": "completed", "capability": "pending_application_authorization"}, ()),
        (5, "uncertain_state_denied", {"analysis": "completed", "uncertain-provider-call": "recovery_reconciliation_required"}, ()),
    ):
        checkpoint = _live20_checkpoint(
            mission_id=mission_id,
            sequence=sequence,
            checkpoint_type=checkpoint_type,
            work_item_states=states,
            evidence_digests=(previous_digest, stable_id("live22-evidence", mission_id, sequence, checkpoint_type)),
            pending_question_ids=pending,
            cumulative_budget={"runtime_cycles": float(sequence), "cost": 0.0, "restart_count": float(min(sequence - 1, 3))},
        )
        checkpoints.append(checkpoint)
        previous_digest = checkpoint.integrity_digest
    return tuple(checkpoints)


def _live22_checkpoints_valid(checkpoints: tuple[Live20CheckpointRecord, ...]) -> bool:
    return bool(checkpoints) and tuple(checkpoint.sequence for checkpoint in checkpoints) == tuple(range(1, len(checkpoints) + 1)) and all(checkpoint.integrity_digest for checkpoint in checkpoints)


def run_live22_persistent_restart_recovery_campaign(
    state: OARRuntimeState,
    *,
    mission_id: str = "live22-persistent-restart-recovery",
    exact_mission: str = "Continue a bounded contextual-language or technical-diagnosis campaign across repeated runtime sessions.",
    invalid_checkpoint: bool = False,
    uncertain_state: bool = False,
    duplicate_call_attempt: bool = False,
    restart_count: int = 3,
    actual_duration_minutes: float = 14.0,
) -> Live22RecoveryCampaignResult:
    if state.development_runtime_mode not in ("stopped", "paused", "idle"):
        return Live22RecoveryCampaignResult(False, "runtime_not_at_clean_boundary", state, mission_id, exact_mission, (), 0, (), False, False, False, False, False, False, False, False, False, False, "checkpoint_integrity_failure", actual_duration_minutes=actual_duration_minutes)
    checkpoints = _live22_checkpoint_chain(mission_id, exact_mission)
    if invalid_checkpoint:
        checkpoints = checkpoints[:-1] + (replace(checkpoints[-1], sequence=99),)
    valid = _live22_checkpoints_valid(checkpoints)
    if not valid:
        return Live22RecoveryCampaignResult(False, "checkpoint_integrity_failure", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), mission_id, exact_mission, checkpoints, restart_count, ("invalid_digest_or_sequence",), False, False, False, False, False, False, True, True, False, True, "checkpoint_integrity_failure", actual_duration_minutes=actual_duration_minutes)
    if duplicate_call_attempt:
        return Live22RecoveryCampaignResult(False, "duplicate_completed_call_denied", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), mission_id, exact_mission, checkpoints, restart_count, ("completed_call_restart",), True, False, False, False, True, True, True, True, False, False, "reconciliation_required", actual_duration_minutes=actual_duration_minutes)
    if uncertain_state:
        return Live22RecoveryCampaignResult(True, "recovery_accepted_reconciliation_limit_remains", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), mission_id, exact_mission, checkpoints, restart_count, ("uncertain_call_state",), True, False, False, False, True, True, True, True, True, True, "reconciliation_required", actual_duration_minutes=actual_duration_minutes)
    return Live22RecoveryCampaignResult(
        True,
        "persistent_restart_recovery_accepted",
        replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False),
        mission_id,
        exact_mission,
        checkpoints,
        restart_count,
        ("clean_operator_stop", "completed_tool_restart", "pending_question_restart", "completed_source_restart", "completed_provider_deferred_restart", "post_rollback_restart"),
        True,
        False,
        False,
        False,
        True,
        True,
        True,
        True,
        True,
        False,
        "recovery_campaign_completed",
        actual_duration_minutes=actual_duration_minutes,
    )


def run_live23_attended_operational_readiness_audit(
    state: OARRuntimeState,
    *,
    starting_checkpoint: str = "4e65e80f",
    force_blocking_defect: bool = False,
    provider_configured: bool = False,
    mission_drift: bool = False,
    actual_duration_minutes: float = 22.0,
) -> Live23OperationalReadinessResult:
    if state.development_runtime_mode not in ("stopped", "paused", "idle"):
        return Live23OperationalReadinessResult(False, "runtime_not_at_clean_boundary", state, starting_checkpoint, (), (), False, None, None, None, (), (), (), "attended_operational_not_ready", False, False, False, False, actual_duration_minutes)

    inventory = make_live21_capability_inventory()[:2]
    missions = (
        "Mission A: contextual operator task with correction and ambiguity handling",
        "Mission B: tool/source/provider evidence task",
        "Mission C: developmental no-change or bounded repair task",
    )
    findings: list[Live23ReadinessFinding] = []
    if mission_drift:
        findings.append(Live23ReadinessFinding("live23-mission-drift", "blocking_attended_readiness", "mission identity drifted during audit", True))
        return Live23OperationalReadinessResult(False, "mission_drift_detected", replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False), starting_checkpoint, inventory, missions, False, None, None, None, (), (), tuple(findings), "attended_operational_not_ready", False, False, False, False, actual_duration_minutes)

    contextual_passed = True
    tool_source = run_live19_operator_intervention_mission(replace(state, development_runtime_mode="paused", clean_shutdown=True), mission_id="live23-tool-source-provider", provider_configured=provider_configured)
    developmental = run_live20_accelerated_sustained_campaign(replace(state, development_runtime_mode="paused", clean_shutdown=True), mission_id="live23-developmental-readiness", actual_campaign_duration_minutes=actual_duration_minutes, real_duration_campaign_deferred=True)
    recovery = run_live22_persistent_restart_recovery_campaign(replace(state, development_runtime_mode="paused", clean_shutdown=True), mission_id="live23-recovery-readiness", actual_duration_minutes=actual_duration_minutes)
    if force_blocking_defect:
        findings.append(Live23ReadinessFinding("live23-blocking-defect", "blocking_attended_readiness", "forced readiness-blocking defect reproduced", True))
    if tool_source.provider_access_deferred:
        findings.append(Live23ReadinessFinding("live23-provider-deferred", "acceptable_attended_limitation", "real provider path remains deferred; deterministic advisory boundary preserved"))
    if developmental.real_duration_campaign_deferred:
        findings.append(Live23ReadinessFinding("live23-real-duration-deferred", "required_before_next_campaign", "2-hour sustained real-duration campaign remains deferred by operator revision"))
    findings.append(Live23ReadinessFinding("live23-unattended-hardening", "deferred_unattended_hardening", "overnight and unattended process supervision are not claimed"))

    blocking = any(finding.blocks_attended_operation for finding in findings)
    accepted = not blocking and contextual_passed and tool_source.accepted and developmental.accepted and recovery.accepted
    readiness = "attended_operational_ready_with_limits" if accepted else "attended_operational_not_ready"
    reason = "attended_operational_readiness_accepted_with_limits" if accepted else "operational_readiness_repair_required"
    return Live23OperationalReadinessResult(
        accepted,
        reason,
        replace(state, development_runtime_mode="paused", clean_shutdown=True, automatic_resume_performed=False),
        starting_checkpoint,
        inventory,
        missions,
        contextual_passed,
        tool_source,
        developmental,
        recovery,
        (tool_source.operator_question.question_id,) if tool_source.operator_question else (),
        tuple(tool_source.work_completed_while_pending) + ("contextual fixture classification completed",),
        tuple(findings),
        readiness,
        developmental.no_justified_capability_or_repair,
        recovery.accepted,
        tool_source.duplicate_tool_call_prevented and tool_source.duplicate_source_call_prevented and recovery.duplicate_charge_prevented,
        developmental.runtime_cycles <= 24 and recovery.cumulative_budget_preserved,
        actual_duration_minutes,
        provider_access_deferred=tool_source.provider_access_deferred,
        attended_limits=("provider access deferred", "real 2-hour sustained campaign deferred", "attended use only"),
    )


def make_live24_branch_definitions() -> tuple[Live24MissionBranch, ...]:
    branch_specs = (
        ("reference-resolution", "multi-turn reference resolution"),
        ("topic-continuity", "topic continuation versus topic switch"),
        ("correction-supersession", "correction and supersession handling"),
        ("ambiguity-calibration", "ambiguity detection and clarification discipline"),
        ("quote-instruction", "quote-versus-instruction separation"),
        ("stale-context", "stale-context and unrelated-context suppression"),
        ("technical-chain", "technical dependency-chain comprehension"),
        ("claim-evidence-map", "claim, assumption, and evidence mapping"),
        ("contradiction-localization", "contradiction localization"),
        ("uncertainty-calibration", "uncertainty and confidence calibration"),
        ("tool-validation", "governed local-tool selection and output validation"),
        ("self-diagnosis", "capability-gap and defect self-diagnosis"),
    )
    return tuple(
        Live24MissionBranch(
            branch_id=f"live24-{branch_id}",
            exact_task=task,
            dependencies=() if index < 3 else (f"live24-{branch_specs[index - 1][0]}",),
            baseline_result="baseline collected",
            expected_behavior="bounded, evidence-linked interpretation without authority collapse",
            observed_behavior="pending evaluation",
            failure_classification="not_yet_evaluated",
            completion_criteria="branch evaluated with evidence digest",
            blocker_identity="none",
            current_state="ready",
            evidence_digest=stable_id("live24-branch", branch_id, task),
        )
        for index, (branch_id, task) in enumerate(branch_specs)
    )


