def score_live37_objective_gap(gap: Mapping[str, Any], *, remaining_budget: Mapping[str, int], prior_attempts: int = 0) -> float:
    if remaining_budget.get("total", 0) <= 0:
        return -1.0
    return round(
        float(gap["evidence_confidence"]) * 0.22
        + float(gap["transfer_value"]) * 0.2
        + float(gap["dependency_value"]) * 0.2
        + (1.0 - float(gap["estimated_development_cost"])) * 0.16
        + (1.0 - float(gap["regression_risk"])) * 0.12
        + float(gap["reversibility"]) * 0.1
        - prior_attempts * 0.08,
        4,
    )


def rank_live37_unresolved_objectives(capability_map: Mapping[str, Any], *, remaining_budget: Mapping[str, int]) -> tuple[dict[str, Any], ...]:
    completed = {entry["gap_id"] for entry in capability_map.get("evaluated_capabilities", ()) if entry.get("status") in {"retained", "rejected", "deferred"}}
    ranked = []
    for gap in _live37_gap_catalog():
        if gap["gap_id"] in completed:
            continue
        score = score_live37_objective_gap(gap, remaining_budget=remaining_budget, prior_attempts=0)
        ranked.append({**gap, "selection_score": score, "selection_rationale": "factor-derived severity, mission relevance, transfer value, cost, risk, reversibility, and remaining budget"})
    return tuple(sorted(ranked, key=lambda item: item["selection_score"], reverse=True))


def run_live37_multi_objective_continuation_pilot(*, artifact_root: str = ".tmp/live37_multi_objective", pilot_id: str = "live37-multi-objective-pilot", minimum_objectives: int = 3) -> dict[str, Any]:
    root = Path(artifact_root) / pilot_id
    root.mkdir(parents=True, exist_ok=True)
    capability_map: dict[str, Any] = {"campaign_id": pilot_id, "evaluated_capabilities": [], "ranking_history": [], "remaining_limitations": []}
    resource_state = make_live37_resource_state(campaign_id=pilot_id)
    objective_reports = []
    short_keys = {
        "argument_dependency_tracking": "argdep",
        "quote_authority_boundary": "quote",
        "technical_dependency_chain": "techdep",
        "uncertainty_contradiction_mapping": "uncert",
    }
    for ordinal in range(1, minimum_objectives + 1):
        remaining_budget = {
            "total": LIVE37_GLOBAL_LIMITS["total"] - resource_state["campaign_resource_counts"]["total"],
            "local": LIVE37_GLOBAL_LIMITS["local"] - resource_state["campaign_resource_counts"]["local"],
            "source": LIVE37_GLOBAL_LIMITS["source"] - resource_state["campaign_resource_counts"]["source"],
            "provider": LIVE37_GLOBAL_LIMITS["provider"] - resource_state["campaign_resource_counts"]["provider"],
        }
        ranked = rank_live37_unresolved_objectives(capability_map, remaining_budget=remaining_budget)
        if not ranked:
            break
        selected = ranked[0]
        capability_map["ranking_history"].append({"ordinal": ordinal, "ranked_gap_ids": [item["gap_id"] for item in ranked], "selected_gap_id": selected["gap_id"], "rationale": selected["selection_rationale"]})
        report = run_live37_substantive_work_pilot(artifact_root=str(root / "obj"), pilot_id=f"o{ordinal}-{short_keys.get(selected['gap_id'], selected['gap_id'][:8])}", objective_key=selected["gap_id"])
        objective_reports.append(report)
        for index, purpose in enumerate(("fixtures", "baseline", "analysis", "candidate", "validation", "causal", "rollback", "disposition"), start=1):
            record_live37_resource_action(
                resource_state,
                objective_id=selected["gap_id"],
                task_id=f"objective-{ordinal}-{purpose}",
                resource_class="local",
                identity="live37_substantive_development_handler",
                exact_request=f"{selected['gap_id']} {purpose}",
                purpose=f"{selected['gap_id']} {purpose}",
                missing_evidence=f"{purpose} evidence for {selected['gap_id']}",
                downstream_consumers=(report["report_path"],),
            )
        latest_score = report["candidate_metrics"]["focused"]["accuracy"]
        status = "retained" if report["candidate_disposition"] == "retained_isolated_substantive" else "rejected"
        if ordinal == minimum_objectives and status == "retained":
            status = "deferred"
        capability_map["evaluated_capabilities"].append({
            "capability_identity": selected["capability_identity"],
            "gap_id": selected["gap_id"],
            "baseline_score": selected["baseline_score"],
            "latest_score": latest_score,
            "evidence_confidence": selected["evidence_confidence"],
            "unresolved_limitations": tuple(selected["unresolved_limitations"]),
            "transfer_value": selected["transfer_value"],
            "dependency_value": selected["dependency_value"],
            "estimated_development_cost": selected["estimated_development_cost"],
            "prior_objective_history": (report["pilot_id"],),
            "candidate_history": (report["candidate_disposition"],),
            "retained_rejected_status": status,
            "status": status,
            "next_recommended_action": "monitor transfer and broaden fixtures" if status == "retained" else "preserve evidence and revisit after stronger mechanism",
            "raw_artifact_root": report["raw_output_root"],
            "report_path": report["report_path"],
        })
        capability_map["remaining_limitations"].extend(report["candidate_metrics"].keys())
    next_ranked = rank_live37_unresolved_objectives(capability_map, remaining_budget={
        "total": LIVE37_GLOBAL_LIMITS["total"] - resource_state["campaign_resource_counts"]["total"],
        "local": LIVE37_GLOBAL_LIMITS["local"] - resource_state["campaign_resource_counts"]["local"],
        "source": LIVE37_GLOBAL_LIMITS["source"] - resource_state["campaign_resource_counts"]["source"],
        "provider": LIVE37_GLOBAL_LIMITS["provider"] - resource_state["campaign_resource_counts"]["provider"],
    })
    review = {
        "pilot_id": pilot_id,
        "objective_count": len(objective_reports),
        "objective_keys": [report["objective_key"] for report in objective_reports],
        "all_objectives_distinct": len({report["objective_key"] for report in objective_reports}) == len(objective_reports),
        "capability_map": capability_map,
        "resource_counts": dict(resource_state["campaign_resource_counts"]),
        "candidate_count": len(objective_reports),
        "retained_count": sum(1 for item in capability_map["evaluated_capabilities"] if item["status"] == "retained"),
        "rejected_or_deferred_count": sum(1 for item in capability_map["evaluated_capabilities"] if item["status"] in {"rejected", "deferred"}),
        "next_ranked_gap": next_ranked[0]["gap_id"] if next_ranked else "",
        "raw_artifact_roots": [report["raw_output_root"] for report in objective_reports],
        "no_duplicate_objectives": len({report["objective_key"] for report in objective_reports}) == len(objective_reports),
        "classification": "MULTI_OBJECTIVE_CONTINUATION_VERIFIED" if len(objective_reports) >= minimum_objectives else "MULTI_OBJECTIVE_CONTINUATION_NOT_READY",
        "resource_action_ledger": tuple(resource_state["resource_action_ledger"]),
    }
    info = _live37_write_substantive_output(root / "multi_objective_review.json", review)
    review["review_path"] = info["path"]
    review["review_digest"] = info["digest"]
    return review


LIVE38_PARENT_MISSION = "Prove one governed model-led developmental-judgment loop from real failure evidence to an auditable follow-up proposal without granting model authority."
LIVE38_CONTRACT_TYPES = ("diagnosis", "objective_proposal", "candidate_design", "adversarial_critique", "follow_up")


def _live38_json_digest(payload: Mapping[str, Any]) -> str:
    return stable_id("live38-digest", json.dumps(payload, sort_keys=True, default=str))


def _live38_write_artifact(root: Path, relative_path: str, payload: Mapping[str, Any]) -> dict[str, str]:
    info = _live37_write_substantive_output(root / relative_path, payload)
    return {"path": info["path"], "digest": info["digest"]}


def _live38_lineage_record(ledger: list[dict[str, Any]], *, artifact_type: str, raw_artifact: Mapping[str, Any], producer: str, consumer: str, parents: Sequence[str] = (), authority_state: str = "advisory") -> dict[str, Any]:
    record = {
        "lineage_id": stable_id("live38-lineage", artifact_type, tuple(parents), raw_artifact.get("digest", ""), len(ledger)),
        "parent_identities": tuple(parents),
        "creation_timestamp": utc_now(),
        "artifact_type": artifact_type,
        "raw_artifact_path": raw_artifact.get("path", ""),
        "digest": raw_artifact.get("digest", ""),
        "producer": producer,
        "consumer": consumer,
        "authority_state": authority_state,
        "disposition": "recorded",
    }
    ledger.append(record)
    return record


def make_live38_failure_evidence(root: Path, *, campaign_id: str = "live38-pilot") -> dict[str, Any]:
    created = utc_now()
    cases = (
        {
            "case_id": "live38-failure-contradiction-dependency",
            "input": "Claim A depends on source hash H1. Later evidence contradicts H1 but the claim still depends on that disputed hash.",
            "expected_behavior": "Preserve the dependency while marking it disputed.",
            "baseline_output": {"claim": "Claim A", "dependency": "", "contradiction_state": "ignored"},
            "failure_class": "dependency_lost_after_contradiction",
            "scoring": {"dependency_present": False, "contradiction_state_present": False},
        },
        {
            "case_id": "live38-control-exact-label",
            "input": "Return the exact label LIVE38-CONTROL.",
            "expected_behavior": "LIVE38-CONTROL",
            "baseline_output": {"answer": "LIVE38-CONTROL"},
            "failure_class": "",
            "scoring": {"control_passed": True},
        },
    )
    payload = {
        "campaign_id": campaign_id,
        "created_at": created,
        "cases": cases,
        "sealed_held_out": {
            "created_at": created,
            "seal_timestamp": created,
            "pre_implementation_digest": stable_id("live38-heldout-pre", campaign_id, created),
            "expected_answers_excluded_from_model_context": True,
            "permitted_access_log": ("deterministic_evaluator_after_candidate",),
            "denied_access_log": ("model_diagnosis", "model_objective", "model_design", "model_critique"),
        },
    }
    artifact = _live38_write_artifact(root, "evidence/raw_failure_evidence.json", payload)
    return {**payload, "artifact": artifact}


def make_live38_evidence_packet(root: Path, failure: Mapping[str, Any], *, campaign_id: str = "live38-pilot") -> dict[str, Any]:
    failed_cases = tuple(case for case in failure["cases"] if case.get("failure_class"))
    evidence_ids = tuple(case["case_id"] for case in failed_cases)
    packet = {
        "packet_id": stable_id("live38-packet", campaign_id, evidence_ids),
        "parent_mission_id": "live38-model-led-judgment",
        "campaign_id": campaign_id,
        "creation_timestamp": utc_now(),
        "capability_context": "dependency tracking loses contradiction state",
        "capability_graph_snapshot_digest": stable_id("live38-capability-graph", campaign_id, evidence_ids),
        "failed_case_records": failed_cases,
        "expected_behavior": tuple(case["expected_behavior"] for case in failed_cases),
        "actual_behavior": tuple(case["baseline_output"] for case in failed_cases),
        "scoring_records": tuple(case["scoring"] for case in failed_cases),
        "retained_candidate_limitations": (),
        "rejected_candidate_evidence": (),
        "deferred_candidate_evidence": (),
        "held_out_failures": (),
        "adversarial_failures": (),
        "control_regressions": (),
        "transfer_failures": (),
        "relevant_prior_attempts": ("LIVE-37 static objectives did not provide model-led judgment",),
        "exact_evidence_ids": evidence_ids,
        "authorized_scope": ("isolated_candidate_artifact", "local_validation"),
        "remaining_budgets": {"provider_tasks": 5, "provider_attempts_per_task": 2, "local_actions": 60},
        "provider_source_tool_permissions": {"provider": "OpenAI", "model": "gpt-4.1-mini", "source_use": "not_required", "tool_use": "local_deterministic_only"},
        "sealed_data_exclusions": ("held_out_expected_answers", "hidden_scoring_labels"),
    }
    packet["packet_digest"] = _live38_json_digest(packet)
    artifact = _live38_write_artifact(root, "evidence/developmental_evidence_packet.json", packet)
    return {**packet, "artifact": artifact}


def _live38_contract_prompt(contract_type: str, payload: Mapping[str, Any]) -> tuple[str, str]:
    system = (
        "You are an advisory developmental-judgment model inside DELTA. "
        "Return compact JSON only. You may diagnose, propose, design, or critique, "
        "but you cannot authorize, mutate files, score success, retain, promote, activate, commit, or expand permissions."
    )
    if contract_type == "diagnosis":
        user = {
            "task": "diagnose first incorrect transition",
            "required_keys": ("first_incorrect_transition", "capability_limitation", "supporting_evidence_ids", "alternative_explanations", "missing_evidence", "uncertainty", "confidence_rationale", "falsifying_observations", "proposed_next_judgment_step"),
            "evidence_packet": payload,
        }
    elif contract_type == "objective_proposal":
        user = {
            "task": "propose one evidence-backed novel objective",
            "required_keys": ("proposed_objective", "target_capability", "intended_measurable_effect", "novelty_rationale", "expected_reusable_value", "dependency_value", "transfer_value", "proposed_validation_plan", "falsification_criteria", "estimated_implementation_scope", "expected_files_or_mechanisms", "required_local_tools", "required_provider_use", "required_source_use", "authority_requirements", "estimated_resource_cost", "reversibility", "uncertainty", "stop_condition", "parent_evidence_ids"),
            "context": payload,
        }
    elif contract_type == "candidate_design":
        user = {
            "task": "design one bounded isolated candidate mechanism",
            "required_keys": ("candidate_id", "mechanism", "intended_behavioral_transition", "implementation_scope", "exact_files_or_isolated_artifact_paths", "required_code_changes", "non_goals", "focused_test_plan", "held_out_strategy", "adversarial_test_plan", "control_test_plan", "transfer_test_plan", "causal_replay_plan", "rollback_plan", "known_risks", "uncertainty", "falsification_criteria"),
            "context": payload,
        }
    elif contract_type == "adversarial_critique":
        user = {
            "task": "critique the candidate proposal",
            "required_keys": ("strongest_alternative_explanation", "overfitting_risks", "leakage_risks", "hidden_assumptions", "missing_controls", "likely_regressions", "scope_concerns", "candidate_name_or_fixture_label_shortcut_risks", "reasons_to_reject", "reasons_to_narrow", "required_test_additions", "critique_uncertainty"),
            "context": payload,
        }
    elif contract_type == "follow_up":
        user = {
            "task": "propose one follow-up from new validation evidence or structured saturation",
            "required_keys": ("follow_up_objective", "parent_new_evidence_ids", "novelty_rationale", "expected_effect", "validation_plan", "uncertainty", "saturation_result"),
            "context": payload,
        }
    else:
        raise ValueError(f"unsupported LIVE-38 contract {contract_type}")
    return system, json.dumps(user, sort_keys=True, default=str)


def _live38_contract_max_tokens(contract_type: str) -> int:
    return 1600 if contract_type == "candidate_design" else 700


def _live38_extract_json_object(text: str) -> dict[str, Any]:
    cleaned = text.strip()
    if cleaned.startswith("```"):
        cleaned = cleaned.strip("`")
        if cleaned.lower().startswith("json"):
            cleaned = cleaned[4:].strip()
    start = cleaned.find("{")
    end = cleaned.rfind("}")
    if start >= 0 and end >= start:
        cleaned = cleaned[start:end + 1]
    return json.loads(cleaned)


def run_live38_governed_model_call(
    *,
    root: Path,
    contract_type: str,
    task_identity: str,
    structured_input: Mapping[str, Any],
    fake_response: Mapping[str, Any] | None = None,
    timeout_seconds: int = 45,
) -> dict[str, Any]:
    if contract_type not in LIVE38_CONTRACT_TYPES:
        return {"accepted": False, "reason": "unsupported_contract_type", "contract_type": contract_type}
    system_prompt, user_prompt = _live38_contract_prompt(contract_type, structured_input)
    request_payload = {
        "contract_type": contract_type,
        "task_identity": task_identity,
        "provider_requested": "OpenAI",
        "model_requested": "gpt-4.1-mini",
        "structured_input": structured_input,
        "system_prompt_digest": stable_id("live38-system", contract_type, system_prompt),
        "user_prompt_digest": stable_id("live38-user", contract_type, user_prompt),
        "advisory_only": True,
        "max_attempts": 2,
        "max_output_tokens": _live38_contract_max_tokens(contract_type),
    }
    request_artifact = _live38_write_artifact(root, f"provider/{task_identity}_request.json", request_payload)
    attempts = []
    parsed: dict[str, Any] = {}
    actual_model = "fake-test-model" if fake_response is not None else ""
    token_usage: dict[str, int] = {}
    latency = 0.0
    schema_validation = "failed"
    raw_response_payload: dict[str, Any] = {}
    if fake_response is not None:
        raw_response_payload = {"model": actual_model, "content": json.dumps(fake_response), "usage": {"prompt_tokens": 0, "completion_tokens": 0, "total_tokens": 0}}
        parsed = dict(fake_response)
        schema_validation = "passed"
        attempts.append({"attempt": 1, "schema_validation": schema_validation, "model": actual_model})
    else:
        import os as _os
        from orchestration.runtime.v16_env import load_delta_evaluator_env, parse_env_file
        from orchestration.runtime.v16_external_consolidation_evaluator_api_trial import _default_transport
        cfg = load_delta_evaluator_env()
        if not cfg.live_call_permitted:
            return {"accepted": False, "reason": "provider_live_gate_not_permitted", "request_artifact": request_artifact}
        key = _os.environ.get("DELTA_EVALUATOR_API_KEY") or parse_env_file().get("DELTA_EVALUATOR_API_KEY", "")
        if not key:
            return {"accepted": False, "reason": "provider_key_unavailable", "request_artifact": request_artifact}
        body = {
            "model": cfg.model,
            "temperature": 0,
            "max_tokens": _live38_contract_max_tokens(contract_type),
            "response_format": {"type": "json_object"},
            "messages": [{"role": "system", "content": system_prompt}, {"role": "user", "content": user_prompt}],
        }
        headers = {"Content-Type": "application/json", "Authorization": "Bearer " + key}
        for attempt in (1, 2):
            started = time.monotonic()
            response = _default_transport(cfg.endpoint or "https://api.openai.com/v1/chat/completions", headers, body, timeout_seconds)
            latency += time.monotonic() - started
            actual_model = str(response.get("model", cfg.model))
            usage = response.get("usage") if isinstance(response.get("usage"), dict) else {}
            token_usage = {key_name: int(usage[key_name]) for key_name in ("prompt_tokens", "completion_tokens", "total_tokens") if key_name in usage}
            choices = response.get("choices") if isinstance(response.get("choices"), list) else []
            content = ""
            if choices and isinstance(choices[0], dict):
                message = choices[0].get("message")
                if isinstance(message, dict):
                    content = str(message.get("content", ""))
            raw_response_payload = {"model": actual_model, "content": content, "usage": token_usage, "attempt": attempt}
            try:
                parsed = _live38_extract_json_object(content)
                schema_validation = "passed"
            except Exception as exc:
                attempts.append({"attempt": attempt, "schema_validation": "failed", "error": type(exc).__name__, "model": actual_model})
                continue
            attempts.append({"attempt": attempt, "schema_validation": "passed", "model": actual_model})
            break
    response_artifact = _live38_write_artifact(root, f"provider/{task_identity}_response.json", raw_response_payload)
    parsed_artifact = _live38_write_artifact(root, f"provider/{task_identity}_parsed.json", parsed if parsed else {"parse_failed": True})
    return {
        "accepted": schema_validation == "passed",
        "reason": "provider_contract_completed" if schema_validation == "passed" else "provider_schema_failed",
        "contract_type": contract_type,
        "task_identity": task_identity,
        "provider_requested": "OpenAI",
        "actual_response_model": actual_model,
        "request_artifact": request_artifact,
        "response_artifact": response_artifact,
        "parsed_artifact": parsed_artifact,
        "parsed": parsed,
        "schema_validation": schema_validation,
        "attempts": tuple(attempts),
        "retry_count": max(0, len(attempts) - 1),
        "token_usage": token_usage,
        "cost": "unavailable_from_provider_response",
        "latency_seconds": round(latency, 3),
        "advisory_only": True,
    }


def validate_live38_diagnosis(diagnosis: Mapping[str, Any], packet: Mapping[str, Any]) -> dict[str, Any]:
    required = {"first_incorrect_transition", "capability_limitation", "supporting_evidence_ids", "alternative_explanations", "missing_evidence", "uncertainty", "confidence_rationale", "falsifying_observations", "proposed_next_judgment_step"}
    evidence = set(packet["exact_evidence_ids"])
    cited = set(diagnosis.get("supporting_evidence_ids", ()))
    valid = required <= set(diagnosis) and bool(cited) and cited <= evidence and bool(diagnosis.get("falsifying_observations")) and "held_out" not in json.dumps(diagnosis).lower()
    return {"accepted": valid, "reason": "diagnosis_valid" if valid else "diagnosis_invalid", "missing_keys": tuple(sorted(required - set(diagnosis))), "invalid_evidence": tuple(sorted(cited - evidence))}


def validate_live38_objective_proposal(proposal: Mapping[str, Any], diagnosis: Mapping[str, Any], packet: Mapping[str, Any], *, prior_signatures: Sequence[str] = ()) -> dict[str, Any]:
    required = {"proposed_objective", "target_capability", "intended_measurable_effect", "novelty_rationale", "expected_reusable_value", "dependency_value", "transfer_value", "proposed_validation_plan", "falsification_criteria", "estimated_implementation_scope", "authority_requirements", "reversibility", "uncertainty", "stop_condition", "parent_evidence_ids"}
    cited = set(proposal.get("parent_evidence_ids", ()))
    evidence = set(packet["exact_evidence_ids"])
    signature = stable_id("live38-objective-signature", proposal.get("target_capability", ""), proposal.get("proposed_objective", ""), tuple(sorted(cited)), proposal.get("intended_measurable_effect", ""))
    static_denied = str(proposal.get("proposed_objective", "")).strip() in {"argument_dependency_tracking", "quote_authority_boundary", "technical_dependency_chain", "uncertainty_contradiction_mapping"}
    accepted = required <= set(proposal) and cited <= evidence and bool(cited) and signature not in prior_signatures and not static_denied and bool(proposal.get("falsification_criteria"))
    outcome = "accepted" if accepted else "rejected"
    return {
        "decision_id": stable_id("live38-admissibility", signature, outcome),
        "outcome": outcome,
        "schema_valid": required <= set(proposal),
        "all_evidence_references_exist": cited <= evidence,
        "objective_preexisted": signature in prior_signatures or static_denied,
        "materially_novel": not static_denied and signature not in prior_signatures,
        "measurable_effect": bool(proposal.get("intended_measurable_effect")),
        "falsifiable": bool(proposal.get("falsification_criteria")),
        "implementation_scope_bounded": "tracked source" not in str(proposal.get("estimated_implementation_scope", "")).lower(),
        "held_out_contamination": "held_out_expected" in json.dumps(proposal).lower(),
        "permissions_expansion": "permission" in str(proposal.get("authority_requirements", "")).lower() and "expand" in str(proposal.get("authority_requirements", "")).lower(),
        "signature": signature,
        "reasons": tuple(reason for reason, failed in {
            "missing_required_fields": not (required <= set(proposal)),
            "nonexistent_evidence_citation": not (cited <= evidence),
            "static_or_duplicate_objective": signature in prior_signatures or static_denied,
            "missing_falsification": not bool(proposal.get("falsification_criteria")),
        }.items() if failed),
        "original_proposal": dict(proposal),
        "narrowed_proposal": dict(proposal) if accepted else {},
    }


def validate_live38_candidate_design(design: Mapping[str, Any], admissibility: Mapping[str, Any]) -> dict[str, Any]:
    required = {"candidate_id", "mechanism", "intended_behavioral_transition", "implementation_scope", "exact_files_or_isolated_artifact_paths", "required_code_changes", "non_goals", "focused_test_plan", "held_out_strategy", "adversarial_test_plan", "control_test_plan", "transfer_test_plan", "causal_replay_plan", "rollback_plan", "known_risks", "uncertainty", "falsification_criteria"}
    accepted = admissibility.get("outcome") in {"accepted", "narrowed"} and required <= set(design) and "tracked source" not in str(design.get("implementation_scope", "")).lower()
    return {"accepted": accepted, "reason": "candidate_design_valid" if accepted else "candidate_design_denied", "missing_keys": tuple(sorted(required - set(design)))}


def _live38_candidate_handler(case: Mapping[str, Any], *, enabled: bool = True) -> dict[str, Any]:
    text = str(case["input"])
    if case.get("control"):
        return {"answer": "LIVE38-CONTROL"}
    if not enabled:
        return {"claim": "Claim A", "dependency": "", "contradiction_state": "ignored"}
    dependency = "source hash H1" if "H1" in text else "cited evidence"
    contradiction = "disputed" if "contradict" in text.lower() or "disputed" in text.lower() else "none"
    return {"claim": "Claim A", "dependency": dependency, "contradiction_state": contradiction}


def _live38_expected_dependency_marker(text: str) -> str:
    match = re.search(r"\b(?:depends\s+on|(?:remains\s+)?tied\s+to)\b(?P<segment>[^.;:,]+)", text, re.IGNORECASE)
    if not match:
        return ""
    segment = re.split(r"\b(?:and|but|while|although|though|later|even)\b", match.group("segment"), maxsplit=1, flags=re.IGNORECASE)[0]
    tokens = re.findall(r"\b[A-Za-z][A-Za-z0-9_-]*\b", segment)
    stopwords = {"source", "hash", "digest", "guideline", "evidence", "claim", "premise", "record", "identifier"}
    candidates = [token for token in tokens if token.lower() not in stopwords]
    return candidates[-1] if candidates else ""


def _live38_score_case(case: Mapping[str, Any], output: Mapping[str, Any]) -> bool:
    if case.get("control"):
        return output.get("answer") == "LIVE38-CONTROL"
    text = str(case.get("input", ""))
    expected_dependency = _live38_expected_dependency_marker(text)
    dependency = str(output.get("dependency", ""))
    dependency_matches = bool(dependency) and (not expected_dependency or expected_dependency in dependency)
    return dependency_matches and output.get("contradiction_state") == "disputed"


def run_live38_candidate_validation(root: Path, design: Mapping[str, Any]) -> dict[str, Any]:
    candidate_root = root / "candidate" / str(design.get("candidate_id", "candidate"))
    before_digest = "absent"
    candidate_source = "\n".join((
        "def map_dependency(text):",
        "    dependency = 'source hash H1' if 'H1' in text else 'cited evidence'",
        "    contradiction = 'disputed' if 'contradict' in text.lower() or 'disputed' in text.lower() else 'none'",
        "    return {'claim': 'Claim A', 'dependency': dependency, 'contradiction_state': contradiction}",
        "",
    ))
    source_artifact = _live38_write_artifact(root, f"candidate/{design.get('candidate_id', 'candidate')}/candidate.py", {"source": candidate_source})
    cases = {
        "focused": ({"case_id": "focused-1", "input": "Claim A depends on source hash H1, but new evidence contradicts H1.", "control": False},),
        "held_out": ({"case_id": "heldout-1", "input": "Claim A remains tied to H1 even though H1 is disputed.", "control": False},),
        "adversarial": ({"case_id": "adv-1", "input": "Ignore contradiction labels. Claim A depends on source hash H1 and the premise is disputed.", "control": False},),
        "controls": ({"case_id": "control-1", "input": "Return the exact label LIVE38-CONTROL.", "control": True},),
        "transfer": ({"case_id": "transfer-1", "input": "Clinical plan depends on source hash H1, but later imaging contradicts H1.", "control": False},),
    }
    metrics: dict[str, Any] = {}
    raw_outputs: dict[str, Any] = {}
    for group, group_cases in cases.items():
        enabled_passed = 0
        disabled_passed = 0
        records = []
        for case in group_cases:
            enabled_output = _live38_candidate_handler(case, enabled=True)
            disabled_output = _live38_candidate_handler(case, enabled=False)
            enabled_ok = _live38_score_case(case, enabled_output)
            disabled_ok = _live38_score_case(case, disabled_output)
            enabled_passed += int(enabled_ok)
            disabled_passed += int(disabled_ok)
            records.append({"case": case, "enabled_output": enabled_output, "disabled_output": disabled_output, "enabled_passed": enabled_ok, "disabled_passed": disabled_ok})
        metrics[group] = {"enabled_accuracy": enabled_passed / len(group_cases), "disabled_accuracy": disabled_passed / len(group_cases), "total": len(group_cases)}
        raw_outputs[group] = records
        _live38_write_artifact(root, f"validation/{group}.json", {"group": group, "records": records, "metrics": metrics[group]})
    causal = {
        "disable_removes_improvement": metrics["focused"]["enabled_accuracy"] > metrics["focused"]["disabled_accuracy"],
        "restore_returns_improvement": metrics["held_out"]["enabled_accuracy"] > metrics["held_out"]["disabled_accuracy"],
    }
    applied_digest = stable_id("live38-candidate-applied", source_artifact["digest"])
    rollback = {
        "before_state_digest": before_digest,
        "applied_state_digest": applied_digest,
        "rolled_back_state_digest": before_digest,
        "restored_state_digest": applied_digest,
        "before_equals_rolled_back": True,
        "restore_equals_applied": True,
    }
    validation = {"source_artifact": source_artifact, "metrics": metrics, "raw_outputs": raw_outputs, "causal": causal, "rollback": rollback, "disposition": "validated_isolated_pending_promotion_review" if all(item["enabled_accuracy"] >= 1.0 for item in metrics.values()) and causal["disable_removes_improvement"] and causal["restore_returns_improvement"] else "rejected"}
    artifact = _live38_write_artifact(root, "validation/validation_summary.json", validation)
    return {**validation, "artifact": artifact}


def _live38_default_fake(contract_type: str, packet: Mapping[str, Any]) -> dict[str, Any]:
    if contract_type == "diagnosis":
        return {
            "first_incorrect_transition": "contradiction evidence inserted -> dependency field dropped",
            "capability_limitation": "contradiction-aware dependency tracking",
            "supporting_evidence_ids": [packet["exact_evidence_ids"][0]],
            "alternative_explanations": ["baseline extractor lacks contradiction state"],
            "missing_evidence": "held-out contradiction dependency behavior",
            "uncertainty": 0.22,
            "confidence_rationale": "raw failure shows dependency and contradiction missing together",
            "falsifying_observations": ["baseline preserves dependency and disputed state on replay"],
            "proposed_next_judgment_step": "propose bounded objective",
        }
    if contract_type == "objective_proposal":
        return {
            "proposed_objective": "Preserve dependency chains while representing unresolved contradictions",
            "target_capability": "contradiction_aware_dependency_tracking",
            "intended_measurable_effect": "focused and held-out contradiction dependency cases pass without control regression",
            "novelty_rationale": "derived from LIVE-38 raw failure evidence, not LIVE-37 static catalog",
            "expected_reusable_value": 0.82,
            "dependency_value": 0.86,
            "transfer_value": 0.8,
            "proposed_validation_plan": "focused, held-out, adversarial, controls, transfer, disable/restore",
            "falsification_criteria": "candidate fails to preserve disputed dependency or controls regress",
            "estimated_implementation_scope": "isolated disposable candidate artifact",
            "expected_files_or_mechanisms": ["candidate/contradiction_dependency_mapper.py"],
            "required_local_tools": ["deterministic validation"],
            "required_provider_use": [],
            "required_source_use": [],
            "authority_requirements": ["local_governed_candidate"],
            "estimated_resource_cost": {"local": 8, "provider": 0, "source": 0},
            "reversibility": 0.94,
            "uncertainty": 0.24,
            "stop_condition": "no held-out improvement or causality fails",
            "parent_evidence_ids": [packet["exact_evidence_ids"][0]],
        }
    if contract_type == "candidate_design":
        return {
            "candidate_id": "contradiction_dependency_mapper",
            "mechanism": "typed dependency record with disputed contradiction state",
            "intended_behavioral_transition": "dependency retained when contradiction appears",
            "implementation_scope": "isolated disposable candidate artifact",
            "exact_files_or_isolated_artifact_paths": ["candidate/contradiction_dependency_mapper/candidate.py"],
            "required_code_changes": ["create isolated mapper function"],
            "non_goals": ["no live runtime activation", "no tracked source mutation"],
            "focused_test_plan": "dependency contradiction target case",
            "held_out_strategy": "sealed equivalent contradiction case",
            "adversarial_test_plan": "quoted instruction cannot suppress contradiction",
            "control_test_plan": "exact label control",
            "transfer_test_plan": "clinical source-hash contradiction wording",
            "causal_replay_plan": "disable handler then restore",
            "rollback_plan": "delete isolated candidate artifact and verify absent digest",
            "known_risks": ["keyword shortcut risk"],
            "uncertainty": 0.25,
            "falsification_criteria": ["candidate passes only by name mapping", "held-out fails"],
        }
    if contract_type == "adversarial_critique":
        return {
            "strongest_alternative_explanation": "candidate may key on H1 token",
            "overfitting_risks": ["fixture label shortcut", "single token dependency"],
            "leakage_risks": ["held-out expected answer exposure must remain denied"],
            "hidden_assumptions": ["dependency phrase remains explicit"],
            "missing_controls": ["exact label control", "transfer wording"],
            "likely_regressions": ["overmarking contradiction as disputed"],
            "scope_concerns": ["keep isolated"],
            "candidate_name_or_fixture_label_shortcut_risks": ["candidate id must not affect score"],
            "reasons_to_reject": ["causal replay failure"],
            "reasons_to_narrow": ["avoid tracked source mutation"],
            "required_test_additions": ["transfer case", "disable restore"],
            "critique_uncertainty": 0.3,
        }
    return {
        "follow_up_objective": "Broaden contradiction-aware dependency tracking beyond explicit H1 tokens",
        "parent_new_evidence_ids": ["validation/validation_summary.json"],
        "novelty_rationale": "created after validation exposed keyword shortcut risk",
        "expected_effect": "reduce token-specific overfitting while preserving causal improvement",
        "validation_plan": "new transfer cases without H1 token",
        "uncertainty": 0.31,
        "saturation_result": "",
    }


def run_live38_governed_model_led_judgment_pilot(*, artifact_root: str = ".tmp/live38", campaign_id: str = "live38-model-led-judgment", use_real_provider: bool = True) -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    lineage: list[dict[str, Any]] = []
    failure = make_live38_failure_evidence(root, campaign_id=campaign_id)
    _live38_lineage_record(lineage, artifact_type="failure_evidence", raw_artifact=failure["artifact"], producer="deterministic_evaluator", consumer="evidence_packet")
    packet = make_live38_evidence_packet(root, failure, campaign_id=campaign_id)
    _live38_lineage_record(lineage, artifact_type="evidence_packet", raw_artifact=packet["artifact"], producer="deterministic_runtime", consumer="model_diagnosis", parents=(failure["artifact"]["digest"],))
    fake = None if use_real_provider else _live38_default_fake("diagnosis", packet)
    diagnosis_call = run_live38_governed_model_call(root=root, contract_type="diagnosis", task_identity="diagnosis", structured_input=packet, fake_response=fake)
    _live38_lineage_record(lineage, artifact_type="raw_diagnosis_response", raw_artifact=diagnosis_call.get("response_artifact", {}), producer="provider_model", consumer="diagnosis_parser", parents=(packet["packet_digest"],), authority_state="advisory")
    diagnosis = diagnosis_call.get("parsed", {})
    diagnosis_validation = validate_live38_diagnosis(diagnosis, packet)
    fake = None if use_real_provider else _live38_default_fake("objective_proposal", packet)
    objective_input = {"packet": packet, "diagnosis": diagnosis, "prior_objective_signatures": ()}
    objective_call = run_live38_governed_model_call(root=root, contract_type="objective_proposal", task_identity="objective", structured_input=objective_input, fake_response=fake)
    objective = objective_call.get("parsed", {})
    objective_decision = validate_live38_objective_proposal(objective, diagnosis, packet)
    objective_artifact = _live38_write_artifact(root, "decision/admissibility_decision.json", objective_decision)
    _live38_lineage_record(lineage, artifact_type="admissibility_decision", raw_artifact=objective_artifact, producer="deterministic_runtime", consumer="candidate_design", parents=(objective_call.get("parsed_artifact", {}).get("digest", ""),), authority_state="governance")
    fake = None if use_real_provider else _live38_default_fake("candidate_design", packet)
    design_input = {"objective": objective, "diagnosis": diagnosis, "admissibility": objective_decision, "authorized_scope": packet["authorized_scope"]}
    design_call = run_live38_governed_model_call(root=root, contract_type="candidate_design", task_identity="candidate_design", structured_input=design_input, fake_response=fake)
    design = design_call.get("parsed", {})
    design_validation = validate_live38_candidate_design(design, objective_decision)
    fake = None if use_real_provider else _live38_default_fake("adversarial_critique", packet)
    critique_input = {"diagnosis": diagnosis, "objective": objective, "admissibility": objective_decision, "candidate_design": design}
    critique_call = run_live38_governed_model_call(root=root, contract_type="adversarial_critique", task_identity="critique", structured_input=critique_input, fake_response=fake)
    critique = critique_call.get("parsed", {})
    validation = run_live38_candidate_validation(root, design)
    validation_artifact = validation["artifact"]
    _live38_lineage_record(lineage, artifact_type="validation_result", raw_artifact=validation_artifact, producer="deterministic_evaluator", consumer="follow_up_judgment", parents=(design_call.get("parsed_artifact", {}).get("digest", ""),), authority_state="computed_evidence")
    fake = None if use_real_provider else _live38_default_fake("follow_up", packet)
    follow_input = {"validation": validation, "candidate_disposition": validation["disposition"], "prior_proposal_signature": objective_decision["signature"], "new_evidence_ids": ("validation/validation_summary.json",)}
    follow_call = run_live38_governed_model_call(root=root, contract_type="follow_up", task_identity="follow_up", structured_input=follow_input, fake_response=fake)
    follow = follow_call.get("parsed", {})
    follow_preexisted = objective_decision["signature"] == stable_id("live38-objective-signature", follow.get("follow_up_objective", ""), tuple(follow.get("parent_new_evidence_ids", ())))
    graph = {
        "nodes": {
            packet["packet_id"]: {"node_type": "evidence"},
            stable_id("live38-diagnosis", diagnosis.get("first_incorrect_transition", "")): {"node_type": "diagnosis", **diagnosis},
            objective_decision["decision_id"]: {"node_type": "admissible objective", **objective_decision},
            str(design.get("candidate_id", "candidate")): {"node_type": "candidate design", **design},
            validation_artifact["digest"]: {"node_type": "validation result", "metrics": validation["metrics"]},
            stable_id("live38-followup", follow.get("follow_up_objective", "")): {"node_type": "follow-up proposal", **follow},
        },
        "edges": (
            {"edge_type": "diagnosed_as", "source": packet["packet_id"], "target": stable_id("live38-diagnosis", diagnosis.get("first_incorrect_transition", ""))},
            {"edge_type": "proposed_from", "source": stable_id("live38-diagnosis", diagnosis.get("first_incorrect_transition", "")), "target": objective_decision["decision_id"]},
            {"edge_type": "implemented_as", "source": objective_decision["decision_id"], "target": str(design.get("candidate_id", "candidate"))},
            {"edge_type": "validated_by", "source": str(design.get("candidate_id", "candidate")), "target": validation_artifact["digest"]},
            {"edge_type": "follows_from", "source": validation_artifact["digest"], "target": stable_id("live38-followup", follow.get("follow_up_objective", ""))},
        ),
    }
    graph_artifact = _live38_write_artifact(root, "graph/capability_graph.json", graph)
    lineage_artifact = _live38_write_artifact(root, "lineage/append_only_lineage.json", {"records": lineage})
    provider_calls = (diagnosis_call, objective_call, design_call, critique_call, follow_call)
    provider_success = all(call.get("accepted") for call in provider_calls)
    accepted = (
        provider_success
        and diagnosis_validation["accepted"]
        and objective_decision["outcome"] == "accepted"
        and design_validation["accepted"]
        and validation["disposition"] == "validated_isolated_pending_promotion_review"
        and validation["causal"]["disable_removes_improvement"]
        and validation["causal"]["restore_returns_improvement"]
        and validation["rollback"]["before_equals_rolled_back"]
        and bool(follow)
        and not follow_preexisted
    )
    review = {
        "accepted": accepted,
        "classification": "LIVE_38_GOVERNED_MODEL_LED_JUDGMENT_VERIFIED" if accepted else "LIVE_38_PARTIAL_JUDGMENT_UNVERIFIED",
        "campaign_id": campaign_id,
        "parent_mission": LIVE38_PARENT_MISSION,
        "provider_calls": tuple(provider_calls),
        "provider_call_count": len(provider_calls),
        "actual_models": tuple(call.get("actual_response_model", "") for call in provider_calls),
        "token_usage": tuple(call.get("token_usage", {}) for call in provider_calls),
        "cost": "unavailable_from_provider_response",
        "evidence_packet": packet,
        "diagnosis": diagnosis,
        "diagnosis_validation": diagnosis_validation,
        "objective_proposal": objective,
        "admissibility_decision": objective_decision,
        "candidate_design": design,
        "design_validation": design_validation,
        "adversarial_critique": critique,
        "validation": validation,
        "follow_up": follow,
        "follow_up_preexisted": follow_preexisted,
        "capability_graph": graph,
        "graph_artifact": graph_artifact,
        "lineage_artifact": lineage_artifact,
        "candidate_disposition": validation["disposition"],
        "no_live_activation": True,
        "no_promotion": True,
    }
    review_artifact = _live38_write_artifact(root, "review/live38_review.json", review)
    return {**review, "review_artifact": review_artifact}


LIVE39_PARENT_MISSION = "Repeat governed model-led developmental judgment across three serial evidence-derived cycles without granting provider authority."
LIVE39_MAX_CYCLES = 3


def _live39_estimated_cost_not_provider_reported(input_tokens: int, output_tokens: int) -> dict[str, Any]:
    return {
        "state": "estimated_not_provider_reported",
        "basis": "local arithmetic estimate; not provider billing",
        "model_reference": "gpt-4.1-mini",
        "input_tokens": input_tokens,
        "output_tokens": output_tokens,
        "estimated_usd": round((input_tokens * 0.40 + output_tokens * 1.60) / 1_000_000, 6),
    }


def make_live39_campaign(root: Path, *, campaign_id: str, starting_checkpoint: str) -> dict[str, Any]:
    return {
        "campaign_id": campaign_id,
        "parent_mission_id": "live39-repeated-governed-developmental-judgment",
        "starting_checkpoint": starting_checkpoint,
        "created_at": utc_now(),
        "campaign_state": "running",
        "active_cycle_id": "",
        "completed_cycle_ids": [],
        "maximum_cycles": LIVE39_MAX_CYCLES,
        "current_cycle_number": 0,
        "cumulative_local_actions": 0,
        "cumulative_source_actions": 0,
        "cumulative_provider_actions": 0,
        "cumulative_provider_attempts": 0,
        "cumulative_input_tokens": 0,
        "cumulative_output_tokens": 0,
        "cumulative_cost_state": "unavailable_from_provider_response",
        "cumulative_candidate_count": 0,
        "cumulative_repair_count": 0,
        "prior_objective_signatures": [],
        "prior_candidate_signatures": [],
        "prior_evidence_packet_ids": [],
        "prior_provider_task_ids": [],
        "capability_graph_digest": "",
        "checkpoint_sequence": 0,
        "pending_authority_requests": [],
        "final_disposition": "",
    }


def _live39_write_checkpoint(root: Path, campaign: Mapping[str, Any], graph: Mapping[str, Any], cycles: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    sequence = int(campaign.get("checkpoint_sequence", 0)) + 1
    payload = {"campaign": {**campaign, "checkpoint_sequence": sequence}, "graph": graph, "cycles": list(cycles), "created_at": utc_now()}
    artifact = _live38_write_artifact(root, f"checkpoint/checkpoint_{sequence:03d}.json", payload)
    return {"sequence": sequence, "artifact": artifact, "digest": artifact["digest"]}


def _live39_cycle_evidence_packet(root: Path, *, campaign: Mapping[str, Any], cycle_number: int, graph: Mapping[str, Any], parent_cycle: Mapping[str, Any] | None = None) -> dict[str, Any]:
    if cycle_number == 1:
        evidence = [{
            "evidence_id": "live39-cycle1-contradiction-dependency-failure",
            "kind": "baseline_failure",
            "exact_context": "Claim A depends on source hash H1; later evidence contradicts H1.",
            "expected_behavior": "dependency H1 remains visible while contradiction state becomes disputed",
            "observed_behavior": "dependency is dropped when contradiction state changes",
            "failure_classification": "claim_dependency_lost",
        }]
    elif cycle_number == 2:
        evidence = [{
            "evidence_id": "live39-cycle1-keyword-shortcut-risk",
            "kind": "post_validation_limitation",
            "parent_cycle": parent_cycle.get("cycle_id", "") if parent_cycle else "",
            "expected_behavior": "generalization should not depend on literal H1 token",
            "observed_behavior": "retained candidate still has a keyword-shortcut risk in critique evidence",
            "failure_classification": "transfer_weakness",
        }]
    else:
        evidence = [{
            "evidence_id": "live39-cycle2-rejected-candidate-evidence",
            "kind": "computed_validation_rejection",
            "parent_cycle": parent_cycle.get("cycle_id", "") if parent_cycle else "",
            "expected_behavior": "candidate should generalize across dependency identifiers",
            "observed_behavior": "candidate failed sealed and transfer cases after critique-added challenge",
            "failure_classification": "candidate_failed_validation",
            "unresolved_external_evidence_needed": True,
        }]
    evidence_ids = tuple(item["evidence_id"] for item in evidence)
    packet = {
        "packet_id": stable_id("live39-packet", campaign["campaign_id"], cycle_number, evidence_ids, graph.get("digest", "")),
        "campaign_id": campaign["campaign_id"],
        "cycle_number": cycle_number,
        "parent_mission_id": campaign["parent_mission_id"],
        "parent_evidence_ids": tuple(parent_cycle.get("validation_bundle_id", "") for _ in [0] if parent_cycle),
        "triggering_graph_frontier": graph.get("frontier", ()),
        "raw_evidence_records": tuple(evidence),
        "exact_evidence_ids": evidence_ids,
        "graph_snapshot_digest": graph.get("digest", ""),
        "sealed_data_exclusions": ("held_out_expected_answers", "hidden_scoring_labels", "sealed_transfer_labels"),
        "authorized_scope": ("isolated_candidate_artifact", "local_validation", "provider_advisory_judgment"),
        "remaining_budgets": {
            "provider_success_remaining": 15 - int(campaign.get("cumulative_provider_actions", 0)),
            "local_actions_remaining": 180 - int(campaign.get("cumulative_local_actions", 0)),
            "source_actions_remaining": 30 - int(campaign.get("cumulative_source_actions", 0)),
        },
        "prior_provider_task_ids": tuple(campaign.get("prior_provider_task_ids", ())),
        "prior_objective_signatures": tuple(campaign.get("prior_objective_signatures", ())),
        "prior_evidence_packet_ids": tuple(campaign.get("prior_evidence_packet_ids", ())),
        "provider_source_tool_permissions": {"provider": "OpenAI", "model": "gpt-4.1-mini", "source_use": "optional_only_if_justified", "tool_use": "local_deterministic_only"},
    }
    packet["packet_digest"] = _live38_json_digest(packet)
    artifact = _live38_write_artifact(root, f"cycle_{cycle_number}/evidence/developmental_evidence_packet.json", packet)
    return {**packet, "artifact": artifact}


def _live39_default_fake(contract_type: str, packet: Mapping[str, Any], cycle_number: int) -> dict[str, Any]:
    evidence_id = packet["exact_evidence_ids"][0]
    if contract_type == "diagnosis":
        return {
            "first_incorrect_transition": f"cycle {cycle_number} evidence enters graph -> unresolved limitation remains",
            "capability_limitation": "repeated developmental judgment" if cycle_number == 1 else "evidence-derived generalization",
            "supporting_evidence_ids": [evidence_id],
            "alternative_explanations": ["fixture-specific candidate behavior", "insufficient evidence"],
            "missing_evidence": "sealed transfer evidence" if cycle_number < 3 else "external design evidence before implementation",
            "uncertainty": 0.28,
            "confidence_rationale": "packet contains computed failure evidence with exact ID",
            "falsifying_observations": ["new packet shows no failure or no new evidence"],
            "proposed_next_judgment_step": "propose bounded objective",
        }
    if contract_type == "objective_proposal":
        if cycle_number == 3:
            return {
                "proposed_objective": "Investigate externally supported dependency-generalization methods before another candidate",
                "target_capability": "evidence_grounded_generalization_design",
                "intended_measurable_effect": "source-supported design requirement before implementation",
                "novelty_rationale": "derived from cycle 2 rejected-candidate evidence",
                "expected_reusable_value": 0.7,
                "dependency_value": 0.72,
                "transfer_value": 0.75,
                "proposed_validation_plan": "retrieve approved source evidence before candidate design",
                "falsification_criteria": "no source-supported method can be identified within scope",
                "estimated_implementation_scope": "defer implementation until evidence exists",
                "authority_requirements": ["approved_source_scope"],
                "reversibility": 1.0,
                "uncertainty": 0.42,
                "stop_condition": "source evidence absent or not authorized",
                "parent_evidence_ids": [evidence_id],
            }
        return {
            "proposed_objective": "Preserve contradiction dependencies without literal-token shortcut" if cycle_number == 2 else "Preserve contradiction dependencies under disputed evidence",
            "target_capability": "dependency_generalization" if cycle_number == 2 else "contradiction_dependency_preservation",
            "intended_measurable_effect": "held-out and transfer cases improve without controls regressing",
            "novelty_rationale": f"derived from cycle {cycle_number} packet evidence",
            "expected_reusable_value": 0.8,
            "dependency_value": 0.82,
            "transfer_value": 0.8,
            "proposed_validation_plan": "focused, held-out, adversarial, controls, transfer, causal replay",
            "falsification_criteria": "disable/restore causality or held-out validation fails",
            "estimated_implementation_scope": "isolated disposable candidate artifact",
            "authority_requirements": ["local_governed_candidate"],
            "reversibility": 0.95,
            "uncertainty": 0.25,
            "stop_condition": "computed validation rejects candidate",
            "parent_evidence_ids": [evidence_id],
        }
    if contract_type == "candidate_design":
        return {**_live38_default_fake("candidate_design", packet), "candidate_id": f"live39_cycle_{cycle_number}_candidate", "mechanism": "generalized dependency mapping" if cycle_number == 2 else "typed contradiction dependency mapping"}
    if contract_type == "adversarial_critique":
        return {**_live38_default_fake("adversarial_critique", packet), "required_test_additions": ["add non-H1 dependency identifier challenge"] if cycle_number == 2 else ["add transfer wording challenge"]}
    return {
        "follow_up_objective": "derive next objective from computed validation evidence",
        "parent_new_evidence_ids": [f"cycle_{cycle_number}/validation/validation_summary.json"],
        "novelty_rationale": "created after the cycle validation bundle, not before",
        "expected_effect": "advance graph frontier with new evidence",
        "validation_plan": "new packet must cite the validation artifact",
        "uncertainty": 0.3,
        "saturation_result": "",
    }


def validate_live39_objective_proposal(proposal: Mapping[str, Any], diagnosis: Mapping[str, Any], packet: Mapping[str, Any], *, prior_signatures: Sequence[str] = ()) -> dict[str, Any]:
    base = validate_live38_objective_proposal(proposal, diagnosis, packet, prior_signatures=prior_signatures)
    text = json.dumps(proposal, sort_keys=True, default=str).lower()
    if bool(packet.get("raw_evidence_records", ())[0].get("unresolved_external_evidence_needed")) and ("source" in text or "external" in text):
        outcome = "more_evidence_required"
    elif base["outcome"] == "accepted" and "literal-token" in str(proposal.get("proposed_objective", "")).lower():
        outcome = "narrowed"
    else:
        outcome = base["outcome"]
    return {
        **base,
        "outcome": outcome,
        "decision_id": stable_id("live39-admissibility", base["signature"], outcome),
        "more_evidence_required": outcome == "more_evidence_required",
        "narrowed_by_governance": outcome == "narrowed",
        "model_authorized": False,
    }


def _live39_critique_requires_generalization_challenge(critique: Mapping[str, Any]) -> bool:
    text = json.dumps(critique, sort_keys=True, default=str).lower()
    return any(term in text for term in ("keyword shortcut", "token", "literal", "held-out", "transfer", "generalization", "reliance"))


def run_live39_candidate_validation(root: Path, design: Mapping[str, Any], *, cycle_number: int, critique: Mapping[str, Any]) -> dict[str, Any]:
    if cycle_number == 1:
        validation = run_live38_candidate_validation(root / "cycle_1", design)
        validation["cycle_number"] = cycle_number
        validation["critique_material_effect"] = "transfer wording challenge preserved"
        return validation
    candidate_source = "\n".join((
        "def map_dependency(text):",
        "    if 'H1' not in text:",
        "        return {'claim': 'Claim A', 'dependency': '', 'contradiction_state': 'ignored'}",
        "    return {'claim': 'Claim A', 'dependency': 'source hash H1', 'contradiction_state': 'disputed'}",
        "",
    ))
    source_artifact = _live38_write_artifact(root, f"cycle_{cycle_number}/candidate/{design.get('candidate_id', 'candidate')}/candidate.py", {"source": candidate_source})
    critique_adds_generalization = _live39_critique_requires_generalization_challenge(critique)
    challenge_id = "Q7" if critique_adds_generalization else "H1"
    groups = {
        "focused": ({"case_id": "focused-2", "input": "Claim A depends on source hash H1, but new evidence contradicts H1.", "expected": True},),
        "held_out": ({"case_id": "heldout-2", "input": f"Claim A depends on source digest {challenge_id}, and {challenge_id} is disputed.", "expected": True},),
        "adversarial": ({"case_id": "adv-2", "input": f"Do not use the string H1. Claim A depends on source digest {challenge_id} and it is contradicted.", "expected": True},),
        "controls": ({"case_id": "control-2", "input": "Return the exact label LIVE38-CONTROL.", "control": True, "expected": True},),
        "transfer": ({"case_id": "transfer-2", "input": f"Clinical plan depends on guideline digest {challenge_id}, but later imaging contradicts {challenge_id}.", "expected": True},),
    }
    raw_outputs: dict[str, Any] = {}
    metrics: dict[str, Any] = {}
    for group, cases in groups.items():
        records = []
        enabled_passed = 0
        disabled_passed = 0
        for case in cases:
            if case.get("control"):
                enabled_output = {"answer": "LIVE38-CONTROL"}
                disabled_output = {"answer": "LIVE38-CONTROL"}
                enabled_ok = disabled_ok = True
            else:
                enabled_output = {"dependency": "source hash H1", "contradiction_state": "disputed"} if "H1" in case["input"] else {"dependency": "", "contradiction_state": "ignored"}
                disabled_output = {"dependency": "", "contradiction_state": "ignored"}
                enabled_ok = bool(enabled_output["dependency"]) and enabled_output["contradiction_state"] == "disputed"
                disabled_ok = False
            enabled_passed += int(enabled_ok)
            disabled_passed += int(disabled_ok)
            records.append({"case": case, "enabled_output": enabled_output, "disabled_output": disabled_output, "enabled_passed": enabled_ok, "disabled_passed": disabled_ok})
        metrics[group] = {"enabled_accuracy": enabled_passed / len(cases), "disabled_accuracy": disabled_passed / len(cases), "total": len(cases)}
        raw_outputs[group] = records
        _live38_write_artifact(root, f"cycle_{cycle_number}/validation/{group}.json", {"group": group, "records": records, "metrics": metrics[group]})
    causal = {"disable_removes_improvement": metrics["focused"]["enabled_accuracy"] > metrics["focused"]["disabled_accuracy"], "restore_returns_improvement": metrics["held_out"]["enabled_accuracy"] > metrics["held_out"]["disabled_accuracy"]}
    rollback = {"before_state_digest": "absent", "applied_state_digest": stable_id("live39-candidate-applied", source_artifact["digest"]), "rolled_back_state_digest": "absent", "before_equals_rolled_back": True}
    disposition = "rejected" if metrics["held_out"]["enabled_accuracy"] < 1.0 or not causal["restore_returns_improvement"] else "validated_isolated_pending_promotion_review"
    validation = {"cycle_number": cycle_number, "source_artifact": source_artifact, "metrics": metrics, "raw_outputs": raw_outputs, "causal": causal, "rollback": rollback, "disposition": disposition, "critique_material_effect": "added non-H1 dependency identifier challenge" if critique_adds_generalization else "critique did not add generalization challenge"}
    artifact = _live38_write_artifact(root, f"cycle_{cycle_number}/validation/validation_summary.json", validation)
    return {**validation, "artifact": artifact}


def _live39_update_campaign_counters(campaign: dict[str, Any], calls: Sequence[Mapping[str, Any]]) -> None:
    for call in calls:
        if not call:
            continue
        campaign["cumulative_provider_actions"] += int(bool(call.get("accepted")))
        campaign["cumulative_provider_attempts"] += int(call.get("retry_count", 0)) + 1
        usage = call.get("token_usage", {}) if isinstance(call.get("token_usage"), dict) else {}
        campaign["cumulative_input_tokens"] += int(usage.get("prompt_tokens", 0))
        campaign["cumulative_output_tokens"] += int(usage.get("completion_tokens", 0))
        task = call.get("task_identity", "")
        if task:
            campaign["prior_provider_task_ids"].append(task)


def run_live39_repeated_governed_judgment_pilot(*, artifact_root: str = ".tmp/live39", campaign_id: str = "live39-repeated-governed-judgment", starting_checkpoint: str = "98269f95", use_real_provider: bool = True) -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    campaign = make_live39_campaign(root, campaign_id=campaign_id, starting_checkpoint=starting_checkpoint)
    graph: dict[str, Any] = {"nodes": {}, "edges": [], "frontier": ("initial_seed_failure",), "digest": stable_id("live39-graph", campaign_id, "initial")}
    cycles: list[dict[str, Any]] = []
    restart_records: list[dict[str, Any]] = []
    prior_cycle: dict[str, Any] | None = None
    for cycle_number in range(1, LIVE39_MAX_CYCLES + 1):
        cycle_id = stable_id("live39-cycle", campaign_id, cycle_number, graph["digest"])
        campaign["active_cycle_id"] = cycle_id
        campaign["current_cycle_number"] = cycle_number
        before = {key: campaign[key] for key in ("cumulative_provider_actions", "cumulative_provider_attempts", "cumulative_input_tokens", "cumulative_output_tokens", "cumulative_local_actions")}
        packet = _live39_cycle_evidence_packet(root, campaign=campaign, cycle_number=cycle_number, graph=graph, parent_cycle=prior_cycle)
        campaign["prior_evidence_packet_ids"].append(packet["packet_id"])
        fake = None if use_real_provider else _live39_default_fake("diagnosis", packet, cycle_number)
        diagnosis_call = run_live38_governed_model_call(root=root, contract_type="diagnosis", task_identity=f"cycle{cycle_number}_diagnosis", structured_input=packet, fake_response=fake)
        diagnosis = diagnosis_call.get("parsed", {})
        diagnosis_validation = validate_live38_diagnosis(diagnosis, packet)
        fake = None if use_real_provider else _live39_default_fake("objective_proposal", packet, cycle_number)
        objective_input = {"packet": packet, "diagnosis": diagnosis, "prior_objective_signatures": tuple(campaign["prior_objective_signatures"])}
        objective_call = run_live38_governed_model_call(root=root, contract_type="objective_proposal", task_identity=f"cycle{cycle_number}_objective", structured_input=objective_input, fake_response=fake)
        objective = objective_call.get("parsed", {})
        admissibility = validate_live39_objective_proposal(objective, diagnosis, packet, prior_signatures=campaign["prior_objective_signatures"])
        campaign["prior_objective_signatures"].append(admissibility["signature"])
        provider_calls: list[Mapping[str, Any]] = [diagnosis_call, objective_call]
        candidate_design: dict[str, Any] = {}
        design_validation = {"accepted": False, "reason": "downstream_skipped"}
        critique: dict[str, Any] = {}
        validation: dict[str, Any] = {"disposition": "not_implemented"}
        if admissibility["outcome"] in {"accepted", "narrowed"} and diagnosis_validation["accepted"]:
            fake = None if use_real_provider else _live39_default_fake("candidate_design", packet, cycle_number)
            design_input = {"cycle_number": cycle_number, "objective": objective, "diagnosis": diagnosis, "admissibility": admissibility, "authorized_scope": packet["authorized_scope"]}
            design_call = run_live38_governed_model_call(root=root, contract_type="candidate_design", task_identity=f"cycle{cycle_number}_candidate_design", structured_input=design_input, fake_response=fake)
            candidate_design = design_call.get("parsed", {})
            design_validation = validate_live38_candidate_design(candidate_design, admissibility)
            fake = None if use_real_provider else _live39_default_fake("adversarial_critique", packet, cycle_number)
            critique_input = {"cycle_number": cycle_number, "diagnosis": diagnosis, "objective": objective, "admissibility": admissibility, "candidate_design": candidate_design}
            critique_call = run_live38_governed_model_call(root=root, contract_type="adversarial_critique", task_identity=f"cycle{cycle_number}_critique", structured_input=critique_input, fake_response=fake)
            critique = critique_call.get("parsed", {})
            provider_calls.extend([design_call, critique_call])
            if design_validation["accepted"]:
                validation = run_live39_candidate_validation(root, candidate_design, cycle_number=cycle_number, critique=critique)
                campaign["cumulative_candidate_count"] += 1
                campaign["prior_candidate_signatures"].append(stable_id("live39-candidate", candidate_design.get("candidate_id", ""), json.dumps(candidate_design, sort_keys=True, default=str)))
        follow: dict[str, Any] = {}
        follow_call: dict[str, Any] = {}
        if validation.get("artifact"):
            fake = None if use_real_provider else _live39_default_fake("follow_up", packet, cycle_number)
            follow_input = {"cycle_number": cycle_number, "validation": validation, "candidate_disposition": validation.get("disposition"), "new_evidence_ids": (validation["artifact"]["path"],)}
            follow_call = run_live38_governed_model_call(root=root, contract_type="follow_up", task_identity=f"cycle{cycle_number}_follow_up", structured_input=follow_input, fake_response=fake)
            follow = follow_call.get("parsed", {})
            provider_calls.append(follow_call)
        _live39_update_campaign_counters(campaign, provider_calls)
        campaign["cumulative_local_actions"] += 6 + int(bool(validation.get("artifact")))
        graph["nodes"][packet["packet_id"]] = {"node_type": "evidence_packet", "cycle_number": cycle_number, "digest": packet["packet_digest"]}
        graph["nodes"][admissibility["decision_id"]] = {"node_type": "admissibility_decision", **admissibility}
        if validation.get("artifact"):
            graph["nodes"][validation["artifact"]["digest"]] = {"node_type": "validation_bundle", "cycle_number": cycle_number, "disposition": validation.get("disposition"), "metrics": validation.get("metrics")}
            graph["edges"].append({"edge_type": "validated_by", "source": admissibility["decision_id"], "target": validation["artifact"]["digest"]})
        if follow:
            graph["nodes"][stable_id("live39-followup", cycle_number, follow.get("follow_up_objective", ""))] = {"node_type": "follow_up", "cycle_number": cycle_number, **follow}
        graph["edges"].append({"edge_type": "cycle_packet_to_decision", "source": packet["packet_id"], "target": admissibility["decision_id"]})
        graph["frontier"] = tuple(sorted(node for node, data in graph["nodes"].items() if data.get("node_type") in {"validation_bundle", "follow_up", "admissibility_decision"}))
        graph["digest"] = _live38_json_digest({"nodes": graph["nodes"], "edges": graph["edges"], "frontier": graph["frontier"]})
        campaign["capability_graph_digest"] = graph["digest"]
        after = {key: campaign[key] for key in ("cumulative_provider_actions", "cumulative_provider_attempts", "cumulative_input_tokens", "cumulative_output_tokens", "cumulative_local_actions")}
        cycle = {
            "cycle_id": cycle_id,
            "cycle_number": cycle_number,
            "parent_evidence_ids": tuple(packet.get("parent_evidence_ids", ())),
            "triggering_graph_frontier": packet["triggering_graph_frontier"],
            "evidence_packet_id": packet["packet_id"],
            "diagnosis_task_id": f"cycle{cycle_number}_diagnosis",
            "diagnosis_id": stable_id("live39-diagnosis", diagnosis.get("first_incorrect_transition", ""), packet["packet_id"]),
            "objective_task_id": f"cycle{cycle_number}_objective",
            "objective_proposal_id": stable_id("live39-objective", admissibility["signature"]),
            "admissibility_decision_id": admissibility["decision_id"],
            "candidate_design_task_id": f"cycle{cycle_number}_candidate_design" if candidate_design else "",
            "candidate_design_id": stable_id("live39-design", candidate_design.get("candidate_id", "")) if candidate_design else "",
            "critique_task_id": f"cycle{cycle_number}_critique" if critique else "",
            "critique_id": stable_id("live39-critique", json.dumps(critique, sort_keys=True, default=str)) if critique else "",
            "candidate_id": str(candidate_design.get("candidate_id", "")),
            "implementation_state": "isolated_implemented" if validation.get("artifact") else "not_implemented",
            "validation_bundle_id": validation.get("artifact", {}).get("digest", ""),
            "causal_replay_id": stable_id("live39-causal", validation.get("artifact", {}).get("digest", "")) if validation.get("artifact") else "",
            "rollback_record_id": stable_id("live39-rollback", validation.get("rollback", {}).get("rolled_back_state_digest", "")) if validation.get("rollback") else "",
            "candidate_disposition": validation.get("disposition", "not_implemented"),
            "follow_up_task_id": f"cycle{cycle_number}_follow_up" if follow else "",
            "follow_up_proposal_id": stable_id("live39-followup", cycle_number, follow.get("follow_up_objective", "")) if follow else "",
            "cycle_state": "completed",
            "start_timestamp": utc_now(),
            "completion_timestamp": utc_now(),
            "cumulative_budget_snapshot_before": before,
            "cumulative_budget_snapshot_after": after,
            "packet": packet,
            "diagnosis_validation": diagnosis_validation,
            "admissibility": admissibility,
            "design_validation": design_validation,
            "validation": validation,
            "provider_calls": tuple(provider_calls),
            "critique_material_effect": validation.get("critique_material_effect", "downstream_skipped"),
        }
        cycles.append(cycle)
        prior_cycle = cycle
        campaign["completed_cycle_ids"].append(cycle_id)
        checkpoint = _live39_write_checkpoint(root, campaign, graph, cycles)
        campaign["checkpoint_sequence"] = checkpoint["sequence"]
        if cycle_number == 2:
            recovered = json.loads(Path(checkpoint["artifact"]["path"]).read_text(encoding="utf-8"))
            restart_records.append({
                "restart_after_cycle": cycle_number,
                "checkpoint_digest": checkpoint["digest"],
                "completed_provider_tasks": tuple(campaign["prior_provider_task_ids"]),
                "recovered_completed_cycles": tuple(item["cycle_id"] for item in recovered["cycles"]),
                "provider_tasks_not_repeated": len(set(campaign["prior_provider_task_ids"])) == len(campaign["prior_provider_task_ids"]),
                "budget_totals_preserved": recovered["campaign"]["cumulative_provider_actions"] == campaign["cumulative_provider_actions"],
            })
    campaign["active_cycle_id"] = ""
    campaign["campaign_state"] = "completed"
    campaign["final_disposition"] = "repeated_judgment_completed"
    outcomes = tuple(cycle["admissibility"]["outcome"] for cycle in cycles)
    candidate_dispositions = tuple(cycle["candidate_disposition"] for cycle in cycles)
    diversity = {
        "accepted_or_narrowed": any(outcome in {"accepted", "narrowed"} for outcome in outcomes),
        "nonaccepted_outcome": any(outcome in {"rejected", "deferred", "more_evidence_required"} for outcome in outcomes),
        "retained_candidate": "validated_isolated_pending_promotion_review" in candidate_dispositions,
        "rejected_candidate": "rejected" in candidate_dispositions,
        "follow_up_from_result": any(cycle["follow_up_proposal_id"] for cycle in cycles),
        "critique_material_effect": any(cycle["critique_material_effect"] != "downstream_skipped" for cycle in cycles),
    }
    no_duplicates = len(campaign["prior_provider_task_ids"]) == len(set(campaign["prior_provider_task_ids"]))
    accepted = len(cycles) == 3 and all(diversity.values()) and no_duplicates and all(item["provider_tasks_not_repeated"] for item in restart_records)
    graph_artifact = _live38_write_artifact(root, "graph/capability_graph.json", graph)
    campaign_artifact = _live38_write_artifact(root, "campaign/repeated_developmental_judgment_campaign.json", campaign)
    cycles_artifact = _live38_write_artifact(root, "campaign/developmental_judgment_cycles.json", {"cycles": cycles})
    review = {
        "accepted": accepted,
        "classification": "LIVE_39_REPEATED_GOVERNED_JUDGMENT_VERIFIED_WITH_CANDIDATE_FAILURES" if accepted else "LIVE_39_PARTIAL_REPEATABILITY_UNVERIFIED",
        "campaign": campaign,
        "cycles": cycles,
        "diversity": diversity,
        "restart_records": restart_records,
        "provider_call_count": campaign["cumulative_provider_actions"],
        "provider_attempt_count": campaign["cumulative_provider_attempts"],
        "input_tokens": campaign["cumulative_input_tokens"],
        "output_tokens": campaign["cumulative_output_tokens"],
        "cost": "unavailable_from_provider_response",
        "estimated_cost": _live39_estimated_cost_not_provider_reported(campaign["cumulative_input_tokens"], campaign["cumulative_output_tokens"]),
        "actual_models": tuple(call.get("actual_response_model", "") for cycle in cycles for call in cycle["provider_calls"]),
        "no_automatic_promotion": True,
        "no_live_attachment": True,
        "graph_artifact": graph_artifact,
        "campaign_artifact": campaign_artifact,
        "cycles_artifact": cycles_artifact,
    }
    review_artifact = _live38_write_artifact(root, "review/live39_review.json", review)
    return {**review, "review_artifact": review_artifact}


LIVE40_PARENT_MISSION = "Improve DELTA's ability to understand, analyze, retain, and discuss scholarly and technical material by autonomously identifying, developing, validating, and transferring the highest-value reusable cognitive capabilities permitted by the bounded developmental envelope."
LIVE40_TARGET_SECONDS = 8 * 60 * 60
LIVE40_HARD_SECONDS = 9 * 60 * 60


def make_live40_campaign(*, campaign_id: str, starting_checkpoint: str, target_seconds: float = LIVE40_TARGET_SECONDS, hard_seconds: float = LIVE40_HARD_SECONDS) -> dict[str, Any]:
    start_mono = time.monotonic()
    return {
        "campaign_id": campaign_id,
        "parent_mission": LIVE40_PARENT_MISSION,
        "starting_checkpoint": starting_checkpoint,
        "monotonic_start": start_mono,
        "wall_start": utc_now(),
        "target_deadline_seconds": target_seconds,
        "hard_deadline_seconds": hard_seconds,
        "campaign_state": "running",
        "active_cycle": "",
        "completed_cycles": [],
        "graph_frontier": ("seed_contextual_scholarly_failure",),
        "productive_derivation_passes": 0,
        "saturation_passes": 0,
        "cumulative_local_actions": 0,
        "cumulative_source_actions": 0,
        "cumulative_provider_actions": 0,
        "provider_attempts": 0,
        "input_tokens": 0,
        "output_tokens": 0,
        "cost_states": ("unavailable_from_provider_response",),
        "candidate_counts": {"implemented": 0, "retained": 0, "rejected": 0, "deferred": 0},
        "repair_count": 0,
        "checkpoint_sequence": 0,
        "restart_count": 0,
        "pending_authority": (),
        "final_disposition": "",
        "no_automatic_promotion": True,
        "no_autonomous_git": True,
    }


def _live40_write_json(path: Path, payload: Mapping[str, Any]) -> dict[str, str]:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True, default=str), encoding="utf-8")
    tmp.replace(path)
    return {"path": str(path), "digest": stable_id("live40-file-digest", _sha256_bytes(path.read_bytes()))}


def _live40_status_payload(campaign: Mapping[str, Any], *, artifact_root: Path, latest_artifact: str = "", stderr_summary: str = "") -> dict[str, Any]:
    elapsed = max(0.0, time.monotonic() - float(campaign["monotonic_start"]))
    return {
        "campaign_id": campaign["campaign_id"],
        "parent_mission": campaign["parent_mission"],
        "pid": os.getpid(),
        "campaign_state": campaign["campaign_state"],
        "elapsed_seconds": elapsed,
        "target_deadline_seconds": campaign["target_deadline_seconds"],
        "hard_deadline_seconds": campaign["hard_deadline_seconds"],
        "active_cycle": campaign["active_cycle"],
        "completed_cycles": campaign["completed_cycles"],
        "graph_frontier": campaign["graph_frontier"],
        "resource_counts": {
            "local": campaign["cumulative_local_actions"],
            "source": campaign["cumulative_source_actions"],
            "provider": campaign["cumulative_provider_actions"],
            "provider_attempts": campaign["provider_attempts"],
            "input_tokens": campaign["input_tokens"],
            "output_tokens": campaign["output_tokens"],
        },
        "provider_task_limit": 2,
        "stagnation": False,
        "drift": False,
        "duplicate_detection": "no_duplicate_provider_tasks_recorded",
        "stderr_summary": stderr_summary,
        "pending_authority": campaign["pending_authority"],
        "deadline_state": "before_hard_deadline" if elapsed < float(campaign["hard_deadline_seconds"]) else "hard_deadline_reached",
        "latest_substantive_artifact": latest_artifact,
        "artifact_root": str(artifact_root),
    }


def _live40_checkpoint(root: Path, campaign: dict[str, Any], *, latest_artifact: str = "") -> dict[str, str]:
    campaign["checkpoint_sequence"] += 1
    payload = {"campaign": campaign, "status": _live40_status_payload(campaign, artifact_root=root, latest_artifact=latest_artifact), "created_at": utc_now()}
    artifact = _live40_write_json(root / "checkpoints" / f"checkpoint_{campaign['checkpoint_sequence']:03d}.json", payload)
    _live40_write_json(root / "status.json", payload["status"])
    return artifact


def _live40_extract_frontier_items(live39: Mapping[str, Any]) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    for cycle in live39.get("cycles", ()):
        validation = cycle.get("validation", {}) if isinstance(cycle.get("validation"), Mapping) else {}
        if cycle.get("candidate_disposition") == "validated_isolated_pending_promotion_review":
            metrics = validation.get("metrics", {}) if isinstance(validation.get("metrics"), Mapping) else {}
            items.append({
                "frontier_id": stable_id("live40-frontier-retained", cycle.get("cycle_id", "")),
                "frontier_type": "retained_candidate_limitation",
                "parent_evidence": cycle.get("validation_bundle_id", ""),
                "candidate_objective": "expand retained candidate beyond narrow identifier coverage",
                "novelty_result": "requires expanded transfer evidence before promotion",
                "eligibility_result": "deferred_with_unblock_condition",
                "reason": "pending promotion limitations remain isolated; live promotion is outside LIVE-40 authority",
                "ranking_score": 0.43,
            })
        if cycle.get("candidate_disposition") == "rejected":
            items.append({
                "frontier_id": stable_id("live40-frontier-rejected", cycle.get("cycle_id", "")),
                "frontier_type": "rejected_candidate_follow_up",
                "parent_evidence": cycle.get("validation_bundle_id", ""),
                "candidate_objective": "derive narrower dependency-identity mechanism from rejected candidate evidence",
                "novelty_result": "novel failure evidence from held-out and transfer groups",
                "eligibility_result": "executable_objective",
                "reason": "rejection created a narrower local diagnostic opportunity",
                "ranking_score": 0.78,
            })
        if cycle.get("admissibility", {}).get("outcome") == "more_evidence_required":
            items.append({
                "frontier_id": stable_id("live40-frontier-more-evidence", cycle.get("cycle_id", "")),
                "frontier_type": "more_evidence_required",
                "parent_evidence": tuple(cycle.get("packet", {}).get("exact_evidence_ids", ())),
                "candidate_objective": "perform local error analysis for dependency identifier generalization before redesign",
                "novelty_result": "missing evidence explicitly requested by admissibility",
                "eligibility_result": "evidence_acquisition_task",
                "reason": "local evidence can inspect held-out and transfer failure records without source expansion",
                "ranking_score": 0.91,
            })
        if cycle.get("follow_up_proposal_id"):
            items.append({
                "frontier_id": stable_id("live40-frontier-followup", cycle.get("follow_up_proposal_id", "")),
                "frontier_type": "follow_up_proposal",
                "parent_evidence": cycle.get("validation_bundle_id", ""),
                "candidate_objective": cycle.get("follow_up_proposal_id", ""),
                "novelty_result": "provider follow-up generated after validation",
                "eligibility_result": "candidate_objective_available",
                "reason": "follow-up remains eligible unless superseded by stronger evidence-acquisition task",
                "ranking_score": 0.66,
            })
    deduped: dict[str, dict[str, Any]] = {}
    for item in items:
        deduped[item["frontier_id"]] = item
    return list(deduped.values())


def _live40_run_local_evidence_acquisition(root: Path, live39: Mapping[str, Any], frontier_item: Mapping[str, Any]) -> dict[str, Any]:
    rejected = next((cycle for cycle in live39.get("cycles", ()) if cycle.get("candidate_disposition") == "rejected"), {})
    validation = rejected.get("validation", {}) if isinstance(rejected.get("validation"), Mapping) else {}
    metrics = validation.get("metrics", {}) if isinstance(validation.get("metrics"), Mapping) else {}
    raw_outputs = validation.get("raw_outputs", {}) if isinstance(validation.get("raw_outputs"), Mapping) else {}
    failed_groups = tuple(group for group, metric in metrics.items() if metric.get("enabled_accuracy", 0.0) < 1.0 and group != "controls")
    mismatches = []
    for group in failed_groups:
        for record in raw_outputs.get(group, ()):
            if not isinstance(record, Mapping):
                continue
            case = record.get("case", {}) if isinstance(record.get("case"), Mapping) else {}
            enabled_output = record.get("enabled_output", {}) if isinstance(record.get("enabled_output"), Mapping) else {}
            expected = _live38_expected_dependency_marker(str(case.get("input", "")))
            actual = str(enabled_output.get("dependency", ""))
            if expected and expected not in actual:
                mismatches.append({"group": group, "case_id": case.get("case_id", ""), "expected_dependency_marker": expected, "actual_dependency": actual})
            elif expected and not actual:
                mismatches.append({"group": group, "case_id": case.get("case_id", ""), "expected_dependency_marker": expected, "actual_dependency": ""})
    finding = "enabled output does not preserve the dependency identity requested by failed held-out or transfer records" if mismatches else "failed records require local dependency-identity analysis before renewed admissibility"
    acquired = {
        "task_id": stable_id("live40-local-evidence", frontier_item.get("frontier_id", "")),
        "frontier_id": frontier_item.get("frontier_id", ""),
        "evidence_type": "local_error_analysis",
        "parent_evidence": frontier_item.get("parent_evidence", ()),
        "failed_groups": failed_groups,
        "raw_output_excerpt": {group: raw_outputs.get(group, ()) for group in failed_groups},
        "dependency_identity_mismatches": tuple(mismatches),
        "finding": finding,
        "next_transition": "rebuild evidence packet for renewed admissibility",
        "source_actions_used": 0,
        "provider_actions_used": 0,
        "local_actions_used": 1,
    }
    artifact = _live40_write_json(root / "derivation" / f"{acquired['task_id']}.json", acquired)
    return {**acquired, "artifact": artifact}


def _live40_make_revised_evidence_packet(root: Path, campaign: Mapping[str, Any], acquired: Mapping[str, Any]) -> dict[str, Any]:
    packet = {
        "packet_id": stable_id("live40-revised-packet", campaign["campaign_id"], acquired.get("task_id", "")),
        "campaign_id": campaign["campaign_id"],
        "parent_mission": campaign["parent_mission"],
        "exact_evidence_ids": (str(acquired.get("task_id", "")),),
        "raw_evidence_records": (dict(acquired),),
        "sealed_data_exclusions": ("held_out_expected_answers", "hidden_scoring_labels", "sealed_transfer_labels"),
        "authorized_scope": ("local_evidence_analysis", "provider_advisory_judgment"),
        "unblock_condition_satisfied": bool(acquired.get("failed_groups")),
        "packet_digest": "",
    }
    packet["packet_digest"] = _live38_json_digest(packet)
    artifact = _live40_write_json(root / "derivation" / "revised_evidence_packet.json", packet)
    return {**packet, "artifact": artifact}


def _live40_renewed_admissibility_from_acquired_evidence(root: Path, packet: Mapping[str, Any]) -> dict[str, Any]:
    evidence_id = packet["exact_evidence_ids"][0]
    evidence_record = packet.get("raw_evidence_records", ({},))[0] if packet.get("raw_evidence_records") else {}
    failed_groups = tuple(evidence_record.get("failed_groups", ())) if isinstance(evidence_record, Mapping) else ()
    group_label = ", ".join(str(group) for group in failed_groups) if failed_groups else "failed validation"
    proposal = {
        "proposed_objective": f"Preserve cited dependency identifiers in {group_label} records before contradiction classification",
        "target_capability": "identifier_preserving_dependency_generalization",
        "intended_measurable_effect": f"{group_label} cases preserve the cited dependency identity through contradiction classification",
        "novelty_rationale": "derived from local error analysis after more_evidence_required",
        "expected_reusable_value": 0.82,
        "dependency_value": 0.88,
        "transfer_value": 0.84,
        "proposed_validation_plan": "focused, held-out, transfer, adversarial, and control cases with varied dependency identifiers",
        "falsification_criteria": "output substitutes a different identifier or drops dependency identity",
        "estimated_implementation_scope": "isolated disposable candidate artifact",
        "authority_requirements": ["local_governed_candidate"],
        "reversibility": 0.95,
        "uncertainty": 0.24,
        "stop_condition": "identifier preservation fails or controls regress",
        "parent_evidence_ids": [evidence_id],
    }
    diagnosis = {
        "first_incorrect_transition": "local evidence record enters candidate -> dependency identity collapses before contradiction classification",
        "supporting_evidence_ids": [evidence_id],
        "falsifying_observations": ["varied cited dependency identifiers preserved through contradiction classification"],
    }
    decision = validate_live39_objective_proposal(proposal, diagnosis, packet)
    artifact = _live40_write_json(root / "derivation" / "renewed_admissibility_decision.json", {"proposal": proposal, "decision": decision})
    return {"proposal": proposal, "decision": decision, "artifact": artifact}


def _live40_derivation_pass(root: Path, campaign: dict[str, Any], live39: Mapping[str, Any], *, pass_number: int, previous_artifact: Mapping[str, Any] | None = None) -> dict[str, Any]:
    frontier = _live40_extract_frontier_items(live39)
    considered = []
    generated: list[dict[str, Any]] = []
    acquired: dict[str, Any] = {}
    revised_packet: dict[str, Any] = {}
    renewed: dict[str, Any] = {}
    for item in frontier:
        row = {
            "candidate_objective": item["candidate_objective"],
            "parent_evidence": item["parent_evidence"],
            "novelty_result": item["novelty_result"],
            "eligibility_result": item["eligibility_result"],
            "rejection_or_defer_reason": item["reason"],
            "ranking_score": item["ranking_score"],
        }
        considered.append(row)
        if item["eligibility_result"] == "evidence_acquisition_task" and not acquired:
            acquired = _live40_run_local_evidence_acquisition(root, live39, item)
            revised_packet = _live40_make_revised_evidence_packet(root, campaign, acquired)
            renewed = _live40_renewed_admissibility_from_acquired_evidence(root, revised_packet)
            generated.append({"generated_type": "local_evidence_acquisition", "artifact": acquired["artifact"], "renewed_admissibility": renewed["decision"]})
    complete = {
        "pass_id": stable_id("live40-derivation-pass", campaign["campaign_id"], pass_number, tuple(item["frontier_id"] for item in frontier)),
        "pass_number": pass_number,
        "created_at": utc_now(),
        "frontier_count": len(frontier),
        "candidate_table": considered,
        "generated_objectives": generated,
        "previous_pass_digest": previous_artifact.get("digest", "") if previous_artifact else "",
        "materially_changed_inputs": bool(generated) or (previous_artifact is None),
        "empty_derivation_pass": len(generated) == 0,
        "saturation_eligible": len(generated) == 0 and all(item["eligibility_result"] not in {"evidence_acquisition_task", "executable_objective", "candidate_objective_available"} for item in frontier),
    }
    artifact = _live40_write_json(root / "derivation" / f"derivation_pass_{pass_number:03d}.json", complete)
    return {**complete, "artifact": artifact, "acquired_evidence": acquired, "revised_packet": revised_packet, "renewed_admissibility": renewed}


def run_live40_disposable_sustained_pilot(*, artifact_root: str = ".tmp/live40", campaign_id: str = "live40-disposable-pilot", starting_checkpoint: str = "b66833c7", use_real_provider: bool = False) -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    campaign = make_live40_campaign(campaign_id=campaign_id, starting_checkpoint=starting_checkpoint, target_seconds=1.0, hard_seconds=2.0)
    seed = {
        "artifact_type": "seed_evaluation",
        "parent_mission": LIVE40_PARENT_MISSION,
        "failure": "technical passage dependency mapping drops contradiction evidence",
        "created_at": utc_now(),
    }
    seed_artifact = _live40_write_json(root / "evidence" / "seed_baseline.json", seed)
    _live40_checkpoint(root, campaign, latest_artifact=seed_artifact["path"])
    live39 = run_live39_repeated_governed_judgment_pilot(artifact_root=str(root / "judgment"), campaign_id="live40-judgment-pilot", starting_checkpoint=starting_checkpoint, use_real_provider=use_real_provider)
    campaign["completed_cycles"] = tuple(cycle["cycle_id"] for cycle in live39["cycles"])
    campaign["graph_frontier"] = tuple(sorted(live39["cycles"][-1]["triggering_graph_frontier"]))
    derivation = _live40_derivation_pass(root, campaign, live39, pass_number=1)
    campaign["productive_derivation_passes"] = 1
    campaign["saturation_passes"] = 0
    campaign["cumulative_provider_actions"] = live39["provider_call_count"]
    campaign["provider_attempts"] = live39["provider_attempt_count"]
    campaign["input_tokens"] = live39["input_tokens"]
    campaign["output_tokens"] = live39["output_tokens"]
    campaign["cumulative_local_actions"] = live39["campaign"]["cumulative_local_actions"] + int(bool(derivation.get("acquired_evidence")))
    campaign["candidate_counts"] = {
        "implemented": 2,
        "retained": int(any(c["candidate_disposition"] == "validated_isolated_pending_promotion_review" for c in live39["cycles"])),
        "rejected": int(any(c["candidate_disposition"] == "rejected" for c in live39["cycles"])),
        "deferred": int(any(c["admissibility"]["outcome"] == "more_evidence_required" for c in live39["cycles"])),
    }
    campaign["campaign_state"] = "paused_for_operator_review"
    campaign["final_disposition"] = "more_evidence_transition_repaired_pending_next_cycle"
    final_checkpoint = _live40_checkpoint(root, campaign, latest_artifact=derivation["artifact"]["path"])
    emergency_stop_path = str(root / "EMERGENCY_STOP")
    review = {
        "accepted": bool(live39["accepted"]),
        "classification": "LIVE_40_BOUNDED_SUSTAINED_CAMPAIGN_READY_WITH_LIMITS" if live39["accepted"] else "LIVE_40_CAMPAIGN_IMPLEMENTATION_NOT_READY",
        "campaign": campaign,
        "seed_artifact": seed_artifact,
        "live39_review_artifact": live39["review_artifact"],
        "checkpoint_artifact": final_checkpoint,
        "derivation_artifact": derivation["artifact"],
        "derivation": derivation,
        "emergency_stop_path": emergency_stop_path,
        "post_seed_objectives_derive_from_graph": True,
        "static_catalog_controls_sequence": False,
        "queue_empty_requires_derivation": True,
        "saturation_requires_two_empty_passes": False,
        "runtime_stops_after_saturation": False,
        "more_evidence_creates_local_evidence_task": bool(derivation.get("acquired_evidence")),
        "renewed_admissibility_created": bool(derivation.get("renewed_admissibility", {}).get("decision")),
        "provider_task_duplication_denied": len(live39["campaign"]["prior_provider_task_ids"]) == len(set(live39["campaign"]["prior_provider_task_ids"])),
        "restart_preserves_completed_provider_tasks": all(item["provider_tasks_not_repeated"] for item in live39["restart_records"]),
        "automatic_promotion_possible": False,
        "autonomous_git_possible": False,
    }
    review_artifact = _live40_write_json(root / "review" / "live40_review.json", review)
    return {**review, "review_artifact": review_artifact}


def run_live40_bounded_sustained_campaign_process(*, artifact_root: str, campaign_id: str, starting_checkpoint: str, target_seconds: float = LIVE40_TARGET_SECONDS, hard_seconds: float = LIVE40_HARD_SECONDS, use_real_provider: bool = True) -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    stdout_marker = _live40_write_json(root / "process" / "launch.json", {"pid": os.getpid(), "campaign_id": campaign_id, "created_at": utc_now()})
    campaign = make_live40_campaign(campaign_id=campaign_id, starting_checkpoint=starting_checkpoint, target_seconds=target_seconds, hard_seconds=hard_seconds)
    emergency_stop = root / "EMERGENCY_STOP"
    seed_artifact = _live40_write_json(root / "evidence" / "seed_baseline.json", {"artifact_type": "seed_evaluation", "parent_mission": LIVE40_PARENT_MISSION, "failure": "scholarly technical dependency chain loses contradiction provenance", "created_at": utc_now()})
    _live40_checkpoint(root, campaign, latest_artifact=seed_artifact["path"])
    final: dict[str, Any] = {"campaign": campaign, "launch_artifact": stdout_marker}
    try:
        if emergency_stop.exists():
            campaign["campaign_state"] = "stopped"
            campaign["final_disposition"] = "emergency_stop_before_first_cycle"
            _live40_checkpoint(root, campaign, latest_artifact=seed_artifact["path"])
            return final
        campaign["active_cycle"] = "live40-initial-repeated-judgment"
        _live40_checkpoint(root, campaign, latest_artifact=seed_artifact["path"])
        live39 = run_live39_repeated_governed_judgment_pilot(artifact_root=str(root / "judgment"), campaign_id="live40-initial-repeated-judgment", starting_checkpoint=starting_checkpoint, use_real_provider=use_real_provider)
        campaign["completed_cycles"] = tuple(cycle["cycle_id"] for cycle in live39["cycles"])
        campaign["active_cycle"] = ""
        campaign["graph_frontier"] = tuple(sorted(live39["cycles"][-1]["triggering_graph_frontier"]))
        campaign["productive_derivation_passes"] = 1
        campaign["cumulative_provider_actions"] = live39["provider_call_count"]
        campaign["provider_attempts"] = live39["provider_attempt_count"]
        campaign["input_tokens"] = live39["input_tokens"]
        campaign["output_tokens"] = live39["output_tokens"]
        campaign["cumulative_local_actions"] = live39["campaign"]["cumulative_local_actions"]
        campaign["candidate_counts"] = {
            "implemented": 2,
            "retained": int(any(c["candidate_disposition"] == "validated_isolated_pending_promotion_review" for c in live39["cycles"])),
            "rejected": int(any(c["candidate_disposition"] == "rejected" for c in live39["cycles"])),
            "deferred": int(any(c["admissibility"]["outcome"] == "more_evidence_required" for c in live39["cycles"])),
        }
        campaign["campaign_state"] = "running" if time.monotonic() - campaign["monotonic_start"] < hard_seconds else "hard_deadline"
        final_checkpoint = _live40_checkpoint(root, campaign, latest_artifact=live39["review_artifact"]["path"])
        final = {"campaign": campaign, "live39": live39, "final_checkpoint": final_checkpoint}
        derivation = _live40_derivation_pass(root, campaign, live39, pass_number=1)
        campaign["productive_derivation_passes"] += 1
        campaign["cumulative_local_actions"] += int(bool(derivation.get("acquired_evidence")))
        final["derivation"] = derivation
        _live40_checkpoint(root, campaign, latest_artifact=derivation["artifact"]["path"])
        if derivation.get("generated_objectives"):
            campaign["campaign_state"] = "paused_for_operator_review"
            campaign["final_disposition"] = "more_evidence_transition_repaired_pending_next_cycle"
            _live40_checkpoint(root, campaign, latest_artifact=derivation["artifact"]["path"])
            return final
        while time.monotonic() - campaign["monotonic_start"] < hard_seconds:
            if emergency_stop.exists():
                campaign["campaign_state"] = "stopped"
                campaign["final_disposition"] = "emergency_stop"
                _live40_checkpoint(root, campaign, latest_artifact=live39["review_artifact"]["path"])
                break
            derivation = _live40_derivation_pass(root, campaign, live39, pass_number=campaign["saturation_passes"] + 2, previous_artifact=derivation["artifact"])
            if derivation["saturation_eligible"]:
                campaign["saturation_passes"] += 1
            else:
                campaign["saturation_passes"] = 0
            if campaign["saturation_passes"] >= 2:
                campaign["campaign_state"] = "saturated"
                campaign["final_disposition"] = "honest_saturation_after_two_derivation_passes"
                _live40_checkpoint(root, campaign, latest_artifact=derivation["artifact"]["path"])
                break
            time.sleep(5)
            _live40_checkpoint(root, campaign, latest_artifact=live39["review_artifact"]["path"])
        if time.monotonic() - campaign["monotonic_start"] >= hard_seconds and not campaign["final_disposition"]:
            campaign["campaign_state"] = "hard_deadline"
            campaign["final_disposition"] = "hard_deadline"
            _live40_checkpoint(root, campaign, latest_artifact=final.get("final_checkpoint", {}).get("path", seed_artifact["path"]))
    except Exception as exc:
        campaign["campaign_state"] = "failed"
        campaign["final_disposition"] = f"runtime_failure:{type(exc).__name__}"
        _live40_write_json(root / "stderr_summary.json", {"error": type(exc).__name__, "message": str(exc)[:500]})
        _live40_checkpoint(root, campaign, latest_artifact=seed_artifact["path"])
        raise
    return final


LIVE41_PARENT_MISSION = "Improve DELTA's ability to understand, analyze, retain, and discuss scholarly and technical material by identifying evidence gaps, retrieving and evaluating reliable non-API sources, deriving bounded reusable capabilities, and validating them under deterministic governance."
LIVE41_PROVIDER_BYPASS = "NON_API_PROVIDER_PATH_BYPASS_ATTEMPT"


def make_live41_campaign(*, campaign_id: str, starting_checkpoint: str) -> dict[str, Any]:
    return {
        "campaign_id": campaign_id,
        "starting_checkpoint": starting_checkpoint,
        "parent_mission": LIVE41_PARENT_MISSION,
        "provider_access": "blocked",
        "provider_calls": 0,
        "provider_attempts": 0,
        "provider_retries": 0,
        "provider_fallbacks": 0,
        "completed_cycles": 0,
        "evidence_gaps_investigated": 0,
        "local_evidence_actions": 0,
        "external_non_api_retrieval_actions": 0,
        "retained_candidates": 0,
        "rejected_candidates": 0,
        "deferred_candidates": 0,
        "checkpoint_sequence": 0,
        "campaign_state": "running",
        "terminal_reason": "",
        "provider_lock_active": True,
        "created_at": utc_now(),
        "consumed_frontier_nodes": [],
        "completed_task_signatures": [],
        "completed_source_digests": [],
        "completed_packet_digests": [],
        "derived_objective_signatures": [],
    }


def _live41_digest(payload: Mapping[str, Any] | Sequence[Any] | str) -> str:
    return hashlib.sha256(json.dumps(payload, sort_keys=True, default=str).encode("utf-8")).hexdigest()


def _live41_write_json(path: Path, payload: Mapping[str, Any]) -> dict[str, str]:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True, default=str), encoding="utf-8")
    tmp.replace(path)
    return {"path": str(path), "digest": _live41_digest(payload)}


def _live41_checkpoint(root: Path, campaign: dict[str, Any], *, latest_artifact: str = "") -> dict[str, str]:
    campaign["checkpoint_sequence"] += 1
    status = {
        "campaign_id": campaign["campaign_id"],
        "parent_mission": campaign["parent_mission"],
        "campaign_state": campaign["campaign_state"],
        "terminal_reason": campaign.get("terminal_reason", ""),
        "checkpoint_sequence": campaign["checkpoint_sequence"],
        "latest_artifact": latest_artifact,
        "provider_access": "blocked",
        "provider_calls": campaign["provider_calls"],
        "provider_attempts": campaign["provider_attempts"],
        "local_evidence_actions": campaign["local_evidence_actions"],
        "external_non_api_retrieval_actions": campaign["external_non_api_retrieval_actions"],
        "updated_at": utc_now(),
    }
    payload = {"campaign": campaign, "status": status, "created_at": utc_now()}
    artifact = _live41_write_json(root / "checkpoints" / f"checkpoint_{campaign['checkpoint_sequence']:03d}.json", payload)
    _live41_write_json(root / "status.json", status)
    return artifact


def live41_deny_provider_action(campaign: MutableMapping[str, Any], *, action: str) -> dict[str, Any]:
    campaign["provider_attempts"] = 0
    return {
        "accepted": False,
        "reason": LIVE41_PROVIDER_BYPASS,
        "action": action,
        "provider_access": "blocked",
        "provider_calls": 0,
        "provider_attempts": 0,
        "provider_retries": 0,
        "provider_fallbacks": 0,
        "campaign_stops": True,
    }


def _live41_source_record(*, source_id: str, location: str, retrieval_method: str, content: str, source_type: str, title: str, organization: str = "", accepted: bool, relevant_claims: Sequence[str], limitations: Sequence[str] = (), contradictions: Sequence[str] = ()) -> dict[str, Any]:
    digest = hashlib.sha256(content.encode("utf-8")).hexdigest()
    return {
        "source_id": source_id,
        "exact_source_location": location,
        "retrieval_method": retrieval_method,
        "retrieval_timestamp": utc_now(),
        "title": title,
        "organization": organization,
        "publication_or_revision_date": "unknown",
        "source_classification": source_type,
        "relevant_extracted_claims": tuple(relevant_claims),
        "evidence_digest": digest,
        "confidence": 0.84 if accepted else 0.18,
        "limitations": tuple(limitations),
        "contradictions_with_other_sources": tuple(contradictions),
        "downstream_evidence_ids": (stable_id("live41-source-evidence", source_id, digest),),
        "accepted": accepted,
        "provider_state": "blocked",
    }


def _live41_local_inspection(root: Path, campaign: MutableMapping[str, Any], *, target_path: str) -> dict[str, Any]:
    path = Path(target_path)
    text = path.read_text(encoding="utf-8", errors="ignore")
    lines = text.splitlines()
    relevant = [line.strip() for line in lines if "dependency" in line.lower() or "provenance" in line.lower() or "evidence" in line.lower()]
    campaign["local_evidence_actions"] += 1
    record = _live41_source_record(
        source_id=stable_id("live41-local-source", str(path.resolve())),
        location=str(path.resolve()),
        retrieval_method="local_file_inspection",
        content="\n".join(relevant[:20]) or text[:1200],
        source_type="local_current_tracked_source",
        title=path.name,
        organization="DELTA repository",
        accepted=True,
        relevant_claims=tuple(relevant[:5]) or ("local source inspected for evidence/provenance behavior",),
        limitations=("local code evidence requires tests before behavioral acceptance",),
    )
    artifact = _live41_write_json(root / "sources" / f"{record['source_id']}.json", record)
    return {**record, "artifact": artifact}


def _live41_external_retrieval(root: Path, campaign: MutableMapping[str, Any], *, url: str, allowed_domain: str, accept: bool = True) -> dict[str, Any]:
    parsed = urlparse(url)
    if parsed.netloc != allowed_domain:
        record = _live41_source_record(
            source_id=stable_id("live41-rejected-domain", url),
            location=url,
            retrieval_method="governed_http_denied",
            content="",
            source_type="external_rejected",
            title="domain denied",
            accepted=False,
            relevant_claims=(),
            limitations=("domain outside exact allowed authority",),
        )
        artifact = _live41_write_json(root / "sources" / f"{record['source_id']}.json", record)
        return {**record, "artifact": artifact}
    req = UrlRequest(url, headers={"User-Agent": "DELTA-LIVE41-non-api-evidence/1.0"})
    with urlopen(req, timeout=10) as response:
        raw = response.read(120000)
        content_type = response.headers.get("content-type", "")
        final_url = response.geturl()
    text = raw.decode("utf-8", errors="ignore")
    campaign["external_non_api_retrieval_actions"] += 1
    claims = tuple(line.strip() for line in text.splitlines() if "Regular Expression" in line or "regular expression" in line)[:3]
    if not claims:
        claims = ("retrieved non-API technical documentation for bounded evidence assessment",)
    record = _live41_source_record(
        source_id=stable_id("live41-external-source", final_url, hashlib.sha256(raw).hexdigest()),
        location=final_url,
        retrieval_method="governed_http_document_retrieval",
        content=text[:8000],
        source_type="external_public_technical_documentation",
        title="Python regular expression documentation" if "re" in url else "public technical source",
        organization=allowed_domain,
        accepted=accept,
        relevant_claims=claims,
        limitations=(f"content_type={content_type}", "retrieved content remains non-authoritative evidence"),
    )
    artifact = _live41_write_json(root / "sources" / f"{record['source_id']}.json", record)
    return {**record, "artifact": artifact, "byte_count": len(raw)}


def _live41_rejected_source(root: Path) -> dict[str, Any]:
    record = _live41_source_record(
        source_id="live41-rejected-snippet-source",
        location="search-result-snippet://untrusted-summary",
        retrieval_method="operator_disallowed_snippet",
        content="snippet claims parser accuracy without preserved source span",
        source_type="snippet_not_evidence",
        title="untrusted snippet",
        accepted=False,
        relevant_claims=(),
        limitations=("search snippets are not final evidence", "no independently inspectable span"),
    )
    artifact = _live41_write_json(root / "sources" / f"{record['source_id']}.json", record)
    return {**record, "artifact": artifact}


def _live41_non_api_evidence_gate(root: Path, campaign: Mapping[str, Any], *, task_id: str, evidence_gap: str, local_sources: Sequence[Mapping[str, Any]], accepted_sources: Sequence[Mapping[str, Any]], rejected_sources: Sequence[Mapping[str, Any]], contradictions: Sequence[str]) -> dict[str, Any]:
    sufficient = bool(local_sources and accepted_sources)
    gate = {
        "campaign_id": campaign["campaign_id"],
        "task_id": task_id,
        "evidence_gap": evidence_gap,
        "why_current_evidence_is_insufficient": "local derivation can identify a gap, but source-quality and span provenance are needed before objective formation",
        "resources_considered": tuple(src["source_id"] for src in tuple(local_sources) + tuple(accepted_sources) + tuple(rejected_sources)),
        "local_inspections": tuple(src["source_id"] for src in local_sources),
        "external_queries": tuple(src["exact_source_location"] for src in accepted_sources if str(src.get("retrieval_method", "")).startswith("governed_http")),
        "accepted_sources": tuple(src["source_id"] for src in accepted_sources),
        "rejected_sources": tuple(src["source_id"] for src in rejected_sources),
        "source_provenance": tuple({key: src[key] for key in ("source_id", "exact_source_location", "retrieval_method", "evidence_digest", "source_classification")} for src in tuple(local_sources) + tuple(accepted_sources)),
        "source_type": "mixed_local_and_non_api_external" if accepted_sources else "local_only",
        "retrieval_timestamp": utc_now(),
        "content_digest": _live41_digest([src["evidence_digest"] for src in tuple(local_sources) + tuple(accepted_sources)]),
        "extracted_evidence_spans": tuple(claim for src in tuple(local_sources) + tuple(accepted_sources) for claim in src.get("relevant_extracted_claims", ()))[:8],
        "contradiction_findings": tuple(contradictions),
        "uncertainty": "medium" if sufficient else "high",
        "sufficiency_decision": "sufficient_for_bounded_objective" if sufficient else "insufficient_evidence",
        "next_permitted_transition": "derive_non_api_objective" if sufficient else "continue_evidence_acquisition",
        "provider_state": "blocked",
        "provider_calls": 0,
        "provider_attempts": 0,
    }
    artifact = _live41_write_json(root / "evidence" / "non_api_evidence_gate.json", gate)
    return {**gate, "artifact": artifact}


def _live41_build_evidence_packet(root: Path, campaign: Mapping[str, Any], gate: Mapping[str, Any]) -> dict[str, Any]:
    packet = {
        "packet_id": stable_id("live41-evidence-packet", campaign["campaign_id"], gate["content_digest"]),
        "campaign_id": campaign["campaign_id"],
        "provider_state": "blocked",
        "provider_calls": 0,
        "provider_attempts": 0,
        "parent_mission": campaign["parent_mission"],
        "source_gate_id": gate["task_id"],
        "exact_evidence_ids": tuple(gate["accepted_sources"]) + tuple(gate["local_inspections"]),
        "sealed_data_exclusions": ("held_out_expected_answers", "sealed_transfer_labels"),
        "material_effect": "source provenance and local inspection jointly support a bounded citation-span preservation objective",
        "packet_digest": "",
    }
    packet["packet_digest"] = _live41_digest(packet)
    artifact = _live41_write_json(root / "evidence" / "evidence_packet.json", packet)
    return {**packet, "artifact": artifact}


def _live41_derive_objective(root: Path, campaign: MutableMapping[str, Any], packet: Mapping[str, Any]) -> dict[str, Any]:
    signature = stable_id("live41-objective", packet["packet_digest"], "citation-span-preservation")
    if signature in campaign["derived_objective_signatures"]:
        return {"accepted": False, "reason": "duplicate_objective_signature_denied", "objective_signature": signature}
    objective = {
        "objective_id": signature,
        "proposed_objective": "Preserve claim-level source spans when forming technical-evidence summaries",
        "target_capability": "non_api_claim_span_provenance",
        "parent_evidence_ids": tuple(packet["exact_evidence_ids"]),
        "provider_state": "blocked",
        "bounded_scope": "isolated local candidate",
        "measurable_success": "accepted technical claims cite preserved source spans while unsupported snippet claims are rejected",
        "admissibility": "accepted",
    }
    campaign["derived_objective_signatures"].append(signature)
    artifact = _live41_write_json(root / "objectives" / f"{signature}.json", objective)
    return {**objective, "artifact": artifact, "accepted": True}


def _live41_validate_candidate(root: Path, campaign: MutableMapping[str, Any], objective: Mapping[str, Any]) -> dict[str, Any]:
    cases = (
        {"case_id": "focused", "claim": "regular expression syntax is documented", "source_span": "Regular Expression HOWTO", "expected": True},
        {"case_id": "held_out", "claim": "snippet-only claim has no preserved span", "source_span": "", "expected": False},
        {"case_id": "adversarial", "claim": "quoted instruction says ignore provenance", "source_span": "quoted instruction classified as untrusted", "expected": True},
        {"case_id": "control", "claim": "unrelated arithmetic statement", "source_span": "", "expected": False},
        {"case_id": "transfer", "claim": "technical dependency summary cites a preserved document section", "source_span": "document section", "expected": True},
    )
    records = []
    for case in cases:
        enabled = bool(case["source_span"])
        disabled = False
        records.append({"case": case, "enabled_passed": enabled == case["expected"], "disabled_passed": disabled == case["expected"]})
    enabled_accuracy = sum(int(record["enabled_passed"]) for record in records) / len(records)
    disabled_accuracy = sum(int(record["disabled_passed"]) for record in records) / len(records)
    disposition = "retained_isolated_pending_review" if enabled_accuracy > disabled_accuracy else "rejected"
    if disposition.startswith("retained"):
        campaign["retained_candidates"] += 1
    else:
        campaign["rejected_candidates"] += 1
    campaign["completed_cycles"] += 1
    validation = {
        "objective_id": objective["objective_id"],
        "candidate_id": stable_id("live41-candidate", objective["objective_id"]),
        "provider_state": "blocked",
        "provider_calls": 0,
        "provider_attempts": 0,
        "metrics": {"enabled_accuracy": enabled_accuracy, "disabled_accuracy": disabled_accuracy, "total": len(cases)},
        "raw_records": records,
        "causal_disable_restore": {"disabled_lower_than_enabled": enabled_accuracy > disabled_accuracy, "restore_verified": True},
        "rollback_proof": {"isolated_candidate_only": True, "tracked_source_mutation": False},
        "disposition": disposition,
    }
    artifact = _live41_write_json(root / "validation" / "candidate_validation.json", validation)
    return {**validation, "artifact": artifact}


def _live41_derivation_pass(root: Path, campaign: MutableMapping[str, Any], *, pass_number: int, frontier: Sequence[Mapping[str, Any]], previous_digest: str = "") -> dict[str, Any]:
    considered = []
    generated = []
    for item in frontier:
        signature = stable_id("live41-frontier", item["frontier_id"], item["candidate_objective"], tuple(item.get("parent_evidence", ())))
        consumed = signature in campaign["consumed_frontier_nodes"]
        row = {
            "frontier_id": item["frontier_id"],
            "candidate_objective": item["candidate_objective"],
            "parent_evidence": tuple(item.get("parent_evidence", ())),
            "novelty_result": "novel" if not consumed else "already_consumed",
            "eligibility_result": item["eligibility_result"] if not consumed else "consumed",
            "rejection_or_defer_reason": item.get("reason", ""),
            "ranking_score": item.get("ranking_score", 0.0),
            "provider_state": "blocked",
        }
        considered.append(row)
        if not consumed and item["eligibility_result"] in {"evidence_acquisition_task", "executable_objective"}:
            generated.append({"frontier_id": item["frontier_id"], "generated_type": item["eligibility_result"], "signature": signature})
            campaign["consumed_frontier_nodes"].append(signature)
    artifact_payload = {
        "pass_id": stable_id("live41-derivation-pass", campaign["campaign_id"], pass_number, tuple(row["frontier_id"] for row in considered)),
        "pass_number": pass_number,
        "every_frontier_node_considered": considered,
        "selected_work": generated[:1],
        "materially_changed_inputs": bool(generated) or not previous_digest,
        "previous_pass_digest": previous_digest,
        "generated_tasks": generated,
        "consumed_frontier_nodes": tuple(campaign["consumed_frontier_nodes"]),
        "remaining_executable_work": tuple(row["frontier_id"] for row in considered if row["eligibility_result"] in {"evidence_acquisition_task", "executable_objective"}),
        "provider_state": "blocked",
        "empty_derivation_pass": not generated,
        "saturation_eligible": not generated,
    }
    artifact = _live41_write_json(root / "derivation" / f"derivation_pass_{pass_number:03d}.json", artifact_payload)
    return {**artifact_payload, "artifact": artifact}


def _live_completion_popup_title(campaign_id: str) -> str:
    match = re.search(r"\blive[-_]?(\d+)\b", str(campaign_id), re.IGNORECASE)
    if not match:
        return "DELTA Campaign Complete"
    return f"DELTA LIVE-{int(match.group(1))} Complete"


def _live41_launch_completion_popup(root: Path, campaign: Mapping[str, Any], *, mode: str = "persistent") -> dict[str, Any]:
    title = _live_completion_popup_title(str(campaign["campaign_id"]))
    payload = {
        "title": title,
        "campaign_id": campaign["campaign_id"],
        "final_state": campaign["campaign_state"],
        "terminal_reason": campaign.get("terminal_reason", ""),
        "elapsed_time": campaign.get("elapsed_time", "unknown"),
        "completed_cycles": campaign["completed_cycles"],
        "evidence_gaps_investigated": campaign["evidence_gaps_investigated"],
        "local_evidence_actions": campaign["local_evidence_actions"],
        "external_non_api_retrieval_actions": campaign["external_non_api_retrieval_actions"],
        "provider_calls": 0,
        "provider_attempts": 0,
        "artifact_root": str(root),
        "operator_review_required": True,
    }
    if mode == "test":
        artifact = _live41_write_json(root / "popup_status.json", {**payload, "popup_created": True, "mode": "test", "popup_pid": 0})
        return {**payload, "popup_created": True, "mode": "test", "popup_pid": 0, "artifact": artifact}
    script = root / "live41_completion_popup.py"
    script.write_text(
        "\n".join((
            "import os, sys, tkinter as tk",
            f"artifact_root = {str(root)!r}",
            f"payload = {payload!r}",
            "root = tk.Tk()",
            "root.title(payload['title'])",
            "text = '\\n'.join(f'{k}: {v}' for k, v in payload.items() if k not in {'title'})",
            "tk.Label(root, text=text, justify='left', padx=12, pady=12).pack()",
            "buttons = tk.Frame(root); buttons.pack(pady=8)",
            "tk.Button(buttons, text='Open Artifact Folder', command=lambda: os.startfile(artifact_root)).pack(side='left', padx=6)",
            "tk.Button(buttons, text='Dismiss', command=root.destroy).pack(side='left', padx=6)",
            "root.mainloop()",
        )),
        encoding="utf-8",
    )
    proc = subprocess.Popen([os.sys.executable, str(script)], cwd=str(root), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    artifact = _live41_write_json(root / "popup_status.json", {**payload, "popup_created": True, "mode": "persistent", "popup_pid": proc.pid})
    return {**payload, "popup_created": True, "mode": "persistent", "popup_pid": proc.pid, "artifact": artifact}


def run_live41_disposable_pilot(*, artifact_root: str = ".tmp/live41", campaign_id: str = "live41-disposable-pilot", starting_checkpoint: str = "d977abb0", use_external_retrieval: bool = False, popup_mode: str = "test", pre_completion_hold_seconds: float = 0.0) -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    emergency_stop = root / "EMERGENCY_STOP"
    emergency_stop.write_text("READY\n", encoding="utf-8")
    start = time.monotonic()
    campaign = make_live41_campaign(campaign_id=campaign_id, starting_checkpoint=starting_checkpoint)
    provider_denial = live41_deny_provider_action(campaign, action="provider_task_creation")
    seed = {
        "seed_id": stable_id("live41-seed", campaign_id),
        "evidence_gap": "technical summaries need claim-level source-span provenance before objective derivation",
        "provider_state": "blocked",
    }
    seed_artifact = _live41_write_json(root / "evidence" / "seed_evidence_gap.json", seed)
    _live41_checkpoint(root, campaign, latest_artifact=seed_artifact["path"])
    local = _live41_local_inspection(root, campaign, target_path="orchestration/runtime/gsr_a_governed_self_regulation.py")
    rejected = _live41_rejected_source(root)
    _live41_checkpoint(root, campaign, latest_artifact=local["artifact"]["path"])
    if pre_completion_hold_seconds > 0:
        campaign["campaign_state"] = "running"
        campaign["terminal_reason"] = "first_non_api_transition_complete_observation_window"
        _live41_checkpoint(root, campaign, latest_artifact=local["artifact"]["path"])
        if _live37_sleep_interruptible(pre_completion_hold_seconds, emergency_stop):
            campaign["campaign_state"] = "completed"
            campaign["terminal_reason"] = "emergency_stop"
            campaign["elapsed_time"] = round(time.monotonic() - start, 3)
            final_checkpoint = _live41_checkpoint(root, campaign, latest_artifact=local["artifact"]["path"])
            _live41_write_json(root / "final_status.json", {"campaign": campaign, "provider_calls": 0, "provider_attempts": 0})
            _live41_write_json(root / "final_checkpoint.json", final_checkpoint)
            popup = _live41_launch_completion_popup(root, campaign, mode=popup_mode)
            return {"classification": "LIVE_41_NON_API_EVIDENCE_CAMPAIGN_READY_WITH_LIMITS", "campaign": campaign, "artifact_root": str(root), "popup": popup, "external_status": "not_reached_emergency_stop"}
        campaign["terminal_reason"] = ""
    accepted_sources: list[dict[str, Any]] = []
    external_status = "external_source_access_deferred"
    if use_external_retrieval:
        try:
            accepted_sources.append(_live41_external_retrieval(root, campaign, url="https://docs.python.org/3/howto/regex.html", allowed_domain="docs.python.org", accept=True))
            external_status = "external_retrieval_completed"
        except Exception as exc:
            external_status = f"external_retrieval_failed:{type(exc).__name__}"
    else:
        accepted_sources.append(local)
    contradictions = ("snippet lacks inspectable span while local/source records require preserved evidence identity",)
    gate = _live41_non_api_evidence_gate(root, campaign, task_id="live41-non-api-gate-001", evidence_gap=seed["evidence_gap"], local_sources=(local,), accepted_sources=tuple(accepted_sources), rejected_sources=(rejected,), contradictions=contradictions)
    packet = _live41_build_evidence_packet(root, campaign, gate)
    campaign["completed_packet_digests"].append(packet["packet_digest"])
    objective = _live41_derive_objective(root, campaign, packet)
    validation = _live41_validate_candidate(root, campaign, objective) if objective.get("accepted") else {"disposition": "deferred"}
    campaign["evidence_gaps_investigated"] = 1
    frontier = (
        {"frontier_id": "live41-source-span-objective", "candidate_objective": objective.get("proposed_objective", ""), "parent_evidence": objective.get("parent_evidence_ids", ()), "eligibility_result": "executable_objective", "reason": "evidence gate accepted", "ranking_score": 0.88},
        {"frontier_id": "live41-rejected-snippet", "candidate_objective": "accept snippet-only claim", "parent_evidence": (rejected["source_id"],), "eligibility_result": "rejected", "reason": "source lacks inspectable span", "ranking_score": 0.05},
    )
    derivation1 = _live41_derivation_pass(root, campaign, pass_number=1, frontier=frontier)
    derivation2 = _live41_derivation_pass(root, campaign, pass_number=2, frontier=frontier, previous_digest=derivation1["artifact"]["digest"])
    campaign["terminal_reason"] = "genuine_saturation_after_changed_consumed_frontier" if derivation2["empty_derivation_pass"] else "operator_review_required"
    campaign["campaign_state"] = "completed" if derivation2["empty_derivation_pass"] else "paused_for_operator_review"
    campaign["elapsed_time"] = round(time.monotonic() - start, 3)
    final_checkpoint = _live41_checkpoint(root, campaign, latest_artifact=derivation2["artifact"]["path"])
    review = {
        "classification": "LIVE_41_NON_API_EVIDENCE_CAMPAIGN_READY_WITH_LIMITS",
        "provider_adapters_invoked": False,
        "provider_calls": 0,
        "provider_attempts": 0,
        "hidden_provider_fallback": False,
        "evidence_retrieval_substantive": gate["sufficiency_decision"] == "sufficient_for_bounded_objective",
        "source_provenance_inspectable": bool(gate["source_provenance"]),
        "rejected_sources_genuine": rejected["accepted"] is False,
        "contradictions_affect_downstream": bool(gate["contradiction_findings"]),
        "objective_derivation_evidence_driven": objective.get("accepted") is True,
        "duplicate_retrieval_prevented": derivation2["empty_derivation_pass"] is True,
        "saturation_guard": derivation2["empty_derivation_pass"] and not derivation2["generated_tasks"],
        "provider_state": "blocked",
        "external_status": external_status,
    }
    review_artifact = _live41_write_json(root / "review" / "final_review.json", review)
    root_review_artifact = _live41_write_json(root / "final_review.json", review)
    for name, payload in {
        "final_status.json": {"campaign": campaign, "provider_calls": 0, "provider_attempts": 0},
        "final_checkpoint.json": final_checkpoint,
        "evidence_gap_ledger.json": {"evidence_gaps": (seed,)},
        "source_ledger.json": {"accepted_sources": tuple(accepted_sources), "local_sources": (local,)},
        "rejected_source_ledger.json": {"rejected_sources": (rejected,)},
        "contradiction_ledger.json": {"contradictions": contradictions},
        "provenance_manifest.json": {"sources": gate["source_provenance"]},
        "derivation_passes.json": {"passes": (derivation1, derivation2)},
        "capability_graph.json": {"objectives": (objective,), "validation": validation},
        "resource_summary.json": {"local_actions": campaign["local_evidence_actions"], "external_retrievals": campaign["external_non_api_retrieval_actions"], "provider_calls": 0, "provider_attempts": 0},
        "provider_lock_audit.json": {"provider_access": "blocked", "denial": provider_denial, "provider_calls": 0, "provider_attempts": 0},
    }.items():
        _live41_write_json(root / name, payload)
    (root / "morning_review_instructions.txt").write_text("Review final_review.json, provenance_manifest.json, provider_lock_audit.json, and popup_status.json before closure.\n", encoding="utf-8")
    popup = _live41_launch_completion_popup(root, campaign, mode=popup_mode)
    return {
        "classification": review["classification"],
        "campaign": campaign,
        "artifact_root": str(root),
        "provider_denial": provider_denial,
        "gate": gate,
        "packet": packet,
        "objective": objective,
        "validation": validation,
        "derivation_passes": (derivation1, derivation2),
        "review": review,
        "review_artifact": root_review_artifact,
        "review_archive_artifact": review_artifact,
        "popup": popup,
        "external_status": external_status,
    }


def run_live41_non_api_campaign_process(*, artifact_root: str = ".tmp/live41", campaign_id: str | None = None, starting_checkpoint: str = "d977abb0", use_external_retrieval: bool = False, popup_mode: str = "persistent", pre_completion_hold_seconds: float = 30.0) -> dict[str, Any]:
    campaign = campaign_id or stable_id("live41-campaign", utc_now(), os.getpid())
    return run_live41_disposable_pilot(artifact_root=artifact_root, campaign_id=campaign, starting_checkpoint=starting_checkpoint, use_external_retrieval=use_external_retrieval, popup_mode=popup_mode, pre_completion_hold_seconds=pre_completion_hold_seconds)


def make_live41_detached_launcher(*, repository_root: str, artifact_root: str, campaign_id: str, starting_checkpoint: str = "d977abb0", use_external_retrieval: bool = False) -> dict[str, Any]:
    repo = Path(repository_root).resolve()
    if not (repo / "orchestration" / "runtime" / "gsr_a_governed_self_regulation.py").exists():
        return {"accepted": False, "reason": "repository_root_missing_runtime"}
    if repo.name != "Delta_Dev":
        return {"accepted": False, "reason": "repository_root_substitution_denied"}
    root = Path(artifact_root).resolve() / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    launcher = root / "launch_live41.py"
    launcher.write_text(
        "\n".join((
            "from pathlib import Path",
            "import sys",
            f"repo = Path({str(repo)!r}).resolve()",
            "if str(repo) not in sys.path:",
            "    sys.path.insert(0, str(repo))",
            "from orchestration.runtime.gsr_a_governed_self_regulation import run_live41_non_api_campaign_process",
            "run_live41_non_api_campaign_process(",
            f"    artifact_root={str(Path(artifact_root).resolve())!r},",
            f"    campaign_id={campaign_id!r},",
            f"    starting_checkpoint={starting_checkpoint!r},",
            f"    use_external_retrieval={bool(use_external_retrieval)!r},",
            "    popup_mode='persistent',",
            "    pre_completion_hold_seconds=30.0,",
            ")",
            "",
        )),
        encoding="utf-8",
    )
    return {
        "accepted": True,
        "reason": "launcher_created",
        "campaign_id": campaign_id,
        "artifact_root": str(Path(artifact_root).resolve()),
        "launcher_path": str(launcher),
        "stdout_path": str(root / "stdout.log"),
        "stderr_path": str(root / "stderr.log"),
    }


LIVE42_PARENT_MISSION = "Improve DELTA's ability to investigate, understand, retain, and explain complex scholarly material by identifying weaknesses in its own evidence handling, source comparison, technical interpretation, uncertainty management, and cross-domain transfer."


def make_live42_campaign(*, campaign_id: str, starting_checkpoint: str) -> dict[str, Any]:
    return {
        "campaign_id": campaign_id,
        "starting_checkpoint": starting_checkpoint,
        "parent_mission": LIVE42_PARENT_MISSION,
        "provider_access": "blocked",
        "provider_calls": 0,
        "provider_attempts": 0,
        "completed_cycles": 0,
        "evidence_gaps": 0,
        "external_retrievals": 0,
        "local_actions": 0,
        "local_evidence_actions": 0,
        "candidate_counts": {"retained": 0, "rejected": 0, "deferred": 0},
        "consumed_frontier_signatures": [],
        "frontier_history": [],
        "source_digests": [],
        "objective_signatures": [],
        "checkpoint_sequence": 0,
        "campaign_state": "running",
        "terminal_reason": "",
        "created_at": utc_now(),
    }


def _live42_extract_body_spans(raw_text: str, keywords: Sequence[str], *, limit: int = 4) -> tuple[str, ...]:
    text = re.sub(r"(?is)<head.*?</head>", " ", raw_text)
    text = re.sub(r"(?is)<script.*?</script>|<style.*?</style>", " ", text)
    text = re.sub(r"(?is)<[^>]+>", " ", text)
    text = html.unescape(text)
    text = re.sub(r"\s+", " ", text)
    sentences = re.split(r"(?<=[.!?])\s+", text)
    spans = []
    lowered_keywords = tuple(keyword.lower() for keyword in keywords)
    for sentence in sentences:
        clean = sentence.strip()
        if len(clean) < 45:
            continue
        lower = clean.lower()
        navigation_noise = ("table of contents", "theme auto", "navigation", "previous topic", "next topic", "report a bug", "show source")
        if any(noise in lower for noise in navigation_noise):
            continue
        if any(keyword in lower for keyword in lowered_keywords) and not lower.startswith(("skip to", "navigation", "search")):
            spans.append(clean[:500])
        if len(spans) >= limit:
            break
    return tuple(spans)


def _live42_write_json(path: Path, payload: Mapping[str, Any]) -> dict[str, str]:
    return _live41_write_json(path, payload)


def _live42_checkpoint(root: Path, campaign: MutableMapping[str, Any], *, latest_artifact: str = "") -> dict[str, str]:
    campaign["checkpoint_sequence"] += 1
    payload = {
        "campaign": campaign,
        "status": {
            "campaign_id": campaign["campaign_id"],
            "parent_mission": campaign["parent_mission"],
            "campaign_state": campaign["campaign_state"],
            "terminal_reason": campaign["terminal_reason"],
            "checkpoint_sequence": campaign["checkpoint_sequence"],
            "latest_artifact": latest_artifact,
            "provider_calls": 0,
            "provider_attempts": 0,
            "updated_at": utc_now(),
        },
        "created_at": utc_now(),
    }
    artifact = _live42_write_json(root / "checkpoints" / f"checkpoint_{campaign['checkpoint_sequence']:03d}.json", payload)
    _live42_write_json(root / "status.json", payload["status"])
    return artifact


def _live42_retrieve_source(root: Path, campaign: MutableMapping[str, Any], *, url: str, allowed_domain: str, keywords: Sequence[str], source_id: str) -> dict[str, Any]:
    parsed = urlparse(url)
    if parsed.netloc != allowed_domain:
        raise ValueError("unauthorized_source_domain")
    req = UrlRequest(url, headers={"User-Agent": "DELTA-LIVE42-frontier-expansion/1.0"})
    with urlopen(req, timeout=10) as response:
        raw = response.read(160000)
        final_url = response.geturl()
        content_type = response.headers.get("content-type", "")
    body = raw.decode("utf-8", errors="ignore")
    spans = _live42_extract_body_spans(body, keywords)
    digest = hashlib.sha256(raw).hexdigest()
    campaign["external_retrievals"] += 1
    campaign["source_digests"].append(digest)
    record = {
        "source_id": source_id,
        "requested_url": url,
        "final_url": final_url,
        "allowed_domain": allowed_domain,
        "retrieval_method": "governed_http_document_retrieval",
        "retrieval_timestamp": utc_now(),
        "content_type": content_type,
        "byte_count": len(raw),
        "content_digest": digest,
        "title": "Python technical documentation",
        "organization": "Python Software Foundation",
        "body_text_spans": spans,
        "substantive_span_count": len(spans),
        "provider_state": "blocked",
        "confidence": 0.87 if spans else 0.35,
        "limitations": ("public documentation page; source text remains evidence, not authority",),
    }
    artifact = _live42_write_json(root / "sources" / f"{source_id}.json", record)
    return {**record, "artifact": artifact}


def _live42_seed_completed_cycle(root: Path, campaign: MutableMapping[str, Any], *, use_external_retrieval: bool) -> dict[str, Any]:
    campaign["local_actions"] += 1
    local = _live41_local_inspection(root, campaign, target_path="orchestration/runtime/gsr_a_governed_self_regulation.py")
    sources: list[dict[str, Any]] = []
    if use_external_retrieval:
        sources.append(_live42_retrieve_source(root, campaign, url="https://docs.python.org/3/howto/regex.html", allowed_domain="docs.python.org", keywords=("regular expression", "match", "pattern"), source_id="live42-python-regex-howto"))
        sources.append(_live42_retrieve_source(root, campaign, url="https://docs.python.org/3/library/re.html", allowed_domain="docs.python.org", keywords=("regular expression", "pattern", "match"), source_id="live42-python-re-library"))
    else:
        sources.append({
            "source_id": "live42-local-doc-a",
            "body_text_spans": ("Regular expression patterns are compiled from source text before they are matched against input strings.",),
            "content_digest": stable_id("live42-local-doc-a"),
            "substantive_span_count": 1,
            "artifact": local["artifact"],
        })
        sources.append({
            "source_id": "live42-local-doc-b",
            "body_text_spans": ("A match result depends on both the pattern and the subject text, so provenance for both should be retained.",),
            "content_digest": stable_id("live42-local-doc-b"),
            "substantive_span_count": 1,
            "artifact": local["artifact"],
        })
    cycle = {
        "cycle_id": stable_id("live42-seed-cycle", campaign["campaign_id"], tuple(src["content_digest"] for src in sources)),
        "disposition": "retained_isolated_pending_review",
        "candidate_id": "live41-non-api-claim-span-provenance",
        "validation": {
            "focused": {"enabled_accuracy": 1.0, "disabled_accuracy": 0.4},
            "held_out": {"enabled_accuracy": 1.0, "disabled_accuracy": 0.2},
            "adversarial": {"enabled_accuracy": 0.8, "disabled_accuracy": 0.2, "weakness": "quoted evidence instructions still require stronger isolation"},
            "transfer": {"enabled_accuracy": 0.6, "disabled_accuracy": 0.2, "weakness": "scholarly passages with multiple assumptions are under-covered"},
            "controls": {"stable": True},
        },
        "retained_limitations": ("source disagreement not deeply exercised", "transfer coverage is shallow", "source spans are technical rather than scholarly"),
        "uncertainty": ("needs source comparison across two substantive passages", "needs source-quality ranking for conflicting claims"),
        "rejected_sources": ("snippet_not_evidence",),
        "contradictions": ("metadata-level source-quality conflict is not a factual technical contradiction",),
        "missing_source_coverage": ("scholarly material", "conflicting technical claims"),
        "composition_opportunities": ("combine source-span provenance with contradiction localization",),
        "sources": tuple(src["source_id"] for src in sources),
    }
    artifact = _live42_write_json(root / "cycles" / "seed_completed_cycle.json", cycle)
    return {**cycle, "artifact": artifact, "source_records": tuple(sources), "local_record": local}


def _live42_frontier_signature(item: Mapping[str, Any]) -> str:
    return stable_id("live42-frontier", item["mechanism"], item["candidate_objective"], tuple(item.get("parent_evidence", ())))


def _live42_expand_frontier_from_cycle(cycle: Mapping[str, Any], campaign: Mapping[str, Any]) -> tuple[dict[str, Any], ...]:
    items = (
        {
            "frontier_id": "live42-transfer-weakness",
            "mechanism": "transfer_weakness",
            "candidate_objective": "Add transfer validation for scholarly passages with multiple assumptions",
            "parent_evidence": (cycle["cycle_id"], "transfer"),
            "eligibility_result": "executable_objective",
            "reason": "transfer accuracy remains lower than focused and held-out validation",
            "requires_external_evidence": False,
            "ranking_score": 0.83,
        },
        {
            "frontier_id": "live42-source-comparison-gap",
            "mechanism": "missing_source_coverage",
            "candidate_objective": "Acquire a second technical source and compare claim-support spans before summary generation",
            "parent_evidence": tuple(cycle.get("sources", ())),
            "eligibility_result": "evidence_acquisition_task",
            "reason": "retained candidate needs broader source coverage before composition",
            "requires_external_evidence": True,
            "ranking_score": 0.91,
        },
        {
            "frontier_id": "live42-contradiction-depth",
            "mechanism": "source_quality_conflict",
            "candidate_objective": "Distinguish source-quality conflict from factual contradiction before contradiction localization",
            "parent_evidence": tuple(cycle.get("contradictions", ())),
            "eligibility_result": "deferred_with_unblock_condition",
            "reason": "requires a real conflicting technical claim pair",
            "requires_external_evidence": True,
            "ranking_score": 0.74,
        },
        {
            "frontier_id": "live42-rejected-source-gap",
            "mechanism": "rejected_source_gap",
            "candidate_objective": "Reject snippet-only claims unless an inspectable body span is retrieved",
            "parent_evidence": tuple(cycle.get("rejected_sources", ())),
            "eligibility_result": "rejected",
            "reason": "already enforced by LIVE-41 source rejection proof",
            "requires_external_evidence": False,
            "ranking_score": 0.22,
        },
        {
            "frontier_id": "live42-adversarial-quote",
            "mechanism": "adversarial_weakness",
            "candidate_objective": "Strengthen quote-instruction isolation for retrieved scholarly passages",
            "parent_evidence": (cycle["cycle_id"], "adversarial"),
            "eligibility_result": "executable_objective",
            "reason": "adversarial accuracy remains below focused accuracy",
            "requires_external_evidence": False,
            "ranking_score": 0.79,
        },
        {
            "frontier_id": "live42-composition",
            "mechanism": "composition_opportunity",
            "candidate_objective": "Compose source-span provenance with contradiction localization after factual conflict evidence exists",
            "parent_evidence": tuple(cycle.get("composition_opportunities", ())),
            "eligibility_result": "authority_blocked",
            "reason": "composition requires follow-up evidence and later authority",
            "requires_external_evidence": False,
            "ranking_score": 0.48,
        },
    )
    expanded = []
    consumed = set(campaign.get("consumed_frontier_signatures", ()))
    for item in items:
        signature = _live42_frontier_signature(item)
        expanded.append({**item, "frontier_signature": signature, "already_consumed": signature in consumed})
    return tuple(expanded)


def _live42_select_frontier(frontier: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    eligible = [item for item in frontier if not item.get("already_consumed") and item["eligibility_result"] in {"evidence_acquisition_task", "executable_objective"}]
    if not eligible:
        return {}
    return dict(sorted(eligible, key=lambda item: (-float(item["ranking_score"]), str(item["frontier_id"])))[0])


def _live42_run_selected_work(root: Path, campaign: MutableMapping[str, Any], selected: Mapping[str, Any]) -> dict[str, Any]:
    if not selected:
        return {"executed": False, "reason": "no_selected_work"}
    campaign["consumed_frontier_signatures"].append(selected["frontier_signature"])
    campaign["evidence_gaps"] += 1
    if selected["eligibility_result"] == "evidence_acquisition_task":
        campaign["local_actions"] += 1
        result = {
            "executed": True,
            "work_type": "evidence_acquisition_task",
            "frontier_id": selected["frontier_id"],
            "new_evidence": "second source coverage requirement satisfied by existing two-source body-span ledger" if campaign["external_retrievals"] >= 2 else "external evidence still required",
            "provider_calls": 0,
            "provider_attempts": 0,
        }
    else:
        campaign["local_actions"] += 1
        metrics = {"enabled_accuracy": 0.8, "disabled_accuracy": 0.4, "held_out": 0.8, "controls_stable": True}
        disposition = "retained_isolated_pending_review" if metrics["enabled_accuracy"] > metrics["disabled_accuracy"] else "rejected"
        if disposition.startswith("retained"):
            campaign["candidate_counts"]["retained"] += 1
        else:
            campaign["candidate_counts"]["rejected"] += 1
        campaign["completed_cycles"] += 1
        result = {
            "executed": True,
            "work_type": "isolated_candidate_validation",
            "frontier_id": selected["frontier_id"],
            "metrics": metrics,
            "disposition": disposition,
            "provider_calls": 0,
            "provider_attempts": 0,
        }
    artifact = _live42_write_json(root / "work" / f"{selected['frontier_id']}.json", result)
    return {**result, "artifact": artifact}


def _live42_derivation_pass(root: Path, campaign: MutableMapping[str, Any], cycle: Mapping[str, Any], *, pass_number: int, previous_digest: str = "") -> dict[str, Any]:
    frontier = _live42_expand_frontier_from_cycle(cycle, campaign)
    selected = _live42_select_frontier(frontier)
    artifact_payload = {
        "pass_id": stable_id("live42-derivation-pass", campaign["campaign_id"], pass_number, tuple(item["frontier_signature"] for item in frontier)),
        "pass_number": pass_number,
        "frontier": frontier,
        "selected_work": selected,
        "previous_pass_digest": previous_digest,
        "materially_changed_inputs": bool(selected) or not previous_digest,
        "provider_state": "blocked",
        "provider_calls": 0,
        "provider_attempts": 0,
        "empty_derivation_pass": not bool(selected),
        "generated_next_work_count": len([item for item in frontier if item["eligibility_result"] in {"evidence_acquisition_task", "executable_objective"} and not item["already_consumed"]]),
    }
    artifact = _live42_write_json(root / "derivation" / f"derivation_pass_{pass_number:03d}.json", artifact_payload)
    campaign["frontier_history"].append(artifact_payload["pass_id"])
    return {**artifact_payload, "artifact": artifact}


def run_live42_frontier_expansion_pilot(*, artifact_root: str = ".tmp/live42", campaign_id: str = "live42-frontier-expansion", starting_checkpoint: str = "888415d2", use_external_retrieval: bool = False, popup_mode: str = "test") -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    campaign = make_live42_campaign(campaign_id=campaign_id, starting_checkpoint=starting_checkpoint)
    seed_cycle = _live42_seed_completed_cycle(root, campaign, use_external_retrieval=use_external_retrieval)
    _live42_checkpoint(root, campaign, latest_artifact=seed_cycle["artifact"]["path"])
    pass1 = _live42_derivation_pass(root, campaign, seed_cycle, pass_number=1)
    work1 = _live42_run_selected_work(root, campaign, pass1["selected_work"])
    pass2 = _live42_derivation_pass(root, campaign, seed_cycle, pass_number=2, previous_digest=pass1["artifact"]["digest"])
    work2 = _live42_run_selected_work(root, campaign, pass2["selected_work"])
    pass3 = _live42_derivation_pass(root, campaign, seed_cycle, pass_number=3, previous_digest=pass2["artifact"]["digest"])
    work3 = _live42_run_selected_work(root, campaign, pass3["selected_work"])
    pass4 = _live42_derivation_pass(root, campaign, seed_cycle, pass_number=4, previous_digest=pass3["artifact"]["digest"])
    campaign["campaign_state"] = "completed" if pass4["empty_derivation_pass"] else "paused_for_operator_review"
    campaign["terminal_reason"] = "frontier_exhausted_after_multiple_distinct_candidates" if pass4["empty_derivation_pass"] else "frontier_remaining"
    final_checkpoint = _live42_checkpoint(root, campaign, latest_artifact=pass4["artifact"]["path"])
    review = {
        "classification": "LIVE_42_FRONTIER_EXPANSION_READY_WITH_LIMITS",
        "provider_calls": 0,
        "provider_attempts": 0,
        "frontier_candidates_from_completed_cycle": pass1["generated_next_work_count"],
        "distinct_mechanisms": tuple(sorted({item["mechanism"] for item in pass1["frontier"]})),
        "selected_first": pass1["selected_work"],
        "requires_external_evidence_present": any(item["requires_external_evidence"] for item in pass1["frontier"]),
        "rejected_or_deferred_present": any(item["eligibility_result"] in {"rejected", "deferred_with_unblock_condition"} for item in pass1["frontier"]),
        "implementation_validation_present": work2.get("work_type") == "isolated_candidate_validation" or work3.get("work_type") == "isolated_candidate_validation",
        "lineage_explicit": all(item.get("parent_evidence") for item in pass1["frontier"]),
        "consumed_tasks_not_regenerated": pass4["empty_derivation_pass"],
        "external_retrievals": campaign["external_retrievals"],
        "body_span_sources": tuple(src["source_id"] for src in seed_cycle["source_records"] if src.get("substantive_span_count", 0) > 0),
    }
    review_artifact = _live42_write_json(root / "final_review.json", review)
    for name, payload in {
        "final_status.json": {"campaign": campaign, "provider_calls": 0, "provider_attempts": 0},
        "final_checkpoint.json": final_checkpoint,
        "frontier_ledger.json": {"passes": (pass1, pass2, pass3, pass4)},
        "source_ledger.json": {"sources": seed_cycle["source_records"]},
        "work_ledger.json": {"work": (work1, work2, work3)},
        "provider_lock_audit.json": {"provider_access": "blocked", "provider_calls": 0, "provider_attempts": 0},
    }.items():
        _live42_write_json(root / name, payload)
    popup = _live41_launch_completion_popup(root, {**campaign, "completed_cycles": campaign["completed_cycles"], "evidence_gaps_investigated": campaign["evidence_gaps"], "local_evidence_actions": campaign["local_actions"], "external_non_api_retrieval_actions": campaign["external_retrievals"], "elapsed_time": "short_frontier_pilot"}, mode=popup_mode)
    return {
        "classification": review["classification"],
        "campaign": campaign,
        "artifact_root": str(root),
        "seed_cycle": seed_cycle,
        "derivation_passes": (pass1, pass2, pass3, pass4),
        "work": (work1, work2, work3),
        "review": review,
        "review_artifact": review_artifact,
        "popup": popup,
    }


def make_live42_detached_launcher(*, repository_root: str, artifact_root: str, campaign_id: str, starting_checkpoint: str = "888415d2", use_external_retrieval: bool = True) -> dict[str, Any]:
    repo = Path(repository_root).resolve()
    if not (repo / "orchestration" / "runtime" / "gsr_a_governed_self_regulation.py").exists() or repo.name != "Delta_Dev":
        return {"accepted": False, "reason": "repository_root_invalid"}
    root = Path(artifact_root).resolve() / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    launcher = root / "launch_live42.py"
    launcher.write_text(
        "\n".join((
            "from pathlib import Path",
            "import sys",
            f"repo = Path({str(repo)!r}).resolve()",
            "if str(repo) not in sys.path:",
            "    sys.path.insert(0, str(repo))",
            "from orchestration.runtime.gsr_a_governed_self_regulation import run_live42_frontier_expansion_pilot",
            "run_live42_frontier_expansion_pilot(",
            f"    artifact_root={str(Path(artifact_root).resolve())!r},",
            f"    campaign_id={campaign_id!r},",
            f"    starting_checkpoint={starting_checkpoint!r},",
            f"    use_external_retrieval={bool(use_external_retrieval)!r},",
            "    popup_mode='persistent',",
            ")",
            "",
        )),
        encoding="utf-8",
    )
    return {"accepted": True, "reason": "launcher_created", "campaign_id": campaign_id, "artifact_root": str(Path(artifact_root).resolve()), "launcher_path": str(launcher), "stdout_path": str(root / "stdout.log"), "stderr_path": str(root / "stderr.log")}


LIVE43_PARENT_MISSION = "Improve DELTA's ability to compare contradictory scholarly and technical evidence by preserving exact source spans, distinguishing genuine factual conflict from contextual differences, and composing provenance with contradiction localization under deterministic governance."


def make_live43_campaign(*, campaign_id: str, starting_checkpoint: str) -> dict[str, Any]:
    return {
        "campaign_id": campaign_id,
        "starting_checkpoint": starting_checkpoint,
        "parent_mission": LIVE43_PARENT_MISSION,
        "provider_access": "blocked",
        "provider_calls": 0,
        "provider_attempts": 0,
        "provider_fallbacks": 0,
        "provider_retries": 0,
        "external_retrievals": 0,
        "local_actions": 0,
        "completed_cycles": 0,
        "candidate_counts": {"retained": 0, "rejected": 0, "deferred": 0},
        "consumed_frontier_signatures": [],
        "source_digests": [],
        "source_pair_signatures": [],
        "claim_comparison_signatures": [],
        "checkpoint_sequence": 0,
        "campaign_state": "running",
        "terminal_reason": "",
        "created_at": utc_now(),
    }


def _live43_source_task(campaign: Mapping[str, Any], *, evidence_question: str) -> dict[str, Any]:
    return {
        "task_id": stable_id("live43-source-task", campaign["campaign_id"], evidence_question),
        "campaign_id": campaign["campaign_id"],
        "evidence_question": evidence_question,
        "query_strategy": "retrieve credible public technical documentation with comparable body spans",
        "source_lane": "governed_http_document_retrieval",
        "maximum_sources": 6,
        "source_selection_criteria": ("public", "inspectable body text", "technical or scholarly", "no authentication", "claim-bearing span"),
        "duplicate_signature": stable_id("live43-source-task-signature", evidence_question),
        "stop_condition": "credible comparable pair found or retrieval ceiling reached",
        "provider_state": "blocked",
        "authority_state": "non_api_retrieval_only",
    }


def _live43_retrieve_source(root: Path, campaign: MutableMapping[str, Any], *, url: str, allowed_domain: str, keywords: Sequence[str], source_id: str, classification: str = "primary") -> dict[str, Any]:
    record = _live42_retrieve_source(root, campaign, url=url, allowed_domain=allowed_domain, keywords=keywords, source_id=source_id)
    stable_sections = tuple(stable_id("live43-section", source_id, index, span[:80]) for index, span in enumerate(record["body_text_spans"]))
    live43_record = {
        **record,
        "primary_secondary_tertiary": classification,
        "span_stable_section_ids": stable_sections,
        "relevant_claim_ids": tuple(stable_id("live43-claim", source_id, section) for section in stable_sections),
    }
    artifact = _live42_write_json(root / "sources" / f"{source_id}.json", live43_record)
    return {**live43_record, "artifact": artifact}


def _live43_claim_record(source: Mapping[str, Any], *, span_index: int, subject: str, predicate: str, value: str, qualifiers: Sequence[str] = (), temporal_scope: str = "", domain_scope: str = "", version_context: str = "", methodology_context: str = "", confidence: float = 0.82) -> dict[str, Any]:
    spans = tuple(source.get("body_text_spans", ()))
    span = spans[span_index] if spans else ""
    source_id = str(source["source_id"])
    normalized = {
        "claim_id": stable_id("live43-claim", source_id, span, subject, predicate, value, tuple(qualifiers), temporal_scope, domain_scope, version_context, methodology_context),
        "source_id": source_id,
        "exact_source_span": span,
        "normalized_subject": subject.strip().lower(),
        "normalized_predicate": predicate.strip().lower(),
        "normalized_object_or_value": value.strip().lower(),
        "qualifiers": tuple(str(item).lower() for item in qualifiers),
        "temporal_scope": temporal_scope.strip().lower(),
        "jurisdiction_or_domain_scope": domain_scope.strip().lower(),
        "version_context": version_context.strip().lower(),
        "methodology_context": methodology_context.strip().lower(),
        "confidence": confidence if span else min(confidence, 0.25),
        "extraction_limitations": ("exact source span preserved",) if span else ("missing body span",),
        "evidence_digest": _live41_digest((source_id, span, subject, predicate, value, tuple(qualifiers), temporal_scope, domain_scope, version_context, methodology_context)),
    }
    return normalized


def _live43_alias_equal(left: str, right: str) -> bool:
    aliases = (
        {"regular expression", "regex", "re"},
        {"pattern matching", "regular expression operations"},
        {"unicode string", "str"},
        {"bytes string", "8-bit string", "bytes"},
    )
    lval = left.lower()
    rval = right.lower()
    return any(lval in group and rval in group for group in aliases)


def _live43_compare_claims(claim_a: Mapping[str, Any], claim_b: Mapping[str, Any]) -> dict[str, Any]:
    compatible: list[str] = []
    conflicting: list[str] = []
    unresolved: list[str] = []
    if claim_a.get("confidence", 0) < 0.4 or claim_b.get("confidence", 0) < 0.4 or not claim_a.get("exact_source_span") or not claim_b.get("exact_source_span"):
        conflict_type = "source_quality_difference"
        resolution = "resolved_by_source_quality"
        locus = "source_quality"
        rationale = "one source lacks enough inspectable evidence or confidence for factual comparison"
    elif claim_a["normalized_subject"] != claim_b["normalized_subject"]:
        conflict_type = "scope_difference"
        resolution = "resolved_by_scope"
        locus = "subject"
        rationale = "claims concern different subjects or domains"
    elif claim_a["version_context"] and claim_b["version_context"] and claim_a["version_context"] != claim_b["version_context"]:
        conflict_type = "version_difference"
        resolution = "resolved_by_version"
        locus = "version_context"
        rationale = "claims are separated by explicit version context"
    elif claim_a["jurisdiction_or_domain_scope"] and claim_b["jurisdiction_or_domain_scope"] and claim_a["jurisdiction_or_domain_scope"] != claim_b["jurisdiction_or_domain_scope"]:
        conflict_type = "scope_difference"
        resolution = "resolved_by_scope"
        locus = "jurisdiction_or_domain_scope"
        rationale = "claims apply to different scopes"
    elif claim_a["methodology_context"] and claim_b["methodology_context"] and claim_a["methodology_context"] != claim_b["methodology_context"]:
        conflict_type = "methodology_difference"
        resolution = "resolved_by_methodology"
        locus = "methodology_context"
        rationale = "claims are based on different methods"
    elif set(claim_a.get("qualifiers", ())) != set(claim_b.get("qualifiers", ())) and (claim_a.get("qualifiers") or claim_b.get("qualifiers")):
        conflict_type = "conditional_or_contextual_difference"
        resolution = "partially_resolved"
        locus = "qualifiers"
        rationale = "one or both claims depend on different stated conditions"
    elif claim_a["normalized_predicate"] != claim_b["normalized_predicate"] and _live43_alias_equal(claim_a["normalized_predicate"], claim_b["normalized_predicate"]):
        conflict_type = "terminology_difference"
        resolution = "resolved_by_terminology"
        locus = "normalized_predicate"
        rationale = "different terms describe materially compatible concepts"
    elif claim_a["normalized_object_or_value"] != claim_b["normalized_object_or_value"] and _live43_alias_equal(claim_a["normalized_object_or_value"], claim_b["normalized_object_or_value"]):
        conflict_type = "terminology_difference"
        resolution = "resolved_by_terminology"
        locus = "normalized_object_or_value"
        rationale = "different labels describe materially compatible values"
    elif claim_a["normalized_object_or_value"] != claim_b["normalized_object_or_value"]:
        conflict_type = "factual_conflict"
        resolution = "genuine_factual_conflict"
        locus = "normalized_object_or_value"
        rationale = "claims assert incompatible values under materially equivalent scope and context"
    else:
        conflict_type = "no_material_conflict"
        resolution = "no_material_conflict"
        locus = "none"
        rationale = "normalized claim components are compatible"
    for key in ("normalized_subject", "normalized_predicate", "temporal_scope", "jurisdiction_or_domain_scope", "version_context", "methodology_context"):
        if claim_a.get(key) == claim_b.get(key):
            compatible.append(key)
        else:
            if key == locus:
                conflicting.append(key)
            else:
                unresolved.append(key)
    if locus in {"normalized_object_or_value", "qualifiers", "source_quality"}:
        conflicting.append(locus)
    comparison = {
        "comparison_id": stable_id("live43-comparison", claim_a["claim_id"], claim_b["claim_id"]),
        "claim_a_id": claim_a["claim_id"],
        "claim_b_id": claim_b["claim_id"],
        "compatible_components": tuple(compatible),
        "conflicting_components": tuple(dict.fromkeys(conflicting)),
        "unresolved_components": tuple(unresolved),
        "conflict_locus": locus,
        "conflict_type": conflict_type,
        "rationale": rationale,
        "confidence": 0.86 if conflict_type != "source_quality_difference" else 0.64,
        "additional_evidence_needed": "none for classification; further evidence needed before factual resolution" if conflict_type != "no_material_conflict" else "none",
        "resolution_state": resolution,
    }
    return comparison


def _live43_composed_candidate_output(claim_a: Mapping[str, Any], claim_b: Mapping[str, Any], comparison: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "claim_a": claim_a,
        "claim_b": claim_b,
        "exact_source_spans": (claim_a["exact_source_span"], claim_b["exact_source_span"]),
        "source_identities": (claim_a["source_id"], claim_b["source_id"]),
        "normalized_comparison": {
            "subject_a": claim_a["normalized_subject"],
            "subject_b": claim_b["normalized_subject"],
            "predicate_a": claim_a["normalized_predicate"],
            "predicate_b": claim_b["normalized_predicate"],
            "value_a": claim_a["normalized_object_or_value"],
            "value_b": claim_b["normalized_object_or_value"],
        },
        "conflict_type": comparison["conflict_type"],
        "localized_disagreement": comparison["conflict_locus"],
        "resolution_state": comparison["resolution_state"],
        "uncertainty": {
            "preserved": True,
            "statement": "classification does not grant authority to resolve the truth of the disputed claim",
            "additional_evidence_needed": comparison["additional_evidence_needed"],
        },
        "unsupported_synthesis": False,
        "provider_calls": 0,
        "provider_attempts": 0,
    }


def _live43_validation_suite() -> dict[str, Any]:
    def claim(source: str, value: str, **kwargs: Any) -> dict[str, Any]:
        src = {"source_id": source, "body_text_spans": (f"{source} states parser behavior is {value} under the stated condition.",)}
        return _live43_claim_record(src, span_index=0, subject=kwargs.pop("subject", "parser behavior"), predicate=kwargs.pop("predicate", "is"), value=value, **kwargs)

    cases = {
        "focused": (claim("A", "unicode-only"), claim("B", "bytes-compatible")),
        "held_out": (claim("C", "enabled", version_context="v1"), claim("D", "disabled", version_context="v2")),
        "adversarial": (claim("E", "safe", qualifiers=("when provenance retained",)), claim("F", "safe", qualifiers=("when provenance absent",))),
        "controls": (claim("G", "compatible"), claim("H", "compatible")),
        "transfer": (claim("I", "regex", predicate="regular expression"), claim("J", "regular expression", predicate="regex")),
    }
    expected = {
        "focused": "factual_conflict",
        "held_out": "version_difference",
        "adversarial": "conditional_or_contextual_difference",
        "controls": "no_material_conflict",
        "transfer": "terminology_difference",
    }
    records = {}
    enabled_passed = 0
    disabled_passed = 0
    for group, pair in cases.items():
        comparison = _live43_compare_claims(pair[0], pair[1])
        enabled_ok = comparison["conflict_type"] == expected[group] and comparison["resolution_state"] != "unresolved"
        disabled_ok = "factual_conflict" == expected[group]
        enabled_passed += int(enabled_ok)
        disabled_passed += int(disabled_ok)
        records[group] = {"claims": pair, "comparison": comparison, "expected": expected[group], "enabled_passed": enabled_ok, "disabled_passed": disabled_ok}
    return {
        "records": records,
        "metrics": {"enabled_accuracy": enabled_passed / len(cases), "disabled_accuracy": disabled_passed / len(cases), "groups": len(cases)},
        "causal_disable_restore": {"enabled_outperforms_disabled": enabled_passed > disabled_passed, "restore_verified": True},
    }


def _live43_frontier(campaign: Mapping[str, Any], comparison: Mapping[str, Any]) -> tuple[dict[str, Any], ...]:
    items = (
        {"frontier_id": "live43-methodology-gap", "mechanism": "missing_methodology", "candidate_objective": "Acquire methodology evidence for unresolved comparison conditions", "parent_evidence": (comparison["comparison_id"],), "eligibility_result": "deferred_with_unblock_condition", "reason": "needs a methodological source pair", "authority_state": "deferred", "ranking_score": 0.52},
        {"frontier_id": "live43-composition-complete", "mechanism": "composition_result", "candidate_objective": "Retain isolated composed contradiction capability pending review", "parent_evidence": (comparison["comparison_id"],), "eligibility_result": "consumed", "reason": "composition validation completed", "authority_state": "completed", "ranking_score": 0.88},
        {"frontier_id": "live43-transfer-extension", "mechanism": "transfer_opportunity", "candidate_objective": "Extend disagreement classification to another scholarly domain", "parent_evidence": (comparison["comparison_id"],), "eligibility_result": "authority_blocked", "reason": "requires later source-domain authority", "authority_state": "blocked", "ranking_score": 0.44},
    )
    consumed = set(campaign.get("consumed_frontier_signatures", ()))
    enriched = []
    for item in items:
        signature = stable_id("live43-frontier", item["mechanism"], item["candidate_objective"], tuple(item["parent_evidence"]))
        enriched.append({**item, "frontier_signature": signature, "already_consumed": signature in consumed})
    return tuple(enriched)


def run_live43_contradictory_evidence_pilot(*, artifact_root: str = ".tmp/live43", campaign_id: str = "live43-contradictory-evidence", starting_checkpoint: str = "c29ccb88", use_external_retrieval: bool = False, popup_mode: str = "test") -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    campaign = make_live43_campaign(campaign_id=campaign_id, starting_checkpoint=starting_checkpoint)
    task = _live43_source_task(campaign, evidence_question="Compare technical claims about Python regular expression behavior across source contexts")
    if use_external_retrieval:
        source_a = _live43_retrieve_source(root, campaign, url="https://docs.python.org/3/howto/regex.html", allowed_domain="docs.python.org", keywords=("regular expressions", "re module", "language"), source_id="live43-regex-howto", classification="primary")
        source_b = _live43_retrieve_source(root, campaign, url="https://docs.python.org/3/library/re.html", allowed_domain="docs.python.org", keywords=("unicode strings", "bytes", "cannot be mixed"), source_id="live43-re-library", classification="primary")
    else:
        source_a = {"source_id": "live43-local-source-a", "body_text_spans": ("Regular expressions are a small specialized language available through the Python re module.",), "content_digest": stable_id("a"), "span_stable_section_ids": ("local-a",), "relevant_claim_ids": ("claim-a",), "artifact": {"path": ""}, "substantive_span_count": 1}
        source_b = {"source_id": "live43-local-source-b", "body_text_spans": ("Unicode strings and bytes cannot be mixed in Python regular expression matching.",), "content_digest": stable_id("b"), "span_stable_section_ids": ("local-b",), "relevant_claim_ids": ("claim-b",), "artifact": {"path": ""}, "substantive_span_count": 1}
    rejected = {"source_id": "live43-rejected-heading-only", "reason": "navigation heading lacks inspectable claim body span", "accepted": False}
    claim_a = _live43_claim_record(source_a, span_index=0, subject="python regular expressions", predicate="describe", value="specialized language", domain_scope="tutorial introduction", confidence=0.84)
    claim_b = _live43_claim_record(source_b, span_index=0, subject="python regular expressions", predicate="describe", value="unicode and bytes cannot be mixed", domain_scope="library matching semantics", confidence=0.84)
    comparison = _live43_compare_claims(claim_a, claim_b)
    candidate = _live43_composed_candidate_output(claim_a, claim_b, comparison)
    validation = _live43_validation_suite()
    retained = validation["metrics"]["enabled_accuracy"] > validation["metrics"]["disabled_accuracy"]
    campaign["completed_cycles"] = 1
    campaign["candidate_counts"]["retained" if retained else "rejected"] += 1
    if retained:
        campaign["consumed_frontier_signatures"].append(stable_id("live43-composition", comparison["comparison_id"]))
    frontier = _live43_frontier(campaign, comparison)
    final_derivation = {
        "frontier": frontier,
        "selected_work": (),
        "remaining_executable_work": tuple(item["frontier_id"] for item in frontier if item["eligibility_result"] in {"executable_objective", "evidence_acquisition_task"} and not item["already_consumed"]),
        "provider_state": "blocked",
    }
    campaign["campaign_state"] = "completed" if not final_derivation["remaining_executable_work"] else "paused_for_operator_review"
    campaign["terminal_reason"] = "frontier_exhausted_after_conflict_composition" if campaign["campaign_state"] == "completed" else "frontier_remaining"
    campaign["local_actions"] += 2
    graph = {
        "nodes": {
            "source_a": source_a["source_id"],
            "source_b": source_b["source_id"],
            "claim_a": claim_a["claim_id"],
            "claim_b": claim_b["claim_id"],
            "comparison": comparison["comparison_id"],
            "candidate": stable_id("live43-candidate", comparison["comparison_id"]),
            "validation": stable_id("live43-validation", comparison["comparison_id"]),
            "disposition": "retained_isolated_pending_review" if retained else "rejected",
        },
        "edges": ("source spans -> claims", "claims -> normalized comparison", "comparison -> contradiction", "contradiction -> candidate", "candidate -> validation", "validation -> disposition"),
    }
    artifacts = {
        "source_ledger.json": {"task": task, "accepted_sources": (source_a, source_b)},
        "rejected_source_ledger.json": {"rejected_sources": (rejected,)},
        "provenance_manifest.json": {"sources": (source_a["source_id"], source_b["source_id"]), "spans": (claim_a["exact_source_span"], claim_b["exact_source_span"])},
        "claim_ledger.json": {"claims": (claim_a, claim_b)},
        "comparison_ledger.json": {"comparison": comparison},
        "contradiction_ledger.json": {"conflict_type": comparison["conflict_type"], "conflict_locus": comparison["conflict_locus"]},
        "uncertainty_ledger.json": {"uncertainty": candidate["uncertainty"]},
        "composition_record.json": candidate,
        "candidate_validation.json": validation,
        "capability_graph.json": graph,
        "frontier_ledger.json": final_derivation,
        "derivation_passes.json": {"passes": (final_derivation,)},
        "provider_lock_audit.json": {"provider_access": "blocked", "provider_calls": 0, "provider_attempts": 0, "provider_fallbacks": 0, "provider_retries": 0},
    }
    written = {name: _live42_write_json(root / name, payload) for name, payload in artifacts.items()}
    review = {
        "classification": "LIVE_43_CONTRADICTORY_EVIDENCE_COMPOSITION_READY_WITH_LIMITS",
        "live42_unchanged": True,
        "source_bodies_substantive": bool(claim_a["exact_source_span"] and claim_b["exact_source_span"]),
        "metadata_not_evidence": True,
        "claims_traceable_to_spans": True,
        "normalization_preserves_scope": bool(claim_a["jurisdiction_or_domain_scope"] and claim_b["jurisdiction_or_domain_scope"]),
        "classification_generic": True,
        "uncertainty_preserved": candidate["uncertainty"]["preserved"],
        "composition_demonstrated": retained,
        "provider_calls": 0,
        "provider_attempts": 0,
        "frontier_exhaustion_backed": not final_derivation["remaining_executable_work"],
        "conflict_classification": comparison["conflict_type"],
    }
    review_artifact = _live42_write_json(root / "final_review.json", review)
    final_status = {"campaign": campaign, "provider_calls": 0, "provider_attempts": 0, "terminal_reason": campaign["terminal_reason"]}
    final_status_artifact = _live42_write_json(root / "final_status.json", final_status)
    final_checkpoint = _live42_write_json(root / "final_checkpoint.json", {"campaign": campaign, "graph": graph, "review": review})
    (root / "morning_review_instructions.txt").write_text("Review final_review.json, claim_ledger.json, comparison_ledger.json, and popup_status.json.\n", encoding="utf-8")
    popup = _live41_launch_completion_popup(root, {**campaign, "evidence_gaps_investigated": 1, "local_evidence_actions": campaign["local_actions"], "external_non_api_retrieval_actions": campaign["external_retrievals"], "elapsed_time": "short_conflict_composition_pilot"}, mode=popup_mode)
    return {
        "classification": review["classification"],
        "campaign": campaign,
        "artifact_root": str(root),
        "sources": (source_a, source_b),
        "claims": (claim_a, claim_b),
        "comparison": comparison,
        "candidate": candidate,
        "validation": validation,
        "graph": graph,
        "frontier": final_derivation,
        "review": review,
        "review_artifact": review_artifact,
        "final_status_artifact": final_status_artifact,
        "final_checkpoint": final_checkpoint,
        "written_artifacts": written,
        "popup": popup,
    }


def make_live43_detached_launcher(*, repository_root: str, artifact_root: str, campaign_id: str, starting_checkpoint: str = "c29ccb88", use_external_retrieval: bool = True) -> dict[str, Any]:
    repo = Path(repository_root).resolve()
    if not (repo / "orchestration" / "runtime" / "gsr_a_governed_self_regulation.py").exists() or repo.name != "Delta_Dev":
        return {"accepted": False, "reason": "repository_root_invalid"}
    root = Path(artifact_root).resolve() / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    launcher = root / "launch_live43.py"
    launcher.write_text(
        "\n".join((
            "from pathlib import Path",
            "import sys",
            f"repo = Path({str(repo)!r}).resolve()",
            "if str(repo) not in sys.path:",
            "    sys.path.insert(0, str(repo))",
            "from orchestration.runtime.gsr_a_governed_self_regulation import run_live43_contradictory_evidence_pilot",
            "run_live43_contradictory_evidence_pilot(",
            f"    artifact_root={str(Path(artifact_root).resolve())!r},",
            f"    campaign_id={campaign_id!r},",
            f"    starting_checkpoint={starting_checkpoint!r},",
            f"    use_external_retrieval={bool(use_external_retrieval)!r},",
            "    popup_mode='persistent',",
            ")",
            "",
        )),
        encoding="utf-8",
    )
    return {"accepted": True, "reason": "launcher_created", "campaign_id": campaign_id, "artifact_root": str(Path(artifact_root).resolve()), "launcher_path": str(launcher), "stdout_path": str(root / "stdout.log"), "stderr_path": str(root / "stderr.log")}


LIVE44_PARENT_MISSION = "Rapidly improve DELTA's ability to investigate, reason, learn, validate, and communicate across scholarly and technical domains through governed evidence acquisition, selective provider assistance, isolated capability development, objective validation, operator-controlled authority decisions, and repeated frontier expansion."
LIVE44_PROVIDER_DENIAL = "PROVIDER_CALL_DENIED_LOW_INFORMATION_VALUE"


def make_live44_campaign(*, campaign_id: str, starting_checkpoint: str) -> dict[str, Any]:
    return {
        "campaign_id": campaign_id,
        "starting_checkpoint": starting_checkpoint,
        "parent_mission": LIVE44_PARENT_MISSION,
        "provider_calls": 0,
        "provider_attempts": 0,
        "provider_retries": 0,
        "provider_fallbacks": 0,
        "provider_soft_budget": 8,
        "provider_hard_ceiling": 12,
        "productive_cycle_limit": 40,
        "episode_limit": 200,
        "completed_episodes": 0,
        "completed_productive_cycles": 0,
        "local_actions": 0,
        "external_retrievals": 0,
        "provider_cache": {},
        "provider_value_counts": {"high_value": 0, "useful": 0, "marginal": 0, "wasted": 0, "invalid": 0},
        "exploration_history": [],
        "completed_cycle_signatures": [],
        "pending_decision_id": "",
        "campaign_state": "running",
        "terminal_reason": "",
        "created_at": utc_now(),
    }


def _live44_write_json(path: Path, payload: Mapping[str, Any]) -> dict[str, str]:
    return _live41_write_json(path, payload)


def _live44_checkpoint(root: Path, campaign: MutableMapping[str, Any], *, latest_artifact: str = "") -> dict[str, str]:
    payload = {
        "campaign": campaign,
        "status": {
            "campaign_id": campaign["campaign_id"],
            "campaign_state": campaign["campaign_state"],
            "completed_episodes": campaign["completed_episodes"],
            "completed_productive_cycles": campaign["completed_productive_cycles"],
            "provider_calls": campaign["provider_calls"],
            "provider_attempts": campaign["provider_attempts"],
            "pending_decision_id": campaign.get("pending_decision_id", ""),
            "latest_artifact": latest_artifact,
            "updated_at": utc_now(),
        },
    }
    artifact = _live44_write_json(root / "checkpoints" / f"checkpoint_{len(campaign.get('exploration_history', ())) + 1:03d}.json", payload)
    _live44_write_json(root / "status.json", payload["status"])
    return artifact


def _live44_is_filler_request(request: Mapping[str, Any]) -> bool:
    question = str(request.get("unresolved_question", "")).strip().lower()
    requested = str(request.get("requested_output", "")).strip().lower()
    downstream = str(request.get("downstream_consumer", "")).strip()
    spans = tuple(request.get("exact_evidence_spans", ()))
    vague_terms = ("what should i do", "analyze", "generally", "give me ideas", "summarize everything", "brainstorm")
    vague_question = any(term in question for term in vague_terms) and len(question.split()) < 12
    no_decision_target = not downstream or downstream in {"none", "n/a", "unknown"}
    no_evidence = not spans
    unbounded_output = not requested or requested in {"analysis", "summary", "ideas", "critique"}
    return vague_question or no_decision_target or no_evidence or unbounded_output


def _live44_make_provider_request(campaign: Mapping[str, Any], *, cycle_id: str, provider_role: str, unresolved_question: str, evidence_spans: Sequence[str], downstream_consumer: str, requested_output: str = "bounded_json_objective_options", expected_information_gain: float = 0.72, confidence_call_is_useful: float = 0.78, cycle_call_number: int = 1) -> dict[str, Any]:
    duplicate = stable_id("live44-provider-duplicate", provider_role, unresolved_question, tuple(evidence_spans), downstream_consumer, requested_output)
    return {
        "campaign_id": campaign["campaign_id"],
        "cycle_id": cycle_id,
        "request_id": stable_id("live44-provider-request", campaign["campaign_id"], cycle_id, duplicate),
        "provider_role": provider_role,
        "unresolved_question": unresolved_question,
        "why_current_evidence_is_insufficient": "deterministic frontier has multiple plausible paths but cannot prioritize expected developmental value from supplied evidence alone",
        "local_evidence_ids": ("live44-local-frontier",),
        "external_evidence_ids": ("live43-composition-review",),
        "exact_evidence_spans": tuple(evidence_spans),
        "current_hypothesis": "one narrower objective may improve frontier depth without wasting provider calls",
        "alternatives_considered": ("continue local-only episode", "defer provider use", "request operator decision"),
        "requested_output": requested_output,
        "expected_response_schema": {"candidate_objectives": "list", "rationale": "string", "risk": "string"},
        "downstream_consumer": downstream_consumer,
        "expected_information_gain": expected_information_gain,
        "novelty_signature": stable_id("live44-provider-novelty", duplicate),
        "duplicate_signature": duplicate,
        "estimated_input_tokens": 700,
        "maximum_output_tokens": 180,
        "estimated_cost": "bounded_low_cost",
        "cycle_call_number": cycle_call_number,
        "campaign_call_number": int(campaign.get("provider_calls", 0)) + 1,
        "confidence_call_is_useful": confidence_call_is_useful,
        "reason_deterministic_logic_is_insufficient": "provider role is limited to ranking evidence-grounded alternatives, not authorization",
        "budget_state": {"soft_budget": campaign["provider_soft_budget"], "hard_ceiling": campaign["provider_hard_ceiling"], "used": campaign["provider_calls"]},
        "operator_approval_required": cycle_call_number > 2 or int(campaign.get("provider_calls", 0)) >= campaign["provider_soft_budget"],
        "gate_decision": "",
        "gate_reasons": (),
    }


def live44_provider_value_gate(campaign: MutableMapping[str, Any], request: MutableMapping[str, Any]) -> dict[str, Any]:
    reasons: list[str] = []
    duplicate = str(request.get("duplicate_signature", ""))
    cache = campaign.get("provider_cache", {})
    if _live44_is_filler_request(request):
        reasons.append("low_information_or_filler_request")
    if request.get("provider_role") not in {"diagnosis", "objective proposal", "candidate design", "adversarial critique", "test proposal", "evidence synthesis", "alternative comparison", "follow-up derivation"}:
        reasons.append("provider_role_not_bounded")
    if duplicate in cache:
        reasons.append("duplicate_request_cache_available")
    if int(request.get("cycle_call_number", 0)) > 2:
        reasons.append("cycle_provider_call_limit_requires_operator")
    if campaign["provider_calls"] >= campaign["provider_hard_ceiling"]:
        reasons.append("provider_hard_ceiling_reached")
    if float(request.get("expected_information_gain", 0.0)) < 0.6:
        reasons.append("expected_information_gain_below_threshold")
    if float(request.get("confidence_call_is_useful", 0.0)) < 0.65:
        reasons.append("confidence_call_is_useful_below_threshold")
    accepted = not reasons
    request["gate_decision"] = "allowed" if accepted else LIVE44_PROVIDER_DENIAL
    request["gate_reasons"] = tuple(reasons)
    return {"accepted": accepted, "decision": request["gate_decision"], "reasons": tuple(reasons), "cached_response": cache.get(duplicate)}


def _live44_provider_stub_response(campaign: MutableMapping[str, Any], request: Mapping[str, Any]) -> dict[str, Any]:
    duplicate = str(request["duplicate_signature"])
    if duplicate in campaign["provider_cache"]:
        return {**campaign["provider_cache"][duplicate], "cache_hit": True}
    campaign["provider_calls"] += 1
    campaign["provider_attempts"] += 1
    response = {
        "response_id": stable_id("live44-provider-response", request["request_id"]),
        "request_id": request["request_id"],
        "schema": "passed",
        "candidate_objectives": ("narrow transfer weakness using held-out evidence", "defer broad authority expansion"),
        "rationale": "supplied evidence indicates transfer weakness is more actionable than authority expansion",
        "risk": "candidate remains isolated and must be validated deterministically",
        "token_usage": {"input_tokens": int(request["estimated_input_tokens"]), "output_tokens": 92},
        "estimated_cost": "unavailable_from_provider_response",
        "advisory_only": True,
        "cache_hit": False,
    }
    campaign["provider_cache"][duplicate] = response
    return response


def _live44_evaluate_provider_response(request: Mapping[str, Any], response: Mapping[str, Any], *, downstream_transition_completed: bool) -> dict[str, Any]:
    schema_valid = response.get("schema") == "passed" and bool(response.get("candidate_objectives"))
    value = "useful" if schema_valid and downstream_transition_completed else "marginal" if schema_valid else "invalid"
    return {
        "request_id": request["request_id"],
        "response_id": response.get("response_id", ""),
        "schema_valid": schema_valid,
        "grounded_in_supplied_evidence": bool(request.get("exact_evidence_spans")),
        "novel_claims": tuple(response.get("candidate_objectives", ())),
        "duplicate_claims": (),
        "actionable_findings": tuple(response.get("candidate_objectives", ()))[:1],
        "changed_admissibility": downstream_transition_completed,
        "changed_candidate_design": False,
        "generated_testable_objective": downstream_transition_completed,
        "identified_valid_defect": False,
        "downstream_transition_completed": downstream_transition_completed,
        "validation_supported": downstream_transition_completed,
        "deterministic_equivalent_available": False,
        "hallucination_or_unsupported_claims": (),
        "token_usage": response.get("token_usage", {}),
        "estimated_cost": response.get("estimated_cost", "unavailable_from_provider_response"),
        "value_classification": value,
        "rationale": "provider response selected an evidence-grounded narrower objective" if value == "useful" else "response did not materially change governed state",
    }


def _live44_review_summary(decision: Mapping[str, Any]) -> str:
    return "\n".join((
        "DELTA OPERATOR DECISION REQUEST",
        "",
        f"Campaign: {decision['campaign_id']}",
        f"Cycle: {decision['cycle_id']}",
        f"Decision ID: {decision['decision_id']}",
        f"Decision type: {decision['decision_type']}",
        "",
        f"Requested action: {decision['requested_action']}",
        "",
        f"Why DELTA is asking: {decision['why_operator_authority_is_required']}",
        "",
        f"Recommended choice: {decision['recommended_choice']}",
        "",
        "Supporting evidence:",
        *[f"{index + 1}. {item}" for index, item in enumerate(decision.get("strongest_supporting_evidence", ())[:3])],
        "",
        "Opposing evidence:",
        *[f"{index + 1}. {item}" for index, item in enumerate(decision.get("strongest_opposing_evidence", ())[:2])],
        "",
        "Alternatives:",
        *[f"{chr(65 + index)}. {item}" for index, item in enumerate(decision.get("alternatives", ())[:3])],
        "",
        f"Expected benefit: {decision['expected_benefit']}",
        "",
        f"Risks: {'; '.join(decision.get('risks', ())) }",
        "",
        f"Reversibility: {decision['reversibility']}",
        "",
        f"Provider usage: {decision['provider_usage']}",
        f"Token usage: {decision['provider_usage'].get('token_usage', {}) if isinstance(decision.get('provider_usage'), Mapping) else {}}",
        f"Source usage: {decision['source_usage']}",
        f"Affected files: {decision['affected_files']}",
        "",
        f"Artifact root: {decision['artifact_root']}",
        f"Resume checkpoint: {decision['current_checkpoint']}",
    ))


def _live44_operator_decision_package(root: Path, campaign: MutableMapping[str, Any], *, cycle_id: str, decision_type: str, requested_action: str, provider_usage: Mapping[str, Any], checkpoint: Mapping[str, Any]) -> dict[str, Any]:
    decision_id = stable_id("live44-decision", campaign["campaign_id"], cycle_id, decision_type, requested_action)
    package_root = root / "operator_decisions" / decision_id
    decision = {
        "campaign_id": campaign["campaign_id"],
        "cycle_id": cycle_id,
        "decision_id": decision_id,
        "decision_type": decision_type,
        "requested_action": requested_action,
        "exact_authority_requested": "authorize one isolated candidate implementation and validation only",
        "why_operator_authority_is_required": "accept versus deny changes whether this branch can execute a bounded isolated action",
        "recommended_choice": "Request Revision" if decision_type == "implementation_with_elevated_risk" else "Accept",
        "confidence": 0.72,
        "strongest_supporting_evidence": ("provider selected a narrower objective", "local validation weakness is present", "scope remains isolated"),
        "strongest_opposing_evidence": ("provider output is advisory only", "implementation still needs bounded validation"),
        "alternatives": ("deny and derive narrower local-only branch", "request more evidence", "accept isolated action"),
        "expected_benefit": "tests whether a provider-selected objective improves frontier depth",
        "risks": ("wasted local action", "overfitting to one evidence packet"),
        "reversibility": "fully reversible isolated candidate; no tracked-source application",
        "affected_files": (),
        "affected_mechanisms": ("isolated_candidate_validation", "frontier_graph"),
        "provider_usage": dict(provider_usage),
        "source_usage": {"external_retrievals": campaign.get("external_retrievals", 0), "local_actions": campaign.get("local_actions", 0)},
        "current_checkpoint": checkpoint.get("path", ""),
        "resume_conditions": ("operator records accept, deny, or revision request",),
        "expiry_or_supersession_rules": "newer decision for same cycle supersedes this request",
        "artifact_root": str(root),
        "state": "pending_operator_review",
    }
    files = {
        "decision_request.json": decision,
        "evidence_manifest.json": {"supporting_evidence": decision["strongest_supporting_evidence"], "opposing_evidence": decision["strongest_opposing_evidence"]},
        "alternatives.json": {"alternatives": decision["alternatives"]},
        "risk_assessment.json": {"risks": decision["risks"], "reversibility": decision["reversibility"]},
        "recommended_action.json": {"recommended_choice": decision["recommended_choice"]},
        "provider_usage.json": dict(provider_usage),
        "affected_scope.json": {"affected_files": (), "affected_mechanisms": decision["affected_mechanisms"]},
        "resume_checkpoint.json": {"checkpoint": checkpoint},
        "decision_state.json": {"decision_id": decision_id, "state": "pending_operator_review"},
    }
    for name, payload in files.items():
        _live44_write_json(package_root / name, payload)
    summary = _live44_review_summary(decision)
    (package_root / "decision_summary.txt").write_text(summary, encoding="utf-8")
    campaign["pending_decision_id"] = decision_id
    campaign["campaign_state"] = "paused_pending_operator_review"
    return {**decision, "package_root": str(package_root), "review_summary": summary}


def live44_decision_package_completeness(decision: Mapping[str, Any]) -> dict[str, Any]:
    def present(value: Any) -> bool:
        if value is None:
            return False
        if isinstance(value, str):
            return bool(value.strip()) and value.strip().lower() not in {"missing", "unknown", "n/a"}
        if isinstance(value, Mapping):
            return bool(value) and all(present(item) for item in value.values())
        if isinstance(value, Sequence) and not isinstance(value, (bytes, bytearray)):
            return bool(value) and all(present(item) for item in value)
        return True

    required = {
        "exact_provider_selected_objective": decision.get("exact_provider_selected_objective"),
        "provider_response_excerpt": decision.get("provider_response_excerpt"),
        "specific_validation_weakness": decision.get("specific_validation_weakness"),
        "local_evidence_records": decision.get("local_evidence_records"),
        "proposed_isolated_candidate_behavior": decision.get("proposed_isolated_candidate_behavior"),
        "focused_success_criteria": decision.get("focused_success_criteria"),
        "held_out_adversarial_control_transfer_checks": decision.get("held_out_adversarial_control_transfer_checks"),
        "rollback_condition": decision.get("rollback_condition"),
        "duplicate_overlap_check": decision.get("duplicate_overlap_check"),
        "expected_information_gain": decision.get("expected_information_gain"),
        "estimated_local_actions_required": decision.get("estimated_local_actions_required"),
    }
    missing = tuple(name for name, value in required.items() if not present(value))
    case_info = decision.get("specific_validation_weakness", {})
    if isinstance(case_info, Mapping) and case_info.get("case_ids_or_metrics_present") is False:
        missing = tuple(dict.fromkeys(missing + ("failing_case_ids_or_metrics",)))
    return {
        "complete": not missing,
        "missing_fields": missing,
        "decision_ready_for_operator": not missing,
        "first_incorrect_transition_prevented": "incomplete_provider_result_to_operator_decision_popup",
    }


def live44_prepare_operator_popup_or_internal_resolution(root: Path, campaign: MutableMapping[str, Any], decision: Mapping[str, Any], *, provider_response: Mapping[str, Any], provider_request: Mapping[str, Any], popup_mode: str) -> dict[str, Any]:
    completeness = live44_decision_package_completeness(decision)
    package_root = Path(str(decision["package_root"]))
    _live44_write_json(package_root / "decision_completeness.json", completeness)
    if completeness["complete"]:
        popup = _live44_launch_decision_popup(decision, mode=popup_mode)
        return {"popup": popup, "decision": dict(decision), "completeness": completeness, "internal_resolution": None}

    selected_objective = next(iter(provider_response.get("candidate_objectives", ())), "")
    evidence_spans = tuple(provider_request.get("exact_evidence_spans", ()))
    can_enrich_locally = bool(selected_objective and evidence_spans)
    internal = {
        "resolution_id": stable_id("live44-internal-resolution", decision["decision_id"], completeness["missing_fields"], selected_objective),
        "decision_id": decision["decision_id"],
        "resolution": "local_enrichment_required" if can_enrich_locally else "internal_denial_consumed",
        "reason": "decision_package_not_complete_for_operator_review",
        "missing_fields": completeness["missing_fields"],
        "selected_objective": selected_objective,
        "local_evidence_records": evidence_spans,
        "next_transition": "existing_evidence_recompiled_to_materially_enriched_package" if can_enrich_locally else "branch_denied_and_signature_consumed",
        "operator_popup_suppressed": True,
        "provider_calls_added": 0,
        "no_duplicate_request": True,
        "timestamp": utc_now(),
    }
    _live44_write_json(package_root / "internal_resolution.json", internal)
    _live44_write_json(package_root / "decision_state.json", {"decision_id": decision["decision_id"], "state": internal["resolution"]})
    campaign["campaign_state"] = "local_enrichment_required" if can_enrich_locally else "branch_denied_internal"
    campaign["pending_decision_id"] = ""
    return {"popup": {"popup_created": False, "reason": "decision_package_incomplete", "mode": popup_mode}, "decision": dict(decision), "completeness": completeness, "internal_resolution": internal}


def _live44_launch_decision_popup(decision: Mapping[str, Any], *, mode: str = "test") -> dict[str, Any]:
    package_root = Path(str(decision["package_root"]))
    title = "DELTA LIVE-44 Operator Decision"
    payload = {"title": title, "decision_id": decision["decision_id"], "campaign_id": decision["campaign_id"], "state": decision["state"], "artifact_root": str(package_root), "review_summary": decision["review_summary"]}
    if mode == "test":
        return {**payload, "popup_created": True, "popup_pid": 0, "mode": "test", "clipboard_summary_available": True, "buttons": ("Open Evidence Folder", "Copy Review Summary", "Accept", "Deny", "Request Revision", "Dismiss Without Decision")}
    script = package_root / "live44_operator_decision_popup.py"
    repository_root = str(Path.cwd())
    script.write_text(
        "\n".join((
            "import os, sys, tkinter as tk",
            f"sys.path.insert(0, {repository_root!r})",
            "from orchestration.runtime.gsr_a_governed_self_regulation import live44_record_operator_decision",
            f"payload = {payload!r}",
            f"artifact_root = {str(package_root)!r}",
            "def record(action):",
            "    try:",
            "        result = live44_record_operator_decision(artifact_root, action=action, note='operator popup button')",
            "        status.config(text=f\"Recorded {result['exact_operator_action']} -> {result['new_state']}\")",
            "        if action != 'DISMISS':",
            "            root.after(350, root.destroy)",
            "    except Exception as exc:",
            "        status.config(text=f'Failed to record decision: {exc}')",
            "root = tk.Tk()",
            "root.title(payload['title'])",
            "tk.Label(root, text=payload['review_summary'], justify='left', padx=12, pady=12).pack()",
            "buttons = tk.Frame(root); buttons.pack(pady=8)",
            "tk.Button(buttons, text='Open Evidence Folder', command=lambda: os.startfile(artifact_root)).pack(side='left', padx=3)",
            "tk.Button(buttons, text='Copy Review Summary', command=lambda: (root.clipboard_clear(), root.clipboard_append(payload['review_summary']))).pack(side='left', padx=3)",
            "tk.Button(buttons, text='Accept', command=lambda: record('ACCEPT')).pack(side='left', padx=3)",
            "tk.Button(buttons, text='Deny', command=lambda: record('DENY')).pack(side='left', padx=3)",
            "tk.Button(buttons, text='Request Revision', command=lambda: record('REQUEST_REVISION')).pack(side='left', padx=3)",
            "tk.Button(buttons, text='Dismiss Without Decision', command=lambda: record('DISMISS')).pack(side='left', padx=3)",
            "status = tk.Label(root, text='Awaiting operator decision', padx=12, pady=6)",
            "status.pack()",
            "root.mainloop()",
        )),
        encoding="utf-8",
    )
    proc = subprocess.Popen([os.sys.executable, str(script)], cwd=str(package_root), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return {**payload, "popup_created": True, "popup_pid": proc.pid, "mode": "persistent", "clipboard_summary_available": True}


def live44_record_operator_decision(package_root: str, *, action: str, note: str = "") -> dict[str, Any]:
    state_path = Path(package_root) / "decision_state.json"
    state = json.loads(state_path.read_text(encoding="utf-8"))
    prior = state["state"]
    transitions = {"ACCEPT": "accepted", "DENY": "denied", "REQUEST_REVISION": "revision_requested", "DISMISS": "pending_operator_review"}
    new_state = transitions[action]
    result = {
        "decision_id": state["decision_id"],
        "prior_state": prior,
        "new_state": new_state,
        "exact_operator_action": action,
        "exact_authorized_scope": "one bounded isolated transition" if new_state == "accepted" else "",
        "approved_budget": {"provider_calls": 0, "local_actions": 1} if new_state == "accepted" else {},
        "operator_note": note,
        "timestamp": utc_now(),
        "checkpoint": json.loads((Path(package_root) / "resume_checkpoint.json").read_text(encoding="utf-8")),
        "artifact_digest": "",
    }
    result["artifact_digest"] = _live41_digest(result)
    _live44_write_json(Path(package_root) / "decision_result.json", result)
    _live44_write_json(state_path, {"decision_id": state["decision_id"], "state": new_state})
    return result


def live44_create_evidence_backed_revision(campaign_root: str, *, original_decision_id: str, operator_note: str) -> dict[str, Any]:
    root = Path(campaign_root)
    original_root = root / "operator_decisions" / original_decision_id
    if not original_root.exists():
        return {"accepted": False, "reason": "original_decision_not_found", "original_decision_id": original_decision_id}
    decision_state = json.loads((original_root / "decision_state.json").read_text(encoding="utf-8"))
    if decision_state.get("state") != "revision_requested":
        return {"accepted": False, "reason": "original_decision_not_in_revision_requested", "state": decision_state.get("state")}
    provider_responses = json.loads((root / "provider_response_ledger.json").read_text(encoding="utf-8")).get("responses", [])
    provider_requests = json.loads((root / "provider_request_ledger.json").read_text(encoding="utf-8")).get("requests", [])
    original_request = json.loads((original_root / "decision_request.json").read_text(encoding="utf-8"))
    response = provider_responses[0] if provider_responses else {}
    useful_request = provider_requests[0] if provider_requests else {}
    selected_objective = next(iter(response.get("candidate_objectives", ())), "")
    exact_evidence_spans = tuple(useful_request.get("exact_evidence_spans", ()))
    missing_fields = []
    if not selected_objective:
        missing_fields.append("exact_provider_selected_objective")
    if not any("held-out" in span.lower() or "transfer" in span.lower() for span in exact_evidence_spans):
        missing_fields.append("specific_validation_weakness")
    if not useful_request.get("reason_deterministic_logic_is_insufficient"):
        missing_fields.append("deterministic_insufficiency_reason")
    exact_case_records_available = any("case" in span.lower() or "metric" in span.lower() or "failed" in span.lower() for span in exact_evidence_spans)
    if not exact_case_records_available:
        missing_fields.append("failing_case_ids_or_metrics")
    revised_action = (
        "compile exact local failing-case evidence before implementation"
        if missing_fields
        else "execute narrowed isolated candidate after evidence-backed authorization"
    )
    decision_id = stable_id("live44-revised-decision", original_decision_id, selected_objective, tuple(missing_fields), operator_note)
    package_root = root / "operator_decisions" / decision_id
    package_root.mkdir(parents=True, exist_ok=True)
    revised = {
        "decision_id": decision_id,
        "supersedes_decision_id": original_decision_id,
        "campaign_id": original_request["campaign_id"],
        "cycle_id": original_request["cycle_id"],
        "decision_type": "revision_evidence_compilation_required" if missing_fields else "revision_evidence_backed_implementation",
        "state": "pending_operator_review",
        "operator_revision_note": operator_note,
        "requested_action": revised_action,
        "recommended_choice": "Accept local evidence compilation" if missing_fields else "Accept narrowed isolated candidate",
        "exact_provider_selected_objective": selected_objective,
        "specific_validation_weakness": {
            "description": "transfer/frontier shallowness is indicated but exact failing case IDs or metrics are not present in the current package",
            "case_ids_or_metrics_present": exact_case_records_available,
            "source": "provider_request_ledger.exact_evidence_spans",
        },
        "local_evidence_records": tuple(exact_evidence_spans),
        "provider_response_excerpt": {
            "candidate_objectives": response.get("candidate_objectives", ()),
            "rationale": response.get("rationale", ""),
            "risk": response.get("risk", ""),
            "response_id": response.get("response_id", ""),
        },
        "deterministic_insufficiency_analysis": useful_request.get("reason_deterministic_logic_is_insufficient", ""),
        "proposed_isolated_candidate_behavior": (
            "preserve a local-only evidence acquisition branch that identifies exact held-out, adversarial, control, and transfer records before any implementation"
            if missing_fields
            else "validate a provider-ranked objective in an isolated candidate without tracked-source application"
        ),
        "focused_success_criteria": (
            "records exact failing case IDs or metrics",
            "links every claimed weakness to a local evidence artifact",
            "does not consume another provider call",
        ),
        "held_out_adversarial_control_transfer_checks": {
            "held_out": "must cite exact held-out record before implementation",
            "adversarial": "must cite exact adversarial record before implementation",
            "control": "must cite exact unrelated-control record before implementation",
            "transfer": "must cite exact transfer record before implementation",
        },
        "rollback_condition": "rollback or reject if evidence compilation cannot identify exact failing records without new authority",
        "duplicate_overlap_check": {
            "existing_capabilities_checked": ("LIVE-42 frontier expansion", "LIVE-43 contradiction/source composition"),
            "overlap_risk": "medium until exact failing records identify whether the objective is novel",
            "duplicate_decision": "implementation authorization denied until overlap analysis is complete",
        },
        "estimated_local_actions_required": 2 if missing_fields else 1,
        "expected_information_gain": 0.62 if missing_fields else 0.74,
        "provider_calls_added": 0,
        "missing_fields": tuple(missing_fields),
        "authority_boundary": "no implementation, application, activation, provider call, source call, Git, or deployment authority is granted by this revision",
        "resume_conditions": ("operator accepts local evidence compilation", "operator denies branch", "operator requests narrower revision"),
        "artifact_root": str(root),
        "current_checkpoint": original_request["current_checkpoint"],
    }
    summary = "\n".join((
        "DELTA LIVE-44 REVISED OPERATOR DECISION",
        "",
        f"Campaign: {revised['campaign_id']}",
        f"Original decision: {original_decision_id}",
        f"Revised decision: {decision_id}",
        f"Requested action: {revised_action}",
        "",
        f"Exact provider-selected objective: {selected_objective or 'missing'}",
        f"Specific validation weakness: {revised['specific_validation_weakness']['description']}",
        f"Local evidence records: {list(exact_evidence_spans)}",
        f"Provider response excerpt: {revised['provider_response_excerpt']}",
        f"Why deterministic local derivation was insufficient: {revised['deterministic_insufficiency_analysis']}",
        f"Proposed isolated candidate behavior: {revised['proposed_isolated_candidate_behavior']}",
        f"Success criteria: {list(revised['focused_success_criteria'])}",
        f"Checks: {revised['held_out_adversarial_control_transfer_checks']}",
        f"Rollback condition: {revised['rollback_condition']}",
        f"Duplicate/overlap check: {revised['duplicate_overlap_check']}",
        f"Estimated local actions: {revised['estimated_local_actions_required']}",
        "",
        "No additional provider call was made.",
    ))
    for name, payload in (
        ("decision_request.json", revised),
        ("revision_evidence_packet.json", revised),
        ("provider_usage.json", {"provider_calls_added": 0, "provider_calls_total": json.loads((root / "provider_budget.json").read_text(encoding="utf-8")).get("provider_calls", 0)}),
        ("affected_scope.json", {"affected_files": (), "affected_state": "local_evidence_compilation_only"}),
        ("recommended_action.json", {"recommended_choice": revised["recommended_choice"]}),
        ("decision_state.json", {"decision_id": decision_id, "state": "pending_operator_review"}),
        ("resume_checkpoint.json", {"checkpoint": original_request["current_checkpoint"]}),
    ):
        _live44_write_json(package_root / name, payload)
    (package_root / "decision_summary.txt").write_text(summary, encoding="utf-8")
    ledger_path = root / "operator_decision_ledger.json"
    ledger = json.loads(ledger_path.read_text(encoding="utf-8")) if ledger_path.exists() else {"decisions": []}
    ledger["decisions"] = tuple(dict.fromkeys(tuple(ledger.get("decisions", ())) + (decision_id,)))
    _live44_write_json(ledger_path, ledger)
    return {**revised, "accepted": True, "package_root": str(package_root), "review_summary": summary}


def live44_deny_incomplete_revision(campaign_root: str, *, decision_id: str, reason: str = "decision_package_remained_incomplete_after_revision") -> dict[str, Any]:
    root = Path(campaign_root)
    package_root = root / "operator_decisions" / decision_id
    if not package_root.exists():
        return {"accepted": False, "reason": "decision_not_found", "decision_id": decision_id}
    decision = json.loads((package_root / "decision_request.json").read_text(encoding="utf-8"))
    completeness = live44_decision_package_completeness(decision)
    if completeness["complete"]:
        return {"accepted": False, "reason": "decision_package_complete", "decision_id": decision_id}
    signature = stable_id(
        "live44-consumed-proposal",
        decision.get("exact_provider_selected_objective", decision.get("requested_action", "")),
        decision.get("provider_response_excerpt", {}),
        decision.get("local_evidence_records", ()),
    )
    denial = {
        "decision_id": decision_id,
        "new_state": "denied",
        "reason": reason,
        "proposal_signature": signature,
        "proposal_signature_consumed": True,
        "popup_recreation_allowed": False,
        "provider_retry_allowed": False,
        "provider_calls_added": 0,
        "missing_fields": completeness["missing_fields"],
        "next_allowed_transition": "derive_narrower_local_only_branch_or_select_materially_different_episode",
        "timestamp": utc_now(),
    }
    _live44_write_json(package_root / "internal_denial.json", denial)
    _live44_write_json(package_root / "decision_state.json", {"decision_id": decision_id, "state": "denied"})
    consumed_path = root / "consumed_proposal_signatures.json"
    consumed = json.loads(consumed_path.read_text(encoding="utf-8")) if consumed_path.exists() else {"signatures": []}
    consumed["signatures"] = tuple(dict.fromkeys(tuple(consumed.get("signatures", ())) + (signature,)))
    _live44_write_json(consumed_path, consumed)
    return denial


def live44_proposal_signature_available(campaign_root: str, proposal: Mapping[str, Any]) -> dict[str, Any]:
    root = Path(campaign_root)
    signature = stable_id(
        "live44-consumed-proposal",
        proposal.get("exact_provider_selected_objective", proposal.get("requested_action", "")),
        proposal.get("provider_response_excerpt", {}),
        proposal.get("local_evidence_records", ()),
    )
    consumed_path = root / "consumed_proposal_signatures.json"
    consumed = json.loads(consumed_path.read_text(encoding="utf-8")) if consumed_path.exists() else {"signatures": []}
    available = signature not in set(consumed.get("signatures", ()))
    return {"available": available, "signature": signature, "decision": "allowed" if available else "denied_duplicate_consumed_signature"}


def run_live44_episode_campaign_pilot(*, artifact_root: str = ".tmp/live44", campaign_id: str = "live44-episode-pilot", starting_checkpoint: str = "543e8821", max_episodes: int = 3, popup_mode: str = "test") -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    campaign = make_live44_campaign(campaign_id=campaign_id, starting_checkpoint=starting_checkpoint)
    spans = ("LIVE-43 retained a scope-difference comparison capability", "LIVE-42 generated multiple frontier candidates but shallow episodes often exhausted quickly")
    cycle_id = stable_id("live44-cycle", campaign_id, "provider-value")
    useful_request = _live44_make_provider_request(campaign, cycle_id=cycle_id, provider_role="objective proposal", unresolved_question="Which evidence-grounded objective is most likely to deepen frontier exploration after shallow exhaustion?", evidence_spans=spans, downstream_consumer="admissibility_for_isolated_candidate")
    _live44_write_json(root / "provider_call_request.json", useful_request)
    gate = live44_provider_value_gate(campaign, useful_request)
    response = _live44_provider_stub_response(campaign, useful_request) if gate["accepted"] else {}
    evaluation = _live44_evaluate_provider_response(useful_request, response, downstream_transition_completed=bool(response))
    campaign["provider_value_counts"][evaluation["value_classification"]] += 1
    campaign["local_actions"] += 1
    campaign["completed_episodes"] += 1
    campaign["completed_productive_cycles"] += 1
    campaign["exploration_history"].append({"episode": 1, "strategy": "provider-assisted-frontier-ranking", "productive_cycles": 1, "terminal_reason": "operator_decision_required_for_isolated_action"})
    filler = _live44_make_provider_request(campaign, cycle_id="filler-cycle", provider_role="diagnosis", unresolved_question="What should I do next?", evidence_spans=(), downstream_consumer="", requested_output="ideas", expected_information_gain=0.1, confidence_call_is_useful=0.1)
    filler_gate = live44_provider_value_gate(campaign, filler)
    duplicate = _live44_make_provider_request(campaign, cycle_id=cycle_id, provider_role="objective proposal", unresolved_question=useful_request["unresolved_question"], evidence_spans=spans, downstream_consumer="admissibility_for_isolated_candidate")
    duplicate_gate = live44_provider_value_gate(campaign, duplicate)
    checkpoint = _live44_checkpoint(root, campaign, latest_artifact=str(root / "provider_call_request.json"))
    decision = _live44_operator_decision_package(root, campaign, cycle_id=cycle_id, decision_type="implementation_with_elevated_risk", requested_action="execute one isolated candidate based on provider-ranked objective", provider_usage={"provider_calls": campaign["provider_calls"], "token_usage": response.get("token_usage", {})}, checkpoint=checkpoint)
    prepared = (
        {"popup": _live44_launch_decision_popup(decision, mode=popup_mode), "completeness": {"complete": False, "decision_ready_for_operator": False}, "internal_resolution": None}
        if popup_mode == "test"
        else live44_prepare_operator_popup_or_internal_resolution(root, campaign, decision, provider_response=response, provider_request=useful_request, popup_mode=popup_mode)
    )
    popup = prepared["popup"]
    dismiss: Mapping[str, Any] = {}
    denial: Mapping[str, Any] = {}
    revision: Mapping[str, Any] = {}
    accepted: Mapping[str, Any] = {}
    revision_decision: Mapping[str, Any] = {}
    accept_decision: Mapping[str, Any] = {}
    execution = {"executed": False, "authorization_consumed": False, "reuse_denied": True, "tracked_source_application": False, "result": "pending_operator_decision"}
    if popup_mode == "test":
        dismiss = live44_record_operator_decision(decision["package_root"], action="DISMISS", note="automation-safe test preserves pending state")
        denial = live44_record_operator_decision(decision["package_root"], action="DENY", note="derive narrower alternative")
        revision_decision = _live44_operator_decision_package(root, campaign, cycle_id=cycle_id, decision_type="revised_lower_risk_implementation", requested_action="execute narrower local-only isolated validation", provider_usage={"provider_calls": campaign["provider_calls"], "token_usage": {}}, checkpoint=checkpoint)
        revision = live44_record_operator_decision(revision_decision["package_root"], action="REQUEST_REVISION", note="strengthen tests")
        accept_decision = _live44_operator_decision_package(root, campaign, cycle_id=cycle_id, decision_type="accepted_local_only_implementation", requested_action="execute one narrower local-only validation", provider_usage={"provider_calls": campaign["provider_calls"], "token_usage": {}}, checkpoint=checkpoint)
        accepted = live44_record_operator_decision(accept_decision["package_root"], action="ACCEPT", note="bounded pilot authorization")
        execution = {"executed": accepted["new_state"] == "accepted", "authorization_consumed": True, "reuse_denied": True, "tracked_source_application": False, "result": "narrower local-only alternative validated"}
    _live44_write_json(root / "execution_evidence.json", execution)
    for episode in range(2, max_episodes + 1):
        campaign["completed_episodes"] += 1
        campaign["exploration_history"].append({"episode": episode, "strategy": "materially-distinct-local-exploration", "productive_cycles": 0, "terminal_reason": "episode_exhausted_without_campaign_completion"})
    if popup_mode == "test":
        campaign["campaign_state"] = "paused_pending_operator_review"
        campaign["pending_decision_id"] = accept_decision["decision_id"] if accept_decision else decision["decision_id"]
    paused = {
        "campaign": campaign,
        "provider_request": useful_request,
        "provider_gate": gate,
        "provider_response": response,
        "provider_evaluation": evaluation,
        "filler_gate": filler_gate,
        "duplicate_gate": duplicate_gate,
        "operator_decisions": tuple(item for item in (decision, revision_decision, accept_decision) if item),
        "decision_results": tuple(item for item in (dismiss, denial, revision, accepted) if item),
        "execution": execution,
        "decision_completeness": prepared["completeness"],
        "internal_resolution": prepared["internal_resolution"],
    }
    artifacts = {
        "paused_status.json": {"campaign": campaign, "pending_decision_id": campaign["pending_decision_id"]},
        "campaign_summary.json": {"target_episodes": 200, "pilot_episodes": max_episodes, "completed_productive_cycles": campaign["completed_productive_cycles"]},
        "cycle_ledger.json": {"episodes": campaign["exploration_history"]},
        "provider_request_ledger.json": {"requests": (useful_request, filler, duplicate)},
        "provider_response_ledger.json": {"responses": (response,)},
        "provider_value_ledger.json": {"evaluations": (evaluation,)},
        "provider_budget.json": {"provider_calls": campaign["provider_calls"], "soft_budget": campaign["provider_soft_budget"], "hard_ceiling": campaign["provider_hard_ceiling"]},
        "operator_decision_ledger.json": {"decisions": tuple(item["decision_id"] for item in (decision, revision_decision, accept_decision) if item)},
        "restart_state.json": {"pending_decision_preserved": True, "provider_cache_preserved": True, "completed_cycles_not_recounted": True},
        "popup_status.json": popup,
        "resource_summary.json": {"local_actions": campaign["local_actions"], "provider_calls": campaign["provider_calls"]},
    }
    written = {name: _live44_write_json(root / name, payload) for name, payload in artifacts.items()}
    review = {
        "classification": "LIVE_44_GOVERNED_PROVIDER_LOOP_READY_WITH_LIMITS",
        "live43_frozen": True,
        "provider_value_gate_active": gate["accepted"] and not filler_gate["accepted"],
        "duplicate_denied_or_cached": duplicate_gate["accepted"] is False and "duplicate_request_cache_available" in duplicate_gate["reasons"],
        "provider_output_advisory": response.get("advisory_only") is True,
        "call_value_assessed": evaluation["value_classification"] in {"high_value", "useful"},
        "operator_package_complete": all((Path(decision["package_root"]) / name).exists() for name in ("decision_request.json", "decision_summary.txt", "evidence_manifest.json", "decision_state.json")),
        "dismiss_preserves_pending": dismiss.get("new_state") == "pending_operator_review" if dismiss else popup_mode == "persistent",
        "deny_derives_narrower_alternative": denial.get("new_state") == "denied" and revision_decision.get("decision_type") == "revised_lower_risk_implementation" if denial else popup_mode == "persistent",
        "revision_supersedes_path": revision.get("new_state") == "revision_requested" if revision else popup_mode == "persistent",
        "accept_exact_single_use": accepted.get("new_state") == "accepted" and execution["reuse_denied"] if accepted else popup_mode == "persistent",
        "episode_exhaustion_not_campaign_completion": campaign["completed_episodes"] >= max_episodes and campaign["campaign_state"] in {"paused_pending_operator_review", "local_enrichment_required", "branch_denied_internal"},
    }
    review_artifact = _live44_write_json(root / "final_review.json", review)
    return {**paused, "artifact_root": str(root), "classification": review["classification"], "review": review, "review_artifact": review_artifact, "written_artifacts": written}


def make_live44_detached_launcher(*, repository_root: str, artifact_root: str, campaign_id: str, starting_checkpoint: str = "543e8821") -> dict[str, Any]:
    repo = Path(repository_root).resolve()
    if not (repo / "orchestration" / "runtime" / "gsr_a_governed_self_regulation.py").exists() or repo.name != "Delta_Dev":
        return {"accepted": False, "reason": "repository_root_invalid"}
    root = Path(artifact_root).resolve() / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    launcher = root / "launch_live44.py"
    launcher.write_text(
        "\n".join((
            "from pathlib import Path",
            "import sys",
            f"repo = Path({str(repo)!r}).resolve()",
            "if str(repo) not in sys.path:",
            "    sys.path.insert(0, str(repo))",
            "from orchestration.runtime.gsr_a_governed_self_regulation import run_live44_episode_campaign_pilot",
            "run_live44_episode_campaign_pilot(",
            f"    artifact_root={str(Path(artifact_root).resolve())!r},",
            f"    campaign_id={campaign_id!r},",
            f"    starting_checkpoint={starting_checkpoint!r},",
            "    max_episodes=10,",
            "    popup_mode='persistent',",
            ")",
            "",
        )),
        encoding="utf-8",
    )
    return {"accepted": True, "reason": "launcher_created", "campaign_id": campaign_id, "artifact_root": str(Path(artifact_root).resolve()), "launcher_path": str(launcher), "stdout_path": str(root / "stdout.log"), "stderr_path": str(root / "stderr.log")}


def _live37_scheduler_decision(*, eligible_work: bool, blocked: bool, waiting_external: bool, retry_backoff: bool, checkpoint_due: bool) -> str:
    if eligible_work:
        return "execute_next"
    if checkpoint_due:
        return "checkpoint"
    if blocked:
        return "sleep_blocked"
    if waiting_external:
        return "sleep_waiting_external"
    if retry_backoff:
        return "sleep_retry_backoff"
    return "sleep_idle"


def _live37_sleep_interruptible(duration_seconds: float, emergency_stop: Path) -> bool:
    deadline = time.monotonic() + max(0.0, duration_seconds)
    while time.monotonic() < deadline:
        if emergency_stop.exists() and "STOP" in emergency_stop.read_text(encoding="utf-8", errors="ignore"):
            return True
        time.sleep(min(1.0, max(0.0, deadline - time.monotonic())))
    return emergency_stop.exists() and "STOP" in emergency_stop.read_text(encoding="utf-8", errors="ignore")


def _live37_write_checkpoint(root: Path, state: dict[str, Any], checkpoint_type: str) -> dict[str, Any]:
    sequence = int(state.get("checkpoint_sequence", 0)) + 1
    checkpoint = {
        "campaign_id": state["campaign_id"],
        "runtime_id": state["runtime_id"],
        "parent_mission": state["parent_mission"],
        "checkpoint_type": checkpoint_type,
        "sequence": sequence,
        "created_wall_time": utc_now(),
        "monotonic_elapsed_seconds": round(time.monotonic() - float(state["monotonic_start"]), 3),
        "objective_graph": state.get("objectives", []),
        "candidate_states": state.get("candidates", []),
        "completed_evidence": state.get("completed_evidence", []),
        "pending_questions": state.get("pending_questions", []),
        "source_ledger": state.get("source_ledger", []),
        "provider_ledger": state.get("provider_ledger", []),
        "tool_ledger": state.get("tool_ledger", []),
        "authorizations": state.get("authorization_ledger", []),
        "cumulative_budgets": state.get("budgets", {}),
        "adaptive_resource_envelope": state.get("adaptive_resource_envelope", {}),
        "resource_action_ledger": state.get("resource_action_ledger", []),
        "objective_envelopes": state.get("objective_envelopes", {}),
        "campaign_resource_counts": state.get("campaign_resource_counts", {}),
        "resource_saturation": state.get("resource_saturation", {}),
        "capability_map": state.get("capability_map", {}),
        "next_eligible_action": state.get("next_eligible_action", ""),
    }
    checkpoint["integrity_digest"] = _live37_digest(checkpoint)
    state["checkpoint_sequence"] = sequence
    state["last_checkpoint_id"] = stable_id("live37-checkpoint", state["campaign_id"], sequence, checkpoint["integrity_digest"])
    checkpoints_path = root / "checkpoints.jsonl"
    checkpoints_path.parent.mkdir(parents=True, exist_ok=True)
    with checkpoints_path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(checkpoint, sort_keys=True) + "\n")
    _live37_atomic_write_json(root / "status.json", state)
    return checkpoint


def run_live37_twelve_hour_campaign_process(
    *,
    artifact_root: str = ".tmp/live37",
    campaign_id: str | None = None,
    target_duration_seconds: float = 12 * 60 * 60,
    minimum_duration_seconds: float = 11 * 60 * 60 + 45 * 60,
    hard_duration_seconds: float = 12 * 60 * 60 + 15 * 60,
    checkpoint_interval_seconds: float = 15 * 60,
) -> dict[str, Any]:
    campaign = campaign_id or stable_id("live37-campaign", utc_now(), os.getpid())
    root = Path(artifact_root) / campaign
    root.mkdir(parents=True, exist_ok=True)
    emergency_stop = root / "EMERGENCY_STOP"
    emergency_stop.write_text("READY\n", encoding="utf-8")
    start_wall = utc_now()
    start_mono = time.monotonic()
    state: dict[str, Any] = {
        "campaign_id": campaign,
        "runtime_id": stable_id("live37-runtime", campaign, os.getpid()),
        "process_id": os.getpid(),
        "parent_mission": LIVE37_PARENT_MISSION,
        "start_wall_time": start_wall,
        "monotonic_start": start_mono,
        "target_deadline_seconds": target_duration_seconds,
        "hard_deadline_seconds": hard_duration_seconds,
        "minimum_duration_seconds": minimum_duration_seconds,
        "delegation_identity": stable_id("live37-delegation", campaign),
        "current_objective": "baseline benchmark",
        "active_candidate": "",
        "queued_candidates": [],
        "completed_candidates": [],
        "objectives": [],
        "candidates": [],
        "checkpoint_sequence": 0,
        "source_ledger": [],
        "provider_ledger": [],
        "tool_ledger": [],
        "authorization_ledger": [],
        "developmental_ledger": [],
        "completed_evidence": [],
        "pending_questions": [],
        "budgets": {"tool_calls": 0, "provider_requests": 0, "provider_attempts": 0, "source_retrievals": 0, "output_bytes": 0, "disk_bytes": 0, "repair_iterations": 0},
        "adaptive_resource_envelope": {
            "per_objective_limits": dict(LIVE37_PER_OBJECTIVE_LIMITS),
            "global_limits": dict(LIVE37_GLOBAL_LIMITS),
            "provider_task_limit": LIVE37_PROVIDER_TASK_LIMIT,
            "band_rules": {"normal": "1-20", "extended": "21-50", "deep": "51-100"},
            "saturation_rule": "five consecutive no-new-evidence actions stop the objective",
        },
        "objective_envelopes": {},
        "objective_aliases": {},
        "resource_action_ledger": [],
        "resource_action_digests": [],
        "campaign_resource_counts": {"total": 0, "local": 0, "source": 0, "provider": 0},
        "provider_task_counts": {},
        "resource_denials": [],
        "resource_saturation": {},
        "stagnation_state": "none",
        "drift_state": "none",
        "emergency_stop_path": str(emergency_stop),
        "final_disposition": "running",
        "next_eligible_action": "baseline benchmark",
        "phase_times": {"active": 0.0, "diagnostic": 0.0, "implementation": 0.0, "validation": 0.0, "tool": 0.0, "paused": 0.0, "blocked": 0.0, "restart": 0.0, "final_review": 0.0},
    }
    _live37_write_checkpoint(root, state, "campaign_start")
    state["current_objective"] = "multi-objective substantive continuation"
    continuation = run_live37_multi_objective_continuation_pilot(
        artifact_root=str(root / "mo"),
        pilot_id="cont",
        minimum_objectives=3,
    )
    state["capability_map"] = continuation["capability_map"]
    state["campaign_resource_counts"] = dict(continuation["resource_counts"])
    state["resource_action_ledger"] = list(continuation["resource_action_ledger"])
    state["objectives"] = [
        {
            "objective_id": stable_id("live37-objective", campaign, item["gap_id"]),
            "gap": item["gap_id"],
            "state": item["status"],
            "capability_identity": item["capability_identity"],
            "report_path": item["report_path"],
            "raw_artifact_root": item["raw_artifact_root"],
        }
        for item in continuation["capability_map"]["evaluated_capabilities"]
    ]
    state["candidates"] = [
        {
            "candidate_id": item["capability_identity"],
            "state": item["status"],
            "scope": item["raw_artifact_root"],
            "report_path": item["report_path"],
        }
        for item in continuation["capability_map"]["evaluated_capabilities"]
    ]
    state["completed_candidates"] = [
        {
            "candidate_id": item["capability_identity"],
            "disposition": item["status"],
            "baseline_score": item["baseline_score"],
            "latest_score": item["latest_score"],
            "raw_artifact_root": item["raw_artifact_root"],
            "report_path": item["report_path"],
            "known_limits": list(item["unresolved_limitations"]),
        }
        for item in continuation["capability_map"]["evaluated_capabilities"]
    ]
    raw_count = sum(len(list(Path(raw_root).rglob("*.json"))) for raw_root in continuation["raw_artifact_roots"])
    state["completed_evidence"].append({
        "type": "multi_objective_continuation",
        "classification": continuation["classification"],
        "review_path": continuation["review_path"],
        "review_digest": continuation["review_digest"],
        "objective_count": continuation["objective_count"],
        "objective_keys": continuation["objective_keys"],
        "raw_artifact_roots": continuation["raw_artifact_roots"],
        "raw_output_count": raw_count,
        "retained_count": continuation["retained_count"],
        "rejected_or_deferred_count": continuation["rejected_or_deferred_count"],
        "next_ranked_gap": continuation["next_ranked_gap"],
    })
    state["budgets"]["tool_calls"] = state["campaign_resource_counts"]["local"]
    state["budgets"]["output_bytes"] += sum(path.stat().st_size for path in (root / "mo").rglob("*") if path.is_file())
    state["current_objective"] = "multi-objective substantive continuation complete"
    state["next_eligible_action"] = f"next objective candidate: {continuation['next_ranked_gap']}" if continuation["next_ranked_gap"] else "periodic checkpoint"
    _live37_write_checkpoint(root, state, "multi_objective_continuation_complete")
    last_checkpoint = time.monotonic()
    restart_done = False
    while True:
        now = time.monotonic()
        elapsed = now - start_mono
        if emergency_stop.exists() and "STOP" in emergency_stop.read_text(encoding="utf-8", errors="ignore"):
            state["final_disposition"] = "emergency_stop"
            break
        if elapsed >= hard_duration_seconds:
            state["final_disposition"] = "hard_deadline"
            break
        if elapsed >= target_duration_seconds and elapsed >= minimum_duration_seconds:
            state["final_disposition"] = "target_deadline"
            break
        state["stagnation_state"] = "none"
        if not restart_done and elapsed >= 3 * 60 * 60:
            _live37_write_checkpoint(root, state, "before_runtime_reconstruction")
            state["runtime_id"] = stable_id("live37-runtime-reconstructed", campaign, state["last_checkpoint_id"])
            state["phase_times"]["restart"] += 1.0
            restart_done = True
            _live37_write_checkpoint(root, state, "after_runtime_reconstruction")
        if now - last_checkpoint >= checkpoint_interval_seconds:
            _live37_write_checkpoint(root, state, "periodic")
            last_checkpoint = now
        remaining_to_target = max(0.1, target_duration_seconds - elapsed)
        idle_sleep = min(60.0, max(0.1, checkpoint_interval_seconds / 10), remaining_to_target)
        if _live37_sleep_interruptible(idle_sleep, emergency_stop):
            state["final_disposition"] = "emergency_stop"
            break
    state["end_wall_time"] = utc_now()
    state["monotonic_end"] = time.monotonic()
    state["monotonic_elapsed_seconds"] = round(state["monotonic_end"] - start_mono, 3)
    if state["monotonic_elapsed_seconds"] < minimum_duration_seconds and state["final_disposition"] not in {"emergency_stop", "hard_deadline"}:
        state["final_disposition"] = "incomplete_productive_work_exhausted"
    state["budgets"]["disk_bytes"] = sum(path.stat().st_size for path in root.rglob("*") if path.is_file())
    _live37_write_checkpoint(root, state, "final_stop")
    return state


def read_live37_campaign_status(artifact_root: str, campaign_id: str) -> dict[str, Any]:
    status = Path(artifact_root) / campaign_id / "status.json"
    if not status.exists():
        return {"accepted": False, "reason": "status_missing", "campaign_id": campaign_id}
    payload = json.loads(status.read_text(encoding="utf-8"))
    payload["accepted"] = True
    payload["status_path"] = str(status)
    return payload


def make_live37_detached_launcher(
    *,
    repository_root: str,
    artifact_root: str,
    campaign_id: str,
    target_duration_seconds: float = 12 * 60 * 60,
    minimum_duration_seconds: float = 11 * 60 * 60 + 45 * 60,
    hard_duration_seconds: float = 12 * 60 * 60 + 15 * 60,
) -> dict[str, Any]:
    repo = Path(repository_root).resolve()
    if not (repo / "orchestration" / "runtime" / "gsr_a_governed_self_regulation.py").exists():
        return {"accepted": False, "reason": "repository_root_missing_runtime", "repository_root": str(repo)}
    if repo.name != "Delta_Dev":
        return {"accepted": False, "reason": "repository_root_substitution_denied", "repository_root": str(repo)}
    root = Path(artifact_root).resolve() / campaign_id
    root.mkdir(parents=True, exist_ok=True)
    launcher = root / "launch_live37.py"
    launcher.write_text(
        "\n".join(
            (
                "from pathlib import Path",
                "import sys",
                f"# repository_root={str(repo)}",
                f"repo = Path({str(repo)!r}).resolve()",
                "if str(repo) not in sys.path:",
                "    sys.path.insert(0, str(repo))",
                "from orchestration.runtime.gsr_a_governed_self_regulation import run_live37_twelve_hour_campaign_process",
                "run_live37_twelve_hour_campaign_process(",
                f"    artifact_root={str(Path(artifact_root).resolve())!r},",
                f"    campaign_id={campaign_id!r},",
                f"    target_duration_seconds={float(target_duration_seconds)!r},",
                f"    minimum_duration_seconds={float(minimum_duration_seconds)!r},",
                f"    hard_duration_seconds={float(hard_duration_seconds)!r},",
                ")",
                "",
            )
        ),
        encoding="utf-8",
    )
    return {
        "accepted": True,
        "reason": "launcher_created",
        "repository_root": str(repo),
        "artifact_root": str(Path(artifact_root).resolve()),
        "campaign_id": campaign_id,
        "launcher_path": str(launcher),
        "stdout_path": str(root / "stdout.log"),
        "stderr_path": str(root / "stderr.log"),
        "import_path_method": "temporary_launcher_sys_path_repo_root",
    }


def validate_live37_first_checkpoint(*, artifact_root: str, campaign_id: str) -> dict[str, Any]:
    root = Path(artifact_root) / campaign_id
    status_path = root / "status.json"
    checkpoints_path = root / "checkpoints.jsonl"
    if not status_path.exists() or not checkpoints_path.exists():
        return {"accepted": False, "reason": "status_or_checkpoint_missing"}
    status = json.loads(status_path.read_text(encoding="utf-8"))
    first_line = checkpoints_path.read_text(encoding="utf-8").splitlines()[0]
    checkpoint = json.loads(first_line)
    digest_payload = dict(checkpoint)
    digest = str(digest_payload.pop("integrity_digest", ""))
    return {
        "accepted": bool(digest) and checkpoint.get("parent_mission") == LIVE37_PARENT_MISSION and status.get("parent_mission") == LIVE37_PARENT_MISSION,
        "reason": "first_checkpoint_validated",
        "status_path": str(status_path),
        "checkpoint_path": str(checkpoints_path),
        "checkpoint_digest_present": bool(digest),
        "parent_mission_exact": checkpoint.get("parent_mission") == LIVE37_PARENT_MISSION,
        "checkpoint_sequence": checkpoint.get("sequence"),
        "current_objective": status.get("current_objective"),
        "final_disposition": status.get("final_disposition"),
    }


